import type { Prompt } from "../prompt-types";

export const LEARNING_PROMPTS: Prompt[] = [
  // ---- Learning (1025) ----
  { id: "learning-1", title: "Study timetable for a student", category: "learning", text: "Make a daily study timetable for a Class [9/10/12] student in India who has school from [time] to [time]. Include study blocks, breaks, revision, and one hour of play. Keep it realistic, not a 14-hour plan." },
  { id: "learning-2", title: "Explain like I'm 12", category: "learning", text: "Explain [topic, e.g. how a fridge works / what GST is] to me as if I am 12 years old. Use very simple words, one everyday example, and no jargon. End with 3 quick questions to check I understood." },
  { id: "learning-3", title: "Exam revision plan for 30 days", category: "learning", text: "I have board exams in 30 days and 5 subjects: [list them]. Make a day-by-day revision plan that covers every subject twice, with Sundays for mock tests and one rest evening a week." },
  { id: "learning-4", title: "Help with a maths problem", category: "learning", text: "Here is a maths problem I am stuck on: [paste the problem]. Solve it step by step, explaining each step in simple words, and give me one similar problem to try on my own." },
  { id: "learning-5", title: "Science project ideas", category: "learning", text: "Give me 10 science project ideas for a Class [8/9/10] student in India that use materials available at home or a local shop. For each, say the question it answers and what I need to build it." },
  { id: "learning-6", title: "History summary in simple words", category: "learning", text: "Summarise [a history topic, e.g. the freedom movement / the Mughal period] in simple English for a school student. Cover the main events in order, 5 key people, and why it matters today — in under 300 words." },
  { id: "learning-7", title: "English grammar practice", category: "learning", text: "I keep making mistakes with [tenses / articles / prepositions] in English. Explain the rule in simple words with 5 examples, then give me 10 practice sentences to correct, with answers at the end." },
  { id: "learning-8", title: "Learn a new language", category: "learning", text: "I want to learn basic [Hindi / Tamil / Spanish] for daily conversation. Give me a 30-day plan: 10 useful words a week, 5 common sentences, and one fun way to practise each day." },
  { id: "learning-9", title: "Spelling practice for kids", category: "learning", text: "Make a fun spelling practice for a [age]-year-old child using 20 common English words. Include a word list, 3 games to play with the words, and a mini-test with answers." },
  { id: "learning-10", title: "Quiz questions on a topic", category: "learning", text: "Make a 15-question quiz on [topic, e.g. Indian states / the human body] for a school student: 10 multiple-choice questions and 5 one-line answers. Give the answers separately at the end." },
  { id: "learning-11", title: "Flashcards for revision", category: "learning", text: "Turn this lesson into 20 flashcards: [paste your notes or topic]. Each card should have a short question on one side and a one-line answer on the other, covering the most important facts." },
  { id: "learning-12", title: "Essay outline for school", category: "learning", text: "Make an outline for a school essay on [topic]. Give me an introduction idea, 3 main points with one example each, and a conclusion. Keep the language simple enough for a Class 8 student." },
  { id: "learning-13", title: "Presentation for school", category: "learning", text: "Help me plan a 5-minute school presentation on [topic]. Give me the title, 5 slides with one main point each, what to say for each slide, and one question to ask the class at the end." },
  { id: "learning-14", title: "Science experiment at home", category: "learning", text: "Suggest a safe science experiment I can do at home with [vinegar and baking soda / a magnet / water and oil]. Explain what I need, the steps, what will happen, and the science behind it in simple words." },
  { id: "learning-15", title: "Geography facts made easy", category: "learning", text: "Teach me the states of India and their capitals using simple memory tricks. Group them by region, give one fun fact per state, and finish with a 10-question self-test." },
  { id: "learning-16", title: "Learn Excel basics", category: "learning", text: "Teach me Excel basics in one week: Day 1 entering data, Day 2 simple formulas, Day 3 sorting, Day 4 charts, Day 5 a small budget sheet. Give one tiny task to practise each day." },
  { id: "learning-17", title: "Learn to code in a week", category: "learning", text: "I have never coded. Give me a 7-day beginner plan to learn the very basics of coding with free tools: what to learn each day, one small thing to build, and where to practise for free." },
  { id: "learning-18", title: "Learn photography basics", category: "learning", text: "Teach me phone photography basics: light, framing, and focus. Give me 7 daily exercises — one per day for a week — that I can do around my home, with what to look for in each photo." },
  { id: "learning-19", title: "Learn cooking basics", category: "learning", text: "I am a complete beginner in the kitchen. Give me a 7-day plan to learn cooking: Day 1 rice, Day 2 dal, and so on. Each day should teach one skill and end with a meal I can actually eat." },
  { id: "learning-20", title: "Memory techniques for exams", category: "learning", text: "Teach me 5 simple memory techniques for exam revision: one for lists, one for dates, one for long answers, one for formulas, and one for vocabulary. Give a small example of each using my subject: [subject]." },
  { id: "learning-21", title: "Focus tips for studying", category: "learning", text: "I get distracted by my phone while studying. Give me a practical focus plan: how long to study in one stretch, what to do during breaks, how to keep my phone away, and what to do when my mind wanders." },
  { id: "learning-22", title: "Note-making from a chapter", category: "learning", text: "Here is my chapter text: [paste it]. Turn it into short, clear notes: headings, bullet points, and a 5-line summary at the end. Keep only the points likely to come in the exam." },
  { id: "learning-23", title: "Competitive exam study plan", category: "learning", text: "I am preparing for [UPSC / SSC / banking / railway] exams and have 6 months. Make a weekly study plan covering all subjects, with revision days, mock test days, and one rest day a week." },
  { id: "learning-24", title: "Learn useful Hindi phrases", category: "learning", text: "Teach me 20 useful Hindi phrases for daily life in India: greetings, asking directions, shopping, and being polite. Write each phrase in simple Roman letters with its meaning." },
  { id: "learning-25", title: "Book summary in 5 minutes", category: "learning", text: "Summarise the book [title] in simple English: the main idea, 5 key lessons, and who should read it. Keep it under 300 words so I can read it in 5 minutes." },
  { id: "learning-26", title: "Learn Tamil basics for beginners", category: "learning", text: "Teach me Tamil basics for beginners with simple everyday words, greetings, and short sentences I can practise at home. Explain the pronunciation in easy English letters, give me a small daily practice plan, and test me with five simple questions at the end using [my learning goal]." },
  { id: "learning-27", title: "Learn Telugu phrases for travel", category: "learning", text: "Teach me useful Telugu phrases for travel in Andhra Pradesh and Telangana, including asking directions, ordering food, and booking a room. Write each phrase in English letters with its meaning, and add a short practice dialogue for a traveller visiting [city name]." },
  { id: "learning-28", title: "Learn Kannada greetings", category: "learning", text: "Teach me simple Kannada greetings for meeting people in Karnataka, including hello, thank you, please, and goodbye. Show the pronunciation in English letters, explain when to use each greeting, and give me five short sentences to practise every day for [number] days." },
  { id: "learning-29", title: "Learn Malayalam basics", category: "learning", text: "Teach me Malayalam basics for beginners, including common words, greetings, and simple sentences used in Kerala homes and shops. Write everything in English letters with clear pronunciation help, and make a seven-day practice plan for someone learning [minutes] minutes a day." },
  { id: "learning-30", title: "Learn Marathi daily phrases", category: "learning", text: "Teach me Marathi daily phrases for talking with neighbours, shopkeepers, and auto drivers in Maharashtra. Give me greetings, polite requests, and common questions in English letters, plus a short role-play conversation set in [place name] to practise aloud." },
  { id: "learning-31", title: "Learn Bengali basics", category: "learning", text: "Teach me Bengali basics for beginners, including greetings, numbers, and simple sentences for daily life in West Bengal. Explain the pronunciation in English letters, give examples I can use at home, and finish with a small quiz using [topic] as the theme." },
  { id: "learning-32", title: "Learn Gujarati phrases", category: "learning", text: "Teach me useful Gujarati phrases for daily conversation in Gujarat, including greetings, asking for prices, and ordering vegetarian food. Write each phrase in English letters with its meaning, and create a short market dialogue I can practise with [family member]." },
  { id: "learning-33", title: "Learn Punjabi basics", category: "learning", text: "Teach me Punjabi basics for beginners, including greetings, polite words, and simple sentences used in Punjab homes. Explain the pronunciation in English letters, give me a daily practice list, and add five easy questions to test myself after learning [topic]." },
  { id: "learning-34", title: "Learn Urdu basics", category: "learning", text: "Teach me Urdu basics for beginners, including common greetings, polite expressions, and simple sentences for daily conversation. Write the words in English letters with clear pronunciation, and give me a short dialogue between two friends meeting in [city name]." },
  { id: "learning-35", title: "Learn Sanskrit shlokas meaning", category: "learning", text: "Explain the meaning of this Sanskrit shloka in simple English: [shloka text]. Break it word by word, explain its message in everyday language, and give one simple example from daily life in India that shows how to apply it." },
  { id: "learning-36", title: "Improve spoken English at home", category: "learning", text: "Help me improve my spoken English at home with simple daily speaking exercises I can do alone or with family. Give me a 15-minute daily routine, useful sentences for home conversations, and tips to speak slowly and clearly about [daily topic]." },
  { id: "learning-37", title: "Improve English vocabulary daily", category: "learning", text: "Help me improve my English vocabulary with five new useful words every day for [number] days. For each word, give the meaning in simple English, one example sentence from Indian daily life, and a quick way to remember it." },
  { id: "learning-38", title: "Improve English pronunciation", category: "learning", text: "Help me improve my English pronunciation with simple exercises for sounds that Indian learners often find difficult. Give me word lists to practise, tips for mouth and tongue position, and short sentences about [topic] to read aloud every day." },
  { id: "learning-39", title: "Practise English tenses with examples", category: "learning", text: "Teach me English tenses with simple examples from daily life in India, covering past, present, and future in easy words. Give me one clear example for each tense using [verb], then ten fill-in-the-blank sentences for me to practise." },
  { id: "learning-40", title: "Learn reported speech simply", category: "learning", text: "Explain reported speech in simple English with easy examples, showing how to change direct speech into indirect speech. Use everyday Indian examples, explain the tense changes step by step, and give me ten sentences to convert using [person name] as the speaker." },
  { id: "learning-41", title: "Learn active and passive voice", category: "learning", text: "Explain active and passive voice in simple English with clear examples from school and home life in India. Show how to change an active sentence into a passive one, explain when passive voice is useful, and give me ten sentences to practise with [topic]." },
  { id: "learning-42", title: "Learn articles a an the", category: "learning", text: "Teach me when to use a, an, and the in English with simple rules and everyday examples from India. Explain each rule in one short sentence, give five examples for each article, and finish with ten practice sentences about [topic] for me to complete." },
  { id: "learning-43", title: "Learn prepositions with pictures", category: "learning", text: "Teach me English prepositions like in, on, under, beside, and between using simple descriptions of pictures I can imagine at home. Describe a room scene, explain each preposition with an example, and give me ten sentences about [place] to complete correctly." },
  { id: "learning-44", title: "Learn idioms for daily use", category: "learning", text: "Teach me ten common English idioms used in daily conversation, with the meaning of each in simple English and one example sentence from Indian life. Explain when to use each idiom, and give me a short dialogue using five of them about [situation]." },
  { id: "learning-45", title: "Learn phrasal verbs simply", category: "learning", text: "Teach me ten common English phrasal verbs like look after, give up, and turn on, with simple meanings and everyday examples. Explain each one in plain English, show how it is used in a sentence, and give me a short story using them about [topic]." },
  { id: "learning-46", title: "Write better sentences", category: "learning", text: "Help me write better English sentences by improving these sentences: [paste sentences]. Correct the grammar, make each sentence clearer and more natural, and explain in simple words what you changed and why, so I can learn for next time." },
  { id: "learning-47", title: "Paragraph writing for school", category: "learning", text: "Help me write a clear paragraph for school on this topic: [topic]. Show me how to start with a main idea, add three supporting points with simple examples from India, and finish with a closing sentence, then give me a model paragraph to learn from." },
  { id: "learning-48", title: "Letter writing formal practice", category: "learning", text: "Help me practise formal letter writing by drafting a letter to [person or office] about [purpose]. Show the correct format with sender address, date, subject, and closing, use polite formal language, and explain each part in simple words." },
  { id: "learning-49", title: "Letter writing informal practice", category: "learning", text: "Help me practise informal letter writing by drafting a friendly letter to [relative or friend] about [topic]. Use warm, natural language, include news, a question, and a closing message, and explain the simple format for an informal letter." },
  { id: "learning-50", title: "Story writing for beginners", category: "learning", text: "Help me write a short story for beginners about [main character] in [place]. Give me a simple beginning, middle, and end, add one problem and one solution, and write the story in easy English with short sentences I can read aloud." },
  { id: "learning-51", title: "Poem writing for kids", category: "learning", text: "Help me write a simple fun poem for kids about [topic], using easy rhyming words and short lines. Make it cheerful and easy to remember, explain the rhyme pattern in simple words, and give me two more lines I can add myself." },
  { id: "learning-52", title: "Debate speech preparation", category: "learning", text: "Help me prepare a debate speech for school on this topic: [topic], taking the [for or against] side. Give me a strong opening, three clear points with simple Indian examples, one answer to the opposite side, and a confident closing line." },
  { id: "learning-53", title: "Improve handwriting practice", category: "learning", text: "Help me improve my handwriting with a simple daily practice plan for [number] days. Give me tips for holding a pen, forming letters neatly, spacing words evenly, and a short daily passage about [topic] to copy slowly and carefully." },
  { id: "learning-54", title: "Speed reading practice", category: "learning", text: "Help me practise speed reading with a simple method I can use every day for [number] minutes. Give me a short passage about [topic], tips to read faster without losing meaning, and three questions to check what I understood after reading." },
  { id: "learning-55", title: "Reading comprehension practice", category: "learning", text: "Give me a short reading passage about [topic] for reading comprehension practice, written in simple English. After the passage, ask me five questions, including two factual questions, two understanding questions, and one question asking for my opinion." },
  { id: "learning-56", title: "Learn multiplication tables tricks", category: "learning", text: "Teach me easy tricks to learn multiplication tables from 2 to 12 quickly. Show patterns, finger tricks, and shortcuts for the harder tables, give me a fun daily practice game, and test me with ten questions on the [number] times table." },
  { id: "learning-57", title: "Learn division with remainders", category: "learning", text: "Explain division with remainders in simple words using an example of sharing [number] sweets among [number] children. Show each step clearly, explain what the quotient and remainder mean, and give me five practice sums with answers to check." },
  { id: "learning-58", title: "Learn fractions with food examples", category: "learning", text: "Teach me fractions using food examples from an Indian kitchen, like cutting a chapati, sharing a pizza, or dividing a chocolate bar. Explain halves, quarters, and thirds in simple words, and give me five easy fraction questions using [food item]." },
  { id: "learning-59", title: "Learn decimals in shopping", category: "learning", text: "Teach me decimals using shopping examples from an Indian market, like prices in rupees and paise, weighing vegetables, and giving change. Explain how to read and compare decimal numbers, and give me five practice questions about buying [item] at [price]." },
  { id: "learning-60", title: "Learn percentages with discounts", category: "learning", text: "Teach me percentages using shop discounts in India, like 10 percent off a shirt or 25 percent off shoes. Explain how to find the discount amount and the final price step by step, and give me five practice questions with a [rupee amount] item." },
  { id: "learning-61", title: "Learn ratio and proportion cooking", category: "learning", text: "Teach me ratio and proportion using cooking examples, like mixing rice and water or making masala chai for guests. Explain the idea in simple words, show how to scale a recipe up or down, and give me a practice question for serving [number] people." },
  { id: "learning-62", title: "Learn algebra with simple equations", category: "learning", text: "Teach me algebra with simple equations using everyday examples, like finding the price of one notebook when [number] notebooks cost [rupee amount]. Explain each step in plain words, show how to balance both sides, and give me five easy equations to solve." },
  { id: "learning-63", title: "Learn geometry shapes at home", category: "learning", text: "Teach me geometry shapes by finding them at home, like a square window, a round plate, and a rectangular door. Explain each shape in simple words, list its sides and corners, and give me a fun activity to spot ten shapes around [room name]." },
  { id: "learning-64", title: "Learn area and perimeter garden", category: "learning", text: "Teach me area and perimeter using a garden example, where a garden is [length] metres long and [width] metres wide. Explain both ideas in simple words, show how to calculate fencing needed and grass area, and give me two practice questions to try." },
  { id: "learning-65", title: "Learn triangles and angles", category: "learning", text: "Teach me triangles and angles in simple words, explaining the types of triangles and how angles are measured. Use examples from daily life in India, like a roof shape or a slice of pizza, and give me five easy questions about a triangle with [angle] degrees." },
  { id: "learning-66", title: "Learn circles and pi simply", category: "learning", text: "Explain circles and pi in very simple words using a round plate or a bicycle wheel as an example. Explain radius, diameter, and circumference clearly, show how pi is used, and help me calculate the circumference of a circle with radius [number] centimetres." },
  { id: "learning-67", title: "Learn Pythagoras theorem simply", category: "learning", text: "Explain the Pythagoras theorem in simple words using a right-angled triangle, like the corner of a room or a ladder against a wall. Show the formula with a small example, explain each step clearly, and give me a practice question with sides [number] and [number]." },
  { id: "learning-68", title: "Learn trigonometry basics", category: "learning", text: "Teach me trigonometry basics in simple words, explaining sine, cosine, and tangent using a right-angled triangle. Use a simple example like finding the height of a tree, explain each ratio clearly, and give me one easy practice question with angle [number] degrees." },
  { id: "learning-69", title: "Learn statistics with cricket scores", category: "learning", text: "Teach me statistics using cricket scores from an Indian match, explaining mean, median, and mode in simple words. Use these scores: [list of scores], calculate each one step by step, and explain what each number tells us about the players." },
  { id: "learning-70", title: "Learn probability with coins and dice", category: "learning", text: "Teach me probability using coins and dice in simple words, explaining how to find the chance of an event happening. Use examples like tossing a coin or rolling a die, show the steps clearly, and give me five easy questions about getting [outcome]." },
  { id: "learning-71", title: "Learn square roots tricks", category: "learning", text: "Teach me easy tricks to find square roots of perfect squares up to [number]. Explain the method step by step in simple words, show two worked examples, and give me five practice questions with answers I can check myself." },
  { id: "learning-72", title: "Learn cubes and cube roots", category: "learning", text: "Teach me cubes and cube roots in simple words using examples like stacking small boxes or counting cubes in a box. Explain how to find the cube of a number and the cube root, show two worked examples, and give me five practice questions up to [number]." },
  { id: "learning-73", title: "Learn HCF and LCM simply", category: "learning", text: "Explain HCF and LCM in simple words using an everyday example, like packing sweets into boxes or two buses arriving together. Show how to find both step by step for the numbers [number] and [number], and give me three practice questions." },
  { id: "learning-74", title: "Learn profit and loss problems", category: "learning", text: "Teach me profit and loss using a small shop example in India, where a shopkeeper buys an item for [rupee amount] and sells it for [rupee amount]. Explain cost price, selling price, profit, and loss clearly, and give me five practice questions to solve." },
  { id: "learning-75", title: "Learn simple interest calculation", category: "learning", text: "Teach me simple interest using a bank example in India, where [rupee amount] is kept in a bank at [number] percent interest for [number] years. Explain principal, rate, and time in simple words, show the formula step by step, and give me three practice questions." },
  { id: "learning-76", title: "Learn compound interest simply", category: "learning", text: "Teach me compound interest in very simple words with a small example using [amount] saved for [years] at [rate] percent per year. Show how the interest grows each year and why it is different from simple interest. Use a table and Indian rupees so I can understand it easily." },
  { id: "learning-77", title: "Learn speed distance time trains", category: "learning", text: "Explain speed, distance and time in simple words using Indian trains as examples, like a train travelling [distance] km in [hours] hours. Give me the three easy formulas and three practice sums with answers. Show how to convert km per hour to metres per second step by step." },
  { id: "learning-78", title: "Learn time and work problems", category: "learning", text: "Teach me time and work problems in simple steps using everyday examples, like [number] workers finishing a job in [days] days. Explain how to find one person's one-day work and how to combine workers. Give me three practice questions with answers and simple working." },
  { id: "learning-79", title: "Learn averages with marks", category: "learning", text: "Explain averages in simple words using school marks as examples, like scores of [marks] in five subjects. Show how to find the average, the total from an average, and what happens when one new mark is added. Give me three practice sums with answers." },
  { id: "learning-80", title: "Learn mensuration for rooms", category: "learning", text: "Teach me mensuration using a room in my home as an example, with length [length] metres and width [width] metres. Explain area and perimeter in simple words and show how to work out floor tiles or paint needed. Give me three practice questions with answers." },
  { id: "learning-81", title: "Learn coordinate geometry basics", category: "learning", text: "Explain coordinate geometry in very simple words, starting with the x-axis, y-axis and a point like ([x], [y]). Show how to plot points on a graph and find the distance between two points. Give me three easy practice questions with answers and a simple diagram description." },
  { id: "learning-82", title: "Learn linear equations graphs", category: "learning", text: "Teach me linear equations in simple words with an example like [equation], and show how to draw its graph step by step. Explain what the slope and the intercept mean in plain language. Give me two practice equations to solve and draw, with answers." },
  { id: "learning-83", title: "Learn quadratic equations simply", category: "learning", text: "Explain quadratic equations in very simple words using an example like [equation], and show how to solve it by factorisation step by step. Explain what the two answers mean and when a quadratic has no simple answer. Give me three practice questions with answers." },
  { id: "learning-84", title: "Learn sets and Venn diagrams", category: "learning", text: "Teach me sets and Venn diagrams in simple words using a class example, like students who like cricket, football, or both. Explain union, intersection and complement with a clear diagram description. Give me three practice questions with answers." },
  { id: "learning-85", title: "Learn logarithms basics", category: "learning", text: "Explain logarithms in very simple words, starting from the idea that a log is the opposite of a power. Use a small example like log of [number] and show the three basic rules with easy numbers. Give me three practice questions with answers and simple working." },
  { id: "learning-86", title: "Learn calculus idea simply", category: "learning", text: "Explain the basic idea of calculus in very simple words, without difficult symbols, using a moving bicycle or a growing plant as an example. Explain what a rate of change means and what finding an area under a curve means. Give me two everyday examples I can picture easily." },
  { id: "learning-87", title: "Learn matrices basics", category: "learning", text: "Teach me matrices in simple words, starting with a small table of numbers like a shop bill or marks table. Explain rows, columns and order, then show how to add two matrices step by step. Give me three easy practice questions with answers." },
  { id: "learning-88", title: "Learn physics motion with cycles", category: "learning", text: "Explain motion in physics in simple words using a bicycle ride as an example, with distance [distance] km in time [time]. Explain speed, velocity and acceleration and how they are different. Give me three simple numerical questions with answers and working." },
  { id: "learning-89", title: "Learn force and pressure simply", category: "learning", text: "Explain force and pressure in simple words using everyday Indian examples, like pushing a heavy almirah or standing on one foot. Explain the formula for pressure and why a sharp knife cuts more easily. Give me three simple questions with answers." },
  { id: "learning-90", title: "Learn light and reflection mirrors", category: "learning", text: "Explain light and reflection in simple words using a plane mirror at home as an example. Explain the two laws of reflection and how a mirror image is formed. Give me three simple questions with answers and a diagram description I can draw." },
  { id: "learning-91", title: "Learn sound waves simply", category: "learning", text: "Explain sound waves in simple words using examples like a temple bell, a guitar string and my own voice. Explain frequency, pitch and loudness and how sound travels through air. Give me three simple questions with answers in plain language." },
  { id: "learning-92", title: "Learn electricity at home safely", category: "learning", text: "Explain electricity at home in simple words, including current, voltage and watts, using a fan, a bulb and a phone charger as examples. Explain how to stay safe, why we should not touch wet switches, and what a fuse does. Give me five safety rules to remember." },
  { id: "learning-93", title: "Learn magnetism with magnets", category: "learning", text: "Explain magnetism in simple words using a fridge magnet and a compass as examples. Explain north and south poles, attraction and repulsion, and why a compass needle points north. Give me three simple home activities I can try safely with a magnet." },
  { id: "learning-94", title: "Learn heat and temperature", category: "learning", text: "Explain heat and temperature in simple words using Indian examples like hot chai, a pressure cooker and summer in Chennai. Explain conduction, convection and radiation with one example each. Give me three simple questions with answers." },
  { id: "learning-95", title: "Learn atoms and molecules", category: "learning", text: "Explain atoms and molecules in very simple words, like building blocks that make up everything around us. Use water, oxygen and salt as examples and explain the difference between an atom and a molecule. Give me three simple questions with answers." },
  { id: "learning-96", title: "Learn periodic table tricks", category: "learning", text: "Teach me the periodic table in simple words, starting with the first twenty elements and easy memory tricks for them. Explain groups and periods in plain language and why elements are arranged this way. Give me a small quiz of five questions with answers." },
  { id: "learning-97", title: "Learn acids and bases kitchen", category: "learning", text: "Explain acids and bases in simple words using kitchen items like lemon, vinegar, curd and baking soda as examples. Explain the pH scale in plain language and how to test with litmus paper. Give me three safe home observations I can try with an adult." },
  { id: "learning-98", title: "Learn chemical reactions daily life", category: "learning", text: "Explain chemical reactions in simple words using daily life examples like cooking rice, rusting iron and lighting a diya. Explain what changes during a reaction and the signs that a reaction has happened. Give me three simple questions with answers." },
  { id: "learning-99", title: "Learn metals and non-metals", category: "learning", text: "Explain metals and non-metals in simple words using examples from my home, like steel utensils, copper wires, coal and sulphur. Compare their properties such as shine, hardness and conducting heat. Give me three simple questions with answers." },
  { id: "learning-100", title: "Learn carbon and fuels", category: "learning", text: "Explain carbon and fuels in simple words using examples like coal, petrol, LPG and wood. Explain why fuels give energy when they burn and what pollution this can cause. Give me three simple questions with answers and two ways to save fuel at home." },
  { id: "learning-101", title: "Learn human digestion simply", category: "learning", text: "Explain human digestion in simple words, following food from the mouth to the stomach and intestines after eating [food]. Explain what each part does in plain language. Give me three simple questions with answers and two healthy eating habits." },
  { id: "learning-102", title: "Learn human heart and blood", category: "learning", text: "Explain the human heart and blood in simple words, like a pump that sends blood around the body. Explain the four chambers, arteries and veins, and why blood is red. Give me three simple questions with answers." },
  { id: "learning-103", title: "Learn human brain basics", category: "learning", text: "Explain the human brain in simple words, like the control centre of the body. Explain the main parts, what each part does, and how messages travel through nerves. Give me three simple questions with answers and two habits that keep the brain healthy." },
  { id: "learning-104", title: "Learn breathing and lungs", category: "learning", text: "Explain breathing and the lungs in simple words, following air from the nose to the lungs when I breathe in and out. Explain what oxygen and carbon dioxide do in the body. Give me three simple questions with answers." },
  { id: "learning-105", title: "Learn bones and muscles", category: "learning", text: "Explain bones and muscles in simple words, using my own arm and leg as examples. Explain how bones support the body, how joints work, and how muscles pull bones to move. Give me three simple questions with answers." },
  { id: "learning-106", title: "Learn plants photosynthesis", category: "learning", text: "Explain photosynthesis in simple words using a tulsi or money plant at home as an example. Explain how sunlight, water and carbon dioxide help a plant make food and release oxygen. Give me three simple questions with answers and a diagram description." },
  { id: "learning-107", title: "Learn plant reproduction simply", category: "learning", text: "Explain plant reproduction in simple words using a flower like hibiscus as an example. Explain pollination, fertilisation and seeds in plain language. Give me three simple questions with answers and a diagram description I can draw." },
  { id: "learning-108", title: "Learn animal food chains", category: "learning", text: "Explain animal food chains in simple words using an Indian example like grass, deer and tiger. Explain producers, herbivores and carnivores and what happens if one link is removed. Give me three food chains to build, with answers." },
  { id: "learning-109", title: "Learn ecosystems in India", category: "learning", text: "Explain ecosystems in simple words using Indian examples like a pond, a forest in the Western Ghats and a desert in Rajasthan. Explain how living things and non-living things depend on each other. Give me three simple questions with answers." },
  { id: "learning-110", title: "Learn weather and seasons India", category: "learning", text: "Explain weather and seasons in India in simple words, covering summer, monsoon, post-monsoon and winter. Explain why the monsoon brings rain and how seasons change life and farming. Give me three simple questions with answers." },
  { id: "learning-111", title: "Learn water cycle simply", category: "learning", text: "Explain the water cycle in simple words, following water from a river or sea through evaporation, condensation and rain. Use an Indian monsoon example and explain why saving water matters. Give me three simple questions with answers and a diagram description." },
  { id: "learning-112", title: "Learn soil types India", category: "learning", text: "Explain soil types in India in simple words, including alluvial, black, red and desert soil. Explain where each type is found and which crops grow well in it. Give me three simple questions with answers." },
  { id: "learning-113", title: "Learn rocks and minerals", category: "learning", text: "Explain rocks and minerals in simple words using examples like granite, marble, coal and iron ore found in India. Explain the three types of rocks and how they are formed. Give me three simple questions with answers." },
  { id: "learning-114", title: "Learn solar system for kids", category: "learning", text: "Explain the solar system in simple words for a child, starting with the Sun and the eight planets in order. Give one easy fact about each planet and explain why Earth is special. End with five fun quiz questions with answers." },
  { id: "learning-115", title: "Learn moon phases simply", category: "learning", text: "Explain moon phases in simple words, from new moon to full moon, using the Indian calendar months as examples. Explain why the Moon looks different on different nights. Give me three simple questions with answers and a diagram description." },
  { id: "learning-116", title: "Learn earth rotation and day night", category: "learning", text: "Explain Earth rotation and day and night in simple words, using a torch and a ball as a home model. Explain why we have day and night and why time differs between India and America. Give me three simple questions with answers." },
  { id: "learning-117", title: "Learn volcanoes and earthquakes", category: "learning", text: "Explain volcanoes and earthquakes in simple words, using examples from India and the world. Explain what causes them, what happens during each, and how people stay safe. Give me three simple questions with answers." },
  { id: "learning-118", title: "Learn Indian rivers map", category: "learning", text: "Teach me the major Indian rivers in simple words, including the Ganga, Yamuna, Brahmaputra, Godavari, Krishna and Kaveri. Explain where each river starts, where it flows and why it matters. Give me a simple map description and five quiz questions with answers." },
  { id: "learning-119", title: "Learn Indian states and cultures", category: "learning", text: "Teach me about Indian states and cultures in simple words, with one food, festival and language fact for [state 1], [state 2] and [state 3]. Explain how India stays united with so many cultures. Give me five quiz questions with answers." },
  { id: "learning-120", title: "Learn Indian freedom fighters", category: "learning", text: "Teach me about Indian freedom fighters in simple words, including Mahatma Gandhi, Bhagat Singh, Rani Lakshmibai and Subhas Chandra Bose. Give one simple story or contribution for each person. End with five quiz questions with answers." },
  { id: "learning-121", title: "Learn Indian Constitution basics", category: "learning", text: "Explain the Indian Constitution in very simple words, including what it is, when it came into effect and why it matters. Explain fundamental rights in plain language with everyday examples. Give me three simple questions with answers." },
  { id: "learning-122", title: "Learn how Parliament works", category: "learning", text: "Explain how the Indian Parliament works in simple words, including the Lok Sabha, the Rajya Sabha and how a bill becomes a law. Use a simple example like a new road safety rule. Give me three simple questions with answers." },
  { id: "learning-123", title: "Learn how elections work India", category: "learning", text: "Explain how elections work in India in simple words, from voter registration to voting day and counting. Explain the role of the Election Commission and what an EVM does. Give me three simple questions with answers." },
  { id: "learning-124", title: "Learn Indian economy basics", category: "learning", text: "Explain the Indian economy in simple words, including agriculture, industry and services, and what GDP means in plain language. Use everyday examples like farming, factories and shops. Give me three simple questions with answers." },
  { id: "learning-125", title: "Learn Indian agriculture basics", category: "learning", text: "Explain Indian agriculture in simple words, including kharif and rabi crops, irrigation and the role of monsoon rain. Give examples like rice, wheat and cotton and where they grow. Give me three simple questions with answers." },
  { id: "learning-126", title: "Learn Indian festivals history", category: "learning", text: "Teach me the history of Indian festivals like Diwali, Holi, Eid, Christmas and Pongal in simple words. Explain when each festival started, why people celebrate it, and how it is celebrated in different states of India. Use easy examples a school student can understand and remember for exams." },
  { id: "learning-127", title: "Learn Mughal history simply", category: "learning", text: "Explain Mughal history in India in simple words for a beginner. Tell me about Babur, Akbar, Shah Jahan and Aurangzeb, what each ruler is known for, and how Mughal rule changed art, food and buildings in India. End with five easy facts I can remember for a test." },
  { id: "learning-128", title: "Learn British rule India timeline", category: "learning", text: "Make a simple timeline of British rule in India from the East India Company to independence in 1947. Include the main events, dates and leaders in short points. Explain each event in one easy sentence so I can revise it quickly before my exam on [date]." },
  { id: "learning-129", title: "Learn ancient India Harappa", category: "learning", text: "Teach me about the Harappan civilisation and the Indus Valley in simple words. Explain where people lived, what houses, drains and towns looked like, what they traded, and why the cities declined. Give me five simple points to remember for school." },
  { id: "learning-130", title: "Learn medieval India kingdoms", category: "learning", text: "Explain medieval India in simple words, covering kingdoms like the Cholas, Vijayanagara, Rajputs and Delhi Sultanate. Tell me who ruled each kingdom, what they built, and one famous fact about each. Keep the language easy for a class [class number] student." },
  { id: "learning-131", title: "Learn world geography continents", category: "learning", text: "Teach me the seven continents of the world in simple words. For each continent, tell me its location, two or three important countries, and one interesting fact. Help me remember them with an easy trick or short rhyme I can use while studying." },
  { id: "learning-132", title: "Learn world capitals quiz", category: "learning", text: "Make a fun quiz of 20 world capitals for a beginner, starting with easy ones like India, France and Japan and then adding harder ones. Give four options for each question, then list the correct answers at the end. Keep the questions short and friendly." },
  { id: "learning-133", title: "Learn maps and directions", category: "learning", text: "Teach me how to read a map and use directions like north, south, east and west in simple words. Explain what a scale, symbols and a compass mean, with an example of finding the way from [place A] to [place B] in my town. Add three practice questions." },
  { id: "learning-134", title: "Learn climate zones world", category: "learning", text: "Explain the main climate zones of the world in simple words, such as hot deserts, tropical rainforests, cold polar regions and temperate zones. For each zone, tell me the weather, the plants and animals, and one country found there. Use examples from India where possible." },
  { id: "learning-135", title: "Learn oceans and seas", category: "learning", text: "Teach me about the five oceans and important seas of the world in simple words. Tell me where each ocean is, which countries touch it, and one interesting fact about it. Explain why oceans matter for rain, food and travel in India." },
  { id: "learning-136", title: "Learn mountains of India", category: "learning", text: "Teach me about the main mountains of India, including the Himalayas, Western Ghats, Eastern Ghats and Aravalli hills. For each range, tell me where it is, its highest peak, and why it is important. Give me a simple table I can use for revision." },
  { id: "learning-137", title: "Learn deserts of India", category: "learning", text: "Explain the deserts of India, mainly the Thar Desert in Rajasthan, in simple words. Tell me about the hot climate, sand dunes, animals, plants and how people live there. Compare it with the cold desert of Ladakh in three easy points." },
  { id: "learning-138", title: "Learn forests and wildlife India", category: "learning", text: "Teach me about the forests and wildlife of India in simple words. Explain the main forest types, animals like the Bengal tiger, elephant and one-horned rhino, and why we must protect them. Give five easy facts I can use in a school project on [topic]." },
  { id: "learning-139", title: "Learn national parks India", category: "learning", text: "List ten famous national parks of India, such as Jim Corbett, Kaziranga and Gir, with the state, the famous animal found there, and the best time to visit. Keep each point to one short sentence so I can memorise it easily for my general knowledge test." },
  { id: "learning-140", title: "Learn famous Indian scientists", category: "learning", text: "Tell me about five famous Indian scientists, such as C. V. Raman, A. P. J. Abdul Kalam, Homi Bhabha, Jagadish Chandra Bose and Janaki Ammal, in simple words. For each person, share one main discovery or achievement and why it matters to India today." },
  { id: "learning-141", title: "Learn famous Indian authors", category: "learning", text: "Introduce me to five famous Indian authors, such as Rabindranath Tagore, R. K. Narayan, Ruskin Bond, Arundhati Roy and Sudha Murty, in simple words. For each author, name one famous book, what it is about, and why I should read it as a beginner." },
  { id: "learning-142", title: "Learn Indian classical music basics", category: "learning", text: "Teach me the basics of Indian classical music in simple words. Explain Hindustani and Carnatic music, what raga and tala mean, and the main instruments like sitar, tabla, veena and flute. Suggest three easy songs or artists a beginner can listen to first." },
  { id: "learning-143", title: "Learn Indian dance forms", category: "learning", text: "Teach me the main classical dance forms of India, such as Bharatanatyam, Kathak, Kathakali, Odissi and Kuchipudi, in simple words. For each dance, tell me the state it comes from, the costume, and one special feature. Help me remember them with a simple trick." },
  { id: "learning-144", title: "Learn yoga history simply", category: "learning", text: "Explain the history of yoga in simple words, from ancient India to today. Tell me who Patanjali was, what the main types of yoga are, and how yoga helps the body and mind. Give me five easy beginner poses I can try safely at home." },
  { id: "learning-145", title: "Learn Ayurveda basics simply", category: "learning", text: "Explain Ayurveda in simple words for a beginner. Tell me what doshas like Vata, Pitta and Kapha mean, how food, sleep and daily routine matter in Ayurveda, and give five simple daily habits from Ayurveda. Add a note to check with a doctor before trying any remedy." },
  { id: "learning-146", title: "Learn computer basics for elders", category: "learning", text: "Teach me computer basics in very simple words for an elderly person in India who is using a computer for the first time. Explain the mouse, keyboard, screen and internet slowly, step by step. Use large, clear examples like opening WhatsApp Web and watching a YouTube video." },
  { id: "learning-147", title: "Learn keyboard shortcuts", category: "learning", text: "Teach me 20 useful keyboard shortcuts for Windows in simple words, starting with copy, paste, undo and save. For each shortcut, show the keys to press and what it does in one short sentence. Group them into easy, useful and advanced so I can learn a few each day." },
  { id: "learning-148", title: "Learn MS Word basics", category: "learning", text: "Teach me MS Word basics in simple steps for a beginner in India. Show me how to type, change the font size and colour, make headings bold, add a table, save a file and print it. Use a simple example like writing a letter to [person] so I can practise each step." },
  { id: "learning-149", title: "Learn PowerPoint for school", category: "learning", text: "Teach me how to make a simple PowerPoint presentation for school on [topic]. Show me how to add a title slide, add points on each slide, insert a picture, choose colours that are easy to read, and present it confidently. Give me a ten-slide outline I can follow." },
  { id: "learning-150", title: "Learn Google Sheets basics", category: "learning", text: "Teach me Google Sheets basics in simple steps. Show me how to open a new sheet, type numbers and words in cells, make a simple table for monthly expenses, add totals, and save and share the sheet. Use an Indian household budget example with rent, food and travel." },
  { id: "learning-151", title: "Learn email writing basics", category: "learning", text: "Teach me how to write a simple, polite email in English for work or school in India. Show me the subject line, greeting, body and closing, with one example email to a teacher and one to an office manager. Give me five simple rules to avoid spelling and grammar mistakes." },
  { id: "learning-152", title: "Learn internet safety for kids", category: "learning", text: "Teach me internet safety rules for kids in India in simple words. Explain why we should not share our name, school, photos or passwords online, what to do if a stranger messages us, and how to tell a parent or teacher. Give me ten easy safety rules to remember." },
  { id: "learning-153", title: "Learn online banking safely", category: "learning", text: "Teach me how to use online banking safely in India in simple steps. Explain how to log in, check my balance, transfer money, and log out safely. Tell me the warning signs of a fake bank call or message and what to do if I get one." },
  { id: "learning-154", title: "Learn UPI safety basics", category: "learning", text: "Teach me UPI safety basics in simple words for a beginner in India. Explain how UPI works, why I should never share my UPI PIN, and why I should never accept a collect request from a stranger. Give me a checklist to follow before I send money to anyone." },
  { id: "learning-155", title: "Learn typing speed practice", category: "learning", text: "Make a simple 15-minute daily typing practice plan to improve my typing speed on a computer keyboard. Give me easy English sentences to type, tips for finger placement, and a way to track my words per minute each week. Start with slow, correct typing and then build speed." },
  { id: "learning-156", title: "Learn to use smartphone apps", category: "learning", text: "Teach me how to use common smartphone apps in India in simple steps, such as WhatsApp, YouTube, Google Maps and Paytm. For each app, explain how to open it, what the main buttons do, and one useful task I can do with it. Use large, clear steps for a first-time user." },
  { id: "learning-157", title: "Learn to use Google Maps", category: "learning", text: "Teach me how to use Google Maps on my phone in simple steps. Show me how to search for a place, get directions by car, bus or walking, check traffic, save my home address, and share my live location with family. Use an example trip from [place A] to [place B]." },
  { id: "learning-158", title: "Learn to use DigiLocker", category: "learning", text: "Teach me how to use DigiLocker in India in simple steps. Explain what DigiLocker is, how to sign up with my Aadhaar and mobile number, and how to store and download documents like my PAN card, driving licence and marksheet. Tell me how to keep my account safe." },
  { id: "learning-159", title: "Learn to use UMANG app", category: "learning", text: "Teach me how to use the UMANG app in India in simple steps. Explain what services it offers, such as EPFO, PAN, DigiLocker and bill payment, how to download and register with my mobile number, and how to find one service I need, like [service name]." },
  { id: "learning-160", title: "Learn to use IRCTC booking", category: "learning", text: "Teach me how to book a train ticket on IRCTC in simple steps. Show me how to create an account, search for a train from [station A] to [station B] on [date], choose a seat, pay safely, and download my ticket. Explain Tatkal booking and what to do if my ticket is waitlisted." },
  { id: "learning-161", title: "Learn Python basics for kids", category: "learning", text: "Teach me Python coding basics in a fun, simple way for a child aged 10 to 12. Explain what Python is, how to print hello, use variables, and make a simple number guessing game. Give me five small practice tasks I can try, with the answers explained in easy words." },
  { id: "learning-162", title: "Learn Scratch coding for kids", category: "learning", text: "Teach me Scratch coding for kids in simple words. Explain what blocks, sprites and the stage are, and show me step by step how to make a cat move, talk and jump when I press a key. Give me three fun project ideas I can build after this first one." },
  { id: "learning-163", title: "Learn HTML basics first page", category: "learning", text: "Teach me HTML basics in simple words and help me make my first web page. Explain what tags are, then show me a short example page with a heading, a paragraph, a picture and a link about [topic]. Explain each line so I understand what it does." },
  { id: "learning-164", title: "Learn CSS colours and fonts", category: "learning", text: "Teach me CSS colours and fonts in simple words for a beginner. Explain how to change the text colour, background colour, font size and font style on a web page. Give me a short example with three colour and font changes I can try on my first HTML page." },
  { id: "learning-165", title: "Learn JavaScript basics fun", category: "learning", text: "Teach me JavaScript basics in a fun, simple way for a beginner. Explain what JavaScript does on a web page, how to show a message, change text when I click a button, and make a simple counter. Give me a small example I can copy and try in my browser." },
  { id: "learning-166", title: "Learn data entry practice", category: "learning", text: "Teach me data entry basics in simple steps for a beginner looking for office work in India. Explain how to type names, numbers and dates neatly in Excel or Google Sheets, check for mistakes, and save files properly. Give me a practice table with 20 rows to enter." },
  { id: "learning-167", title: "Learn to make a chart in Excel", category: "learning", text: "Teach me how to make a simple chart in Excel in easy steps. Use an example of monthly spending in an Indian home, with rent, food, travel and other costs. Show me how to select the data, insert a bar chart, add a title, and make it clear to read." },
  { id: "learning-168", title: "Learn formulas in Google Sheets", category: "learning", text: "Teach me ten useful formulas in Google Sheets in simple words, starting with SUM, AVERAGE, MAX, MIN and COUNT. For each formula, show a small example with Indian rupees and explain what it does. Then give me a practice sheet idea to test all ten formulas." },
  { id: "learning-169", title: "Learn to make a resume in Word", category: "learning", text: "Teach me how to make a simple, neat resume in MS Word for a fresher in India. Show me what to put in each section, like name, education, skills and experience, with an example for [job role]. Give me five tips to keep it to one page and easy to read." },
  { id: "learning-170", title: "Learn to make a poster in Canva", category: "learning", text: "Teach me how to make a simple poster in Canva in easy steps for [event or topic]. Show me how to pick a template, change the text and colours, add a photo, and download it for WhatsApp or printing. Give me three poster text ideas in simple English." },
  { id: "learning-171", title: "Learn to edit photos on phone", category: "learning", text: "Teach me how to edit photos on my phone in simple steps using a free app. Show me how to crop, straighten, brighten, add a filter, and remove a small unwanted part. Use a family photo example and give me five easy tips to make photos look natural, not over-edited." },
  { id: "learning-172", title: "Learn to edit video on phone", category: "learning", text: "Teach me how to edit a short video on my phone in simple steps using a free app. Show me how to cut extra parts, join clips, add music, add text, and save it for WhatsApp or YouTube Shorts. Use a one-minute birthday video example and keep the steps easy for a beginner." },
  { id: "learning-173", title: "Learn to make a YouTube video", category: "learning", text: "Teach me how to make my first YouTube video in simple steps, from idea to upload. Help me plan a five-minute video on [topic], write a simple script, record with my phone, edit the basic parts, and add a title and thumbnail. Give me five beginner tips." },
  { id: "learning-174", title: "Learn to record a podcast", category: "learning", text: "Teach me how to record a simple podcast in India using just my phone and a quiet room. Help me pick a topic, write a short outline for a ten-minute episode on [topic], record clearly, and edit out mistakes. Give me five easy tips to sound confident and natural." },
  { id: "learning-175", title: "Learn public speaking basics", category: "learning", text: "Teach me public speaking basics in simple words for a beginner in India. Show me how to plan a short three-minute talk on [topic], start with confidence, speak slowly and clearly, use simple words, and handle nervousness. Give me a daily five-minute practice plan." },
  { id: "learning-176", title: "Learn to give a vote of thanks", category: "learning", text: "Teach me how to give a short vote of thanks at [event name] in school or college. Give me a simple structure I can follow, words to thank the chief guest, teachers and audience, and a short example speech of about one minute that I can practise and change to fit my event." },
  { id: "learning-177", title: "Learn anchoring for school function", category: "learning", text: "Help me learn anchoring for a school function like [annual day]. Give me a simple opening line, how to introduce each performance, and smooth lines to use between items, plus tips to speak clearly, stay calm on stage, and keep the audience interested without reading from a paper." },
  { id: "learning-178", title: "Learn to tell a story aloud", category: "learning", text: "Teach me how to tell a story aloud to [children or classmates] so they enjoy it. Show me how to start with something interesting, change my voice for different characters, pause at the right moments, and end with a clear lesson, using the story [story name] as my practice example." },
  { id: "learning-179", title: "Learn to ask questions in class", category: "learning", text: "Help me learn how to ask questions in class without feeling shy. Give me simple polite ways to start a question, examples like 'Could you please explain [topic] again?', and tips on when to ask, how to listen to the answer, and what to do if I still do not understand." },
  { id: "learning-180", title: "Learn to take notes in lectures", category: "learning", text: "Teach me how to take good notes during a lecture on [subject]. Show me a simple method to write down only the main points, use short forms and symbols, leave space for questions, and review my notes the same evening so I remember the lesson better." },
  { id: "learning-181", title: "Learn to revise with mind maps", category: "learning", text: "Help me revise [chapter name] using a mind map. Show me how to put the main topic in the centre, add branches for each important point, use colours and small drawings, and turn the map into quick revision notes I can read in ten minutes before a test." },
  { id: "learning-182", title: "Learn to make a study wall chart", category: "learning", text: "Help me make a study wall chart for [subject] that I can stick on my wall at home. Suggest what to include, such as key dates, formulas or important words, how to keep it neat and colourful, and how to use it every day for quick revision." },
  { id: "learning-183", title: "Learn Pomodoro study method", category: "learning", text: "Explain the Pomodoro study method in simple words for a student preparing for [exam name]. Tell me how long to study, when to take short and long breaks, what to do during breaks, and how to plan four study sessions in one evening without feeling tired." },
  { id: "learning-184", title: "Learn to avoid exam stress", category: "learning", text: "Give me simple ways to avoid stress before my [exam name]. Suggest a calm daily routine, breathing exercises I can do in five minutes, how to break big chapters into small parts, and what to tell myself when I feel worried, so I can study with a clear mind." },
  { id: "learning-185", title: "Learn to sleep well before exams", category: "learning", text: "Teach me how to sleep well the night before my [exam name]. Tell me what time to stop studying, what to avoid in the evening such as heavy food and phone screens, a simple relaxing routine, and what to do if I cannot fall asleep quickly." },
  { id: "learning-186", title: "Learn to plan a holiday study break", category: "learning", text: "Help me plan a study break during my [holiday name] holidays. Make a simple timetable that mixes revision, rest, family time and play, so I cover [subject] without studying all day, and tell me how to stick to the plan without feeling guilty." },
  { id: "learning-187", title: "Learn to set daily study goals", category: "learning", text: "Help me set simple daily study goals for [subject]. Show me how to pick two or three small targets for today, such as finishing one chapter or solving ten questions, how to write them down, and how to check at night whether I finished them." },
  { id: "learning-188", title: "Learn to track study progress", category: "learning", text: "Teach me how to track my study progress for [exam name] in a simple notebook or chart. Show me what to record each day, such as topics finished and test marks, how to spot weak areas, and how to celebrate small progress to stay motivated." },
  { id: "learning-189", title: "Learn to study with a friend", category: "learning", text: "Help me study with my friend [friend's name] in a useful way. Suggest how to divide topics, quiz each other, explain difficult parts in simple words, take breaks together, and avoid wasting time chatting, so both of us learn better." },
  { id: "learning-190", title: "Learn to teach a topic to others", category: "learning", text: "Teach me how to teach [topic] to my classmates in simple words. Show me how to explain it step by step, use a daily-life example, ask them questions to check understanding, and handle a question I cannot answer without feeling embarrassed." },
  { id: "learning-191", title: "Learn to learn from mistakes", category: "learning", text: "Help me learn from my mistakes in [test or exam name]. Show me how to look at each wrong answer, find out why I got it wrong, write the correct method in a mistake notebook, and revise those points again before the next test so I do not repeat them." },
  { id: "learning-192", title: "Learn to read a newspaper daily", category: "learning", text: "Teach me how to read a newspaper daily in just 20 minutes. Tell me which pages to read first, how to pick important news for [exam or general knowledge], note down five new words, and discuss one news item with my family to remember it better." },
  { id: "learning-193", title: "Learn current affairs weekly", category: "learning", text: "Help me learn current affairs every week for [exam name]. Give me a simple weekly plan to read important news about India and the world, note key facts in a notebook, and revise them every Sunday with a short self-test of ten questions." },
  { id: "learning-194", title: "Learn GK for quiz competitions", category: "learning", text: "Help me prepare general knowledge for a quiz competition at [school name]. Give me a daily plan to learn facts about India, science, sports and history, practise with sample quiz questions, and remember answers using simple memory tricks and regular revision." },
  { id: "learning-195", title: "Learn Indian GK for exams", category: "learning", text: "Help me learn Indian general knowledge for [exam name]. Cover important facts about Indian states, capitals, rivers, national symbols and government schemes in simple points, and give me a weekly revision plan with short quiz questions to test myself." },
  { id: "learning-196", title: "Learn sports GK India", category: "learning", text: "Teach me sports general knowledge about India for [exam or quiz name]. Cover famous Indian players, major tournaments, national games and awards in simple points, and give me a fun quiz of ten questions with answers to test what I learned." },
  { id: "learning-197", title: "Learn awards and honours India", category: "learning", text: "Help me learn about Indian awards and honours like the Bharat Ratna and Padma awards for [exam name]. Explain each award in simple words, who receives it, and give me a short table of recent winners I can memorise with easy revision tips." },
  { id: "learning-198", title: "Learn famous places India quiz", category: "learning", text: "Help me learn about famous places in India for a quiz at [school name]. Cover important monuments, temples, forts and natural wonders with one simple fact about each, and make ten quiz questions with answers so I can practise and remember them." },
  { id: "learning-199", title: "Learn Indian Railways facts", category: "learning", text: "Teach me interesting facts about Indian Railways for [exam or quiz name]. Cover its history, longest routes, famous trains like [train name], and important numbers in simple points, then give me ten quick questions to test my memory." },
  { id: "learning-200", title: "Learn about ISRO missions", category: "learning", text: "Help me learn about ISRO missions in simple words for [exam or school project]. Explain what ISRO does, famous missions like Chandrayaan and Mangalyaan, and why they matter for India, with a short timeline I can remember easily." },
  { id: "learning-201", title: "Learn about Indian Army basics", category: "learning", text: "Teach me the basics of the Indian Army for [exam or school project]. Explain its role, main ranks in simple order, famous regiments, and important days, using easy language and a short list of facts I can revise before a test." },
  { id: "learning-202", title: "Learn about Indian Navy basics", category: "learning", text: "Teach me the basics of the Indian Navy for [exam or school project]. Explain its role in protecting India's seas, main ships and ranks in simple words, important naval bases, and Navy Day, with a short fact list to revise." },
  { id: "learning-203", title: "Learn about Indian Air Force", category: "learning", text: "Teach me the basics of the Indian Air Force for [exam or school project]. Explain its role, main aircraft, ranks in simple order, famous squadrons, and Air Force Day, using easy language and a short list of facts I can remember." },
  { id: "learning-204", title: "Learn first aid basics for students", category: "learning", text: "Teach me first aid basics every student should know. Explain in simple steps what to do for a small cut, a nosebleed, a burn or a sprain, when to call an adult or dial [emergency number], and what to keep in a small first aid box at home or school." },
  { id: "learning-205", title: "Learn road safety rules India", category: "learning", text: "Teach me road safety rules in India in simple words for students. Explain why to wear a helmet and seat belt, follow traffic lights, cross roads at zebra crossings, and never use a phone while walking or cycling, with examples from daily life in [city name]." },
  { id: "learning-206", title: "Learn traffic signs meaning", category: "learning", text: "Help me learn the meaning of common traffic signs in India. Explain mandatory, cautionary and informative signs with simple examples, show me how to remember them with pictures, and give me a quick quiz of ten signs to test myself." },
  { id: "learning-207", title: "Learn fire safety at home", category: "learning", text: "Teach me fire safety steps to follow at home in [city name]. Explain what to do if a fire starts in the kitchen, how to use a fire extinguisher safely, why to never use water on an oil fire, and how to leave the house calmly and call for help." },
  { id: "learning-208", title: "Learn earthquake safety steps", category: "learning", text: "Teach me what to do during an earthquake in simple steps. Explain the drop, cover and hold method, where to stay safe inside a building, what to avoid such as lifts and windows, and what to do after the shaking stops before going outside." },
  { id: "learning-209", title: "Learn flood safety basics", category: "learning", text: "Teach me flood safety basics for my area in [city or state name]. Explain how to stay safe during heavy rain and flooding, what to keep ready in an emergency bag, why to avoid walking in flood water, and whom to contact for help." },
  { id: "learning-210", title: "Learn to save water at home", category: "learning", text: "Teach me simple ways to save water at home in [city name]. Suggest easy habits like turning off taps while brushing, reusing water for plants, fixing leaks quickly, and collecting rainwater, with a small weekly plan my family can follow together." },
  { id: "learning-211", title: "Learn to grow vegetables at home", category: "learning", text: "Teach me how to grow vegetables at home in a small space like a balcony in [city name]. Suggest easy vegetables for beginners, what soil and pots to use, how often to water, and how long each vegetable takes to grow, in simple steps." },
  { id: "learning-212", title: "Learn to compost kitchen waste", category: "learning", text: "Teach me how to compost kitchen waste at home in simple steps. Explain what waste to use, such as vegetable peels and fruit skins, what to avoid, how to layer it in a bin, and how long it takes to turn into useful compost for plants." },
  { id: "learning-213", title: "Learn to recycle at home", category: "learning", text: "Teach me how to recycle waste at home in [city name]. Explain how to sort paper, plastic, glass and metal, what can and cannot be recycled, where to give sorted waste, and simple habits to reduce waste every day." },
  { id: "learning-214", title: "Learn about solar energy India", category: "learning", text: "Explain solar energy in simple words and how India uses it. Tell me how solar panels make electricity, why solar power is good for the environment, where India has big solar parks, and how a family can use solar power at home." },
  { id: "learning-215", title: "Learn about wind energy simply", category: "learning", text: "Explain wind energy in simple words for a student. Tell me how wind turbines make electricity, where wind farms are located in India, why wind power is clean energy, and what its benefits and limits are, with one daily-life example." },
  { id: "learning-216", title: "Learn about electric vehicles India", category: "learning", text: "Teach me about electric vehicles in India in simple words. Explain how electric cars and scooters work, why they are better for air quality, how charging works, and what the government is doing to support them, with examples from [city name]." },
  { id: "learning-217", title: "Learn about metro trains India", category: "learning", text: "Teach me about metro trains in India in simple words. Explain how metro systems work, which cities have them, how they help reduce traffic and pollution, and simple facts about the Delhi Metro and the metro in [city name] for my school project." },
  { id: "learning-218", title: "Learn about Indian post office", category: "learning", text: "Teach me about the Indian post office and its services in simple words. Explain how to send a letter and parcel, what speed post and registered post mean, how money orders work, and what savings schemes the post office offers for families." },
  { id: "learning-219", title: "Learn about banks in India", category: "learning", text: "Teach me about banks in India in simple words for a student. Explain what banks do, the difference between savings and current accounts, what ATMs and UPI are, and how to open a savings account with the help of a parent." },
  { id: "learning-220", title: "Learn about RBI functions simply", category: "learning", text: "Explain the functions of the Reserve Bank of India in simple words. Tell me what the RBI does, why it prints currency, how it controls inflation, what repo rate means, and why the RBI matters for every Indian family, with easy examples." },
  { id: "learning-221", title: "Learn about stock market basics", category: "learning", text: "Teach me stock market basics in simple words for a beginner in India. Explain what shares are, how the stock market works, what BSE and NSE mean, why prices go up and down, and why learning and patience matter before investing any money." },
  { id: "learning-222", title: "Learn about mutual funds for students", category: "learning", text: "Teach me mutual funds in simple words for a student in India. Explain what a mutual fund is, how many people pool money to invest, what SIP means, the risks involved, and why it is important to learn and discuss with a parent before investing." },
  { id: "learning-223", title: "Learn about insurance basics teens", category: "learning", text: "Teach me insurance basics in simple words for a teenager in India. Explain what insurance means, how health and life insurance work, why families buy insurance, what a premium is, and what to check before choosing a policy with a parent." },
  { id: "learning-224", title: "Learn about tax for first job", category: "learning", text: "Teach me about tax in simple words for my first job in India. Explain what income tax is, how TDS is deducted from salary, what a PAN card is for, and which basic documents to keep, so I understand my first salary slip better." },
  { id: "learning-225", title: "Learn about salary slip reading", category: "learning", text: "Teach me how to read my salary slip in simple words. Explain each part such as basic pay, HRA, allowances, PF, professional tax and TDS, how to check whether the numbers are correct, and what questions to ask my employer if something looks wrong." },
  { id: "learning-226", title: "Learn about PF and ESI basics", category: "learning", text: "Teach me the basics of PF and ESI in India in simple words for a new employee earning [monthly salary]. Explain what gets deducted, what the employer pays, and what benefits I get, with one small example." },
  { id: "learning-227", title: "Learn about government schemes students", category: "learning", text: "List government schemes in India that can help a student like me in [class or course] from [state]. For each scheme, explain in one line who can apply, what support it gives, and where to check official details." },
  { id: "learning-228", title: "Learn about scholarships India", category: "learning", text: "Help me find scholarships in India for a student in [class or course] with [family income or category, if applicable]. List suitable options, their basic eligibility, documents usually needed, and the official website to apply." },
  { id: "learning-229", title: "Learn about entrance exams after Class 12", category: "learning", text: "Explain the main entrance exams in India after Class 12 for [field of interest, e.g. engineering, medicine, law]. For each exam, give its purpose, subjects tested, and a simple 3-month preparation starting plan." },
  { id: "learning-230", title: "Learn about courses after Class 10", category: "learning", text: "List good course options in India after Class 10 for a student interested in [interest area]. Include short courses, diplomas and streams, what each leads to, and questions to ask before choosing one." },
  { id: "learning-231", title: "Learn about courses after Class 12", category: "learning", text: "List course options in India after Class 12 for a student from [stream: Science, Commerce or Arts] interested in [interest]. For each course, explain duration, skills learned, and possible careers after finishing it." },
  { id: "learning-232", title: "Learn about diploma courses India", category: "learning", text: "Explain diploma courses in India for a student who finished [Class 10 or 12] and wants [field]. List popular diplomas, their duration, fees range in general terms, and jobs or further study after them." },
  { id: "learning-233", title: "Learn about ITI courses India", category: "learning", text: "Explain ITI courses in India in simple words for a student after [Class 8, 10 or 12]. List popular trades like [trade of interest], course length, practical skills taught, and jobs or apprenticeships after finishing." },
  { id: "learning-234", title: "Learn about medical courses India", category: "learning", text: "Explain medical and health courses in India after Class 12 for a student interested in [MBBS, nursing, pharmacy or other]. Compare duration, entrance exams, and career paths, and list things to check before choosing a college." },
  { id: "learning-235", title: "Learn about engineering branches", category: "learning", text: "Explain the main engineering branches in India, such as [branch of interest], in simple words. For each branch, describe what students study, what kind of work graduates do, and skills that help in that field." },
  { id: "learning-236", title: "Learn about law courses India", category: "learning", text: "Explain law courses in India after Class 12 or graduation for someone interested in [career goal]. Cover course types, duration, entrance exams, subjects studied, and career options after becoming a law graduate." },
  { id: "learning-237", title: "Learn about teaching courses India", category: "learning", text: "Explain teaching courses in India, such as B.Ed and D.El.Ed, for someone who wants to become a teacher in [primary or secondary school]. Cover eligibility, duration, entrance process, and where teachers can work after qualifying." },
  { id: "learning-238", title: "Learn about hotel management courses", category: "learning", text: "Explain hotel management courses in India for a student interested in [hotels, cooking, or tourism]. Cover course types, duration, subjects like front office and food service, practical training, and jobs after the course." },
  { id: "learning-239", title: "Learn about design courses India", category: "learning", text: "Explain design courses in India for a student interested in [fashion, graphic, interior or product design]. Cover popular courses, entrance exams, skills needed, portfolio basics, and career options after study." },
  { id: "learning-240", title: "Learn about agriculture courses", category: "learning", text: "Explain agriculture courses in India for a student interested in [farming, horticulture or agri-business]. Cover popular courses, duration, subjects studied, field training, and jobs in farming, government and private companies." },
  { id: "learning-241", title: "Learn about nursing courses", category: "learning", text: "Explain nursing courses in India, such as GNM, B.Sc Nursing and ANM, for a student after [Class 12]. Compare duration, eligibility, practical training, and work options in hospitals, clinics and community health." },
  { id: "learning-242", title: "Learn about CA course basics", category: "learning", text: "Explain the CA course in India in simple words for a student after [Class 12 or graduation]. Cover the stages, subjects, articleship training, exam pattern in general, and how long it usually takes to complete." },
  { id: "learning-243", title: "Learn about UPSC exam pattern", category: "learning", text: "Explain the UPSC Civil Services exam pattern in India in simple words for a beginner. Cover Prelims, Mains and Interview stages, subjects, marks, and a simple first 3-month study plan for [optional subject, if chosen]." },
  { id: "learning-244", title: "Learn about SSC exam pattern", category: "learning", text: "Explain the SSC exam pattern in India for [SSC CGL, CHSL or other exam]. Cover stages, subjects, marks, time limits, and a simple weekly study plan for a beginner preparing while [studying or working]." },
  { id: "learning-245", title: "Learn about banking exam pattern", category: "learning", text: "Explain the banking exam pattern in India for [IBPS, SBI PO, Clerk or other exam]. Cover Prelims and Mains, subjects like reasoning and maths, marks, and a simple daily practice plan for a beginner." },
  { id: "learning-246", title: "Learn about railway exam pattern", category: "learning", text: "Explain the railway exam pattern in India for [RRB NTPC, Group D or other post]. Cover stages, subjects, marks, physical tests if any, and a simple study plan for a beginner from [educational background]." },
  { id: "learning-247", title: "Learn about police exam pattern", category: "learning", text: "Explain the police exam pattern in India for [constable, SI or other post] in [state]. Cover written test, physical test and interview, subjects, and a simple fitness plus study plan for a beginner." },
  { id: "learning-248", title: "Learn about teaching exam TET", category: "learning", text: "Explain the TET exam in India for becoming a teacher in [state], in simple words. Cover Paper 1 and Paper 2, subjects, eligibility, qualifying marks, and a simple study plan for a beginner." },
  { id: "learning-249", title: "Learn about NEET exam pattern", category: "learning", text: "Explain the NEET exam pattern in India in simple words for a Class [11 or 12] student. Cover subjects, marks, question type, time limit, and a simple weekly study plan for Physics, Chemistry and Biology." },
  { id: "learning-250", title: "Learn about JEE exam pattern", category: "learning", text: "Explain the JEE Main and Advanced exam pattern in India in simple words for a Class [11 or 12] student. Cover subjects, marks, question types, and a simple weekly study plan for Physics, Chemistry and Maths." },
  { id: "learning-251", title: "Learn to choose a career", category: "learning", text: "Help me choose a career in India based on my interests in [interest], my strengths in [strength], and my Class [10 or 12] subjects. Suggest 5 suitable careers, what each involves, and the first step for each one." },
  { id: "learning-252", title: "Learn to write a career plan", category: "learning", text: "Help me write a simple one-page career plan for my goal of becoming a [career goal] in India. Include my current stage, skills to learn, courses or exams needed, and month-wise steps for the next 12 months." },
  { id: "learning-253", title: "Learn interview skills for students", category: "learning", text: "Teach me basic interview skills for a student applying for [internship, job or college admission] in India. Give common questions, simple model answers, body language tips, and 5 practice questions for me." },
  { id: "learning-254", title: "Learn group discussion basics", category: "learning", text: "Teach me group discussion basics for a student preparing for [college admission or campus placement] in India. Explain the rules, how to start, how to agree or disagree politely, and give 3 practice topics." },
  { id: "learning-255", title: "Learn to write a job application", category: "learning", text: "Help me write a simple job application for the post of [job title] at [company name] in [city]. Use my details: [qualification, experience, skills]. Keep it polite, short, and ready to send by email or post." },
  { id: "learning-256", title: "Learn to make a LinkedIn profile student", category: "learning", text: "Help me make a simple LinkedIn profile as a student in [course] interested in [career field] in India. Suggest a headline, About section, skills to list, and what to write when I have no work experience yet." },
  { id: "learning-257", title: "Learn time management for students", category: "learning", text: "Help me make a simple daily time management plan for a student in Class [class] who studies [hours per day] and also does [activity]. Include study blocks, breaks, revision time, and one rule to avoid wasting time." },
  { id: "learning-258", title: "Learn to balance study and sports", category: "learning", text: "Help me balance study and sports as a student in Class [class] who plays [sport] for [hours per week]. Make a weekly plan with study time, practice time, rest, and tips to stay fit without falling behind in studies." },
  { id: "learning-259", title: "Learn to balance phone and study", category: "learning", text: "Help me balance phone use and study as a student in Class [class] preparing for [exam]. Suggest daily phone limits, study hours without the phone, useful apps, and 5 simple rules to reduce distraction." },
  { id: "learning-260", title: "Learn to read faster with focus", category: "learning", text: "Teach me how to read faster with focus for my [subject] textbook in Class [class]. Give a simple 3-step method, how to avoid re-reading every line, and a 10-minute daily practice plan for one week." },
  { id: "learning-261", title: "Learn to summarise a lesson in 5 lines", category: "learning", text: "Help me summarise this lesson in exactly 5 simple lines for a Class [class] student: [paste lesson text or topic]. Keep only the main ideas, use easy words, and end with one line I can use for revision." },
  { id: "learning-262", title: "Learn to make a revision timetable for one subject", category: "learning", text: "Help me make a revision timetable for one subject, [subject], before my [exam name] on [exam date]. Divide the chapters by days, add revision and practice test slots, and keep Sundays light for catch-up." },
  { id: "learning-263", title: "Learn to practise previous year papers", category: "learning", text: "Help me make a plan to practise previous year papers for [exam name] in the next [number] weeks. Tell me how many papers to solve weekly, how to check answers, and how to note down repeated mistakes." },
  { id: "learning-264", title: "Learn to write answers in exams", category: "learning", text: "Teach me how to write good answers in exams for [subject] in Class [class]. Explain how to plan an answer, use headings and points, manage length for [marks] questions, and show one good model answer." },
  { id: "learning-265", title: "Learn to manage exam time", category: "learning", text: "Help me manage my time in a [duration] exam for [subject] with [number] questions. Make a minute-wise plan for reading, answering easy questions first, long answers, and last 10 minutes for checking." },
  { id: "learning-266", title: "Learn to stay calm in exams", category: "learning", text: "Teach me simple ways to stay calm in exams as a Class [class] student appearing for [exam name]. Give breathing steps, what to do if I forget an answer, and a short morning routine for exam day." },
  { id: "learning-267", title: "Learn to improve concentration games", category: "learning", text: "Suggest 5 simple games and activities to improve concentration for a student in Class [class] in India. For each game, explain how to play it, how long to play, and which study skill it helps." },
  { id: "learning-268", title: "Learn to memorise with stories", category: "learning", text: "Teach me how to memorise [topic or list] using a short story for a Class [class] student. Turn the points into a funny story, keep it under 150 words, and end with 3 quick recall questions." },
  { id: "learning-269", title: "Learn to memorise with songs", category: "learning", text: "Teach me how to memorise [topic or list] using a simple song or rhyme for a Class [class] student. Make a short tune-friendly rhyme, keep the words easy, and add a repeat line to help recall." },
  { id: "learning-270", title: "Learn to memorise with drawings", category: "learning", text: "Teach me how to memorise [topic or list] using simple drawings for a Class [class] student. Suggest what to draw for each point, how to label it, and how to revise from the drawing in 5 minutes." },
  { id: "learning-271", title: "Learn to learn a poem by heart", category: "learning", text: "Help me learn this poem by heart for Class [class]: [paste poem or poem name]. Break it into small parts, explain hard words simply, and give a daily practice plan for [number] days." },
  { id: "learning-272", title: "Learn to spell difficult words", category: "learning", text: "Help me learn to spell these difficult words for Class [class]: [list words]. For each word, break it into parts, give a simple trick to remember the spelling, and add one sentence using it." },
  { id: "learning-273", title: "Learn to use a dictionary", category: "learning", text: "Teach me how to use a dictionary as a Class [class] student in India. Explain alphabetical order, how to find a word, what the meanings and examples show, and give 5 words to practise with." },
  { id: "learning-274", title: "Learn to use a thesaurus simply", category: "learning", text: "Teach me how to use a thesaurus simply as a Class [class] student. Explain what synonyms are, how to pick the right word, and give 5 common words with 2 better alternatives and one example sentence each." },
  { id: "learning-275", title: "Learn to keep a learning diary", category: "learning", text: "Help me start a simple learning diary as a student in Class [class]. Give a daily format with date, what I learned, one doubt, and one thing to revise, plus 5 sample entries to copy the style." },
  { id: "learning-276", title: "BODMAS order of operations", category: "learning", text: "Teach me the BODMAS rule for Class [7/8] with 10 worked examples from simple to tricky, using Indian rupee sums and cricket scores where it fits. Explain why brackets come first, then give me 5 practice sums with answers at the end." },
  { id: "learning-277", title: "Rational numbers on a number line", category: "learning", text: "Show me how to place rational numbers on a number line for Class [8/9], using examples like [1/2, -3/4, 2.5]. Explain how to find numbers between two given numbers, then give me 8 numbers to plot and check my answers." },
  { id: "learning-278", title: "Integers and negative numbers in daily life", category: "learning", text: "Explain integers and negative numbers for Class [6/7] using daily life in India, like temperature in Shimla, floors below ground, and money owed. Give 10 addition and subtraction sums with a number line, and answers at the end." },
  { id: "learning-279", title: "Exponents and powers laws", category: "learning", text: "Explain exponents and powers for Class [7/8], including the laws of exponents, with simple examples using [base and power]. Show how to simplify 5 expressions step by step, then give me 8 practice questions with answers." },
  { id: "learning-280", title: "Algebraic identities with examples", category: "learning", text: "Teach me three algebraic identities for Class [8/9], like (a+b) squared and (a-b) squared, with a simple diagram or area example for each. Work out 4 examples, then give me 6 problems to solve with answers at the end." },
  { id: "learning-281", title: "Factorisation of algebraic expressions", category: "learning", text: "Show me how to factorise algebraic expressions for Class [8/9] step by step, starting with common factors, then grouping, then identities. Work through 5 examples using [expression], then give me 8 practice sums with answers." },
  { id: "learning-282", title: "Polynomials and their zeroes", category: "learning", text: "Explain polynomials for Class [9/10], what degree, terms and coefficients mean, and how to find zeroes of a polynomial. Use [polynomial] as the worked example, then give me 5 questions to try with answers." },
  { id: "learning-283", title: "Pair of linear equations word problems", category: "learning", text: "Help me solve pair of linear equations word problems for Class 10, like ticket prices, ages, or two numbers, using [problem]. Show the substitution and elimination methods side by side, then give me 3 new word problems with answers." },
  { id: "learning-284", title: "Inequalities on a number line", category: "learning", text: "Teach me linear inequalities for Class [10/11] and how to show the solution on a number line. Work through 4 examples with [inequality], explain open and closed circles, then give me 6 practice questions with answers at the end." },
  { id: "learning-285", title: "Surface area of a cube and cuboid", category: "learning", text: "Explain how to find the surface area of a cube and a cuboid for Class [9/10] with a diagram of each shape and the formula written clearly. Work out 3 examples using [measurements], then give me 5 practice problems with answers." },
  { id: "learning-286", title: "Volume of a cylinder and cone", category: "learning", text: "Show me how to find the volume of a cylinder and a cone for Class [10] using [radius and height], with a diagram and the formula for each. Explain why the cone is one-third of the cylinder, then give me 5 practice problems with answers." },
  { id: "learning-287", title: "Surface area and volume of a sphere", category: "learning", text: "Teach me the surface area and volume of a sphere and a hemisphere for Class 10, with the formulas and a labelled diagram. Work out 3 examples using [radius], like a ball or a bowl, then give me 5 practice questions with answers." },
  { id: "learning-288", title: "Heron's formula for triangle area", category: "learning", text: "Explain Heron's formula for the area of a triangle for Class 9, step by step, using [side lengths]. Show how to find the semi-perimeter first, then work the formula, and give me 4 triangle problems to practise with answers." },
  { id: "learning-289", title: "Circle theorems with diagrams", category: "learning", text: "Teach me three circle theorems for Class 10, like angle in a semicircle and angles in the same segment, with a clear diagram for each. Explain each theorem in simple words, then give me 4 diagram questions with answers." },
  { id: "learning-290", title: "Tangents to a circle explained", category: "learning", text: "Explain tangents to a circle for Class 10 in simple words, with a labelled diagram showing the radius, tangent and point of contact. Prove why the radius is perpendicular to the tangent, then give me 4 practice questions with answers." },
  { id: "learning-291", title: "Construction with compass and ruler", category: "learning", text: "Guide me to construct a triangle, angle bisector and perpendicular bisector for Class [9/10] using only a compass and ruler. Give each step in order, tell me what to check after each step, and use [measurements] for the worked example." },
  { id: "learning-292", title: "Data handling with bar graphs", category: "learning", text: "Teach me data handling for Class [7/8] by making a bar graph from [school data, like favourite sports or tiffin choices]. Explain how to choose the scale and label axes, then give me a table of data to turn into a bar graph." },
  { id: "learning-293", title: "Pie charts from school data", category: "learning", text: "Show me how to make a pie chart for Class [8] from data like [how 30 students travel to school]. Work out the angle for each part, explain how to draw it with a protractor, then give me a new data set to try." },
  { id: "learning-294", title: "Histograms and frequency tables", category: "learning", text: "Explain histograms and frequency tables for Class [9/10] using [marks of 20 students]. Show how to group the data into class intervals, draw the histogram, and read the tallest bar, then give me a practice data set with answers." },
  { id: "learning-295", title: "Probability with playing cards", category: "learning", text: "Teach me probability with a deck of playing cards for Class [10], using examples like drawing a king, a red card, or a face card. Explain the total outcomes first, then work out 6 probabilities step by step with answers." },
  { id: "learning-296", title: "Heights and distances with trigonometry", category: "learning", text: "Explain heights and distances in trigonometry for Class 10 using [a building or tree] and angles of elevation and depression. Draw the diagram, show which ratio to use, and solve 3 problems step by step with answers." },
  { id: "learning-297", title: "Trigonometric identities practice", category: "learning", text: "Teach me trigonometric identities for Class 10, like sin squared theta plus cos squared theta equals 1, with a simple proof for each. Show how to use them to simplify 4 expressions, then give me 6 identity problems to practise with answers." },
  { id: "learning-298", title: "Arithmetic progression problems", category: "learning", text: "Explain arithmetic progression for Class 10 using [first term and common difference], and show how to find the nth term and the sum of n terms. Work out 4 examples, then give me 6 AP problems with answers at the end." },
  { id: "learning-299", title: "Geometric progression basics", category: "learning", text: "Teach me geometric progression for Class [10/11] in simple words, using examples like [doubling money or bacteria growth]. Show the formula for the nth term, work out 3 examples, then give me 5 practice questions with answers." },
  { id: "learning-300", title: "Patterns in square numbers", category: "learning", text: "Show me patterns in square numbers for Class [8] using a table from 1 squared to 20 squared, and tricks to spot squares quickly. Explain odd-number patterns and ending digits, then give me 10 quick questions to test myself with answers." },
  { id: "learning-301", title: "Cube roots by prime factorisation", category: "learning", text: "Teach me how to find cube roots by prime factorisation for Class 8, step by step, using [number] as the worked example. Explain how to group factors in threes, then give me 6 numbers to find cube roots for, with answers." },
  { id: "learning-302", title: "Maths formula sheet for Class 10 board exam", category: "learning", text: "Make a one-page maths formula sheet for the Class 10 board exam covering algebra, geometry, trigonometry and mensuration. List each formula with what every letter means, in the order I will use them, and keep it short enough to revise in 10 minutes." },
  { id: "learning-303", title: "Maths homework checker for Class 8", category: "learning", text: "Check my Class 8 maths homework answers for [chapter]: [paste my answers]. Mark each one right or wrong, explain the mistake in simple words where I went wrong, show the correct working, and give me one similar sum to retry." },
  { id: "learning-304", title: "Word problems with two unknowns", category: "learning", text: "Help me solve word problems with two unknown numbers for Class [9/10], like the cost of two items or two ages, using [problem]. Show how to form two equations, solve them step by step, and check the answer in the original story." },
  { id: "learning-305", title: "Area of a trapezium and rhombus", category: "learning", text: "Teach me the area of a trapezium and a rhombus for Class [8/9], with a labelled diagram and the formula for each shape. Work out 3 examples using [measurements], then give me 5 practice problems with answers at the end." },
  { id: "learning-306", title: "Nutrition and balanced diet for students", category: "learning", text: "Explain a balanced diet for a school student in India for Class [6/8], using a thali with dal, rice, roti, vegetables, curd and fruit. Say what each food group gives the body, then plan one day's meals that a family can afford." },
  { id: "learning-307", title: "Vitamins and deficiency diseases chart", category: "learning", text: "Make a chart of vitamins A, B, C, D and iron for Class [7/8], showing one Indian food source, what it does, and what happens if we lack it. Keep each row to one line, then give me 5 quiz questions from the chart." },
  { id: "learning-308", title: "Plant cell and animal cell diagram labels", category: "learning", text: "Describe a labelled diagram of a plant cell and an animal cell for Class [8/9], naming the parts I must draw and label for the exam. Explain the job of the nucleus, cytoplasm and cell wall in one line each, then list 4 differences." },
  { id: "learning-309", title: "Plant tissues and animal tissues compared", category: "learning", text: "Compare plant tissues and animal tissues for Class 9 in a simple table, with 4 types of each, where they are found, and what they do. Use examples like xylem, phloem, muscle and nerve tissue, then give me 5 questions to test myself." },
  { id: "learning-310", title: "Newton's three laws with Indian examples", category: "learning", text: "Explain Newton's three laws of motion for Class 9 with Indian examples, like a bus stopping suddenly, pushing a cart, and a rocket launch. Give one everyday example and one simple experiment for each law, in plain words." },
  { id: "learning-311", title: "Motion graphs distance-time and velocity-time", category: "learning", text: "Teach me distance-time and velocity-time graphs for Class 9, with a sketch of each type and what a flat, sloping and curved line means. Work out speed from 2 graphs, then give me 3 graph questions with answers." },
  { id: "learning-312", title: "Gravitation and free fall explained", category: "learning", text: "Explain gravitation and free fall for Class 9 in simple words, including why a heavy and a light ball fall together. Use the example of [an object] dropped from a height, then give me 4 questions with answers at the end." },
  { id: "learning-313", title: "Work energy and power problems", category: "learning", text: "Explain work, energy and power for Class 9 with formulas and SI units, using examples like lifting a school bag and climbing stairs. Solve 4 numerical problems step by step, then give me 5 practice questions with answers." },
  { id: "learning-314", title: "Echo and ultrasound in daily life", category: "learning", text: "Explain echo and ultrasound for Class 9, with uses like SONAR, bats, and medical scans in India. Describe how echo is used to find the depth of the sea, then give me 3 numerical problems with answers." },
  { id: "learning-315", title: "Refraction of light through a glass slab", category: "learning", text: "Explain refraction of light through a glass slab for Class 10, with a ray diagram showing incident, refracted and emergent rays. Explain why the ray bends, then give me 4 diagram questions with answers at the end." },
  { id: "learning-316", title: "Lenses and image formation ray diagrams", category: "learning", text: "Teach me lenses and image formation for Class 10, with ray diagrams for a convex lens when the object is near and far. List the nature, size and position of each image in a table, then give me 4 questions with answers." },
  { id: "learning-317", title: "Human eye and common defects", category: "learning", text: "Explain the human eye for Class 10 with a labelled diagram, naming the cornea, lens, retina and optic nerve. Explain myopia and hypermetropia in simple words, what lens corrects each, and give me 5 questions." },
  { id: "learning-318", title: "Ohm's law with circuit problems", category: "learning", text: "Teach me Ohm's law for Class 10 with the formula V = IR, a circuit diagram, and what each letter means. Solve 4 problems using [voltage, current and resistance], then give me 6 practice questions with answers at the end." },
  { id: "learning-319", title: "Series and parallel circuits compared", category: "learning", text: "Compare series and parallel circuits for Class 10 in a table, showing current, voltage and resistance in each, with a diagram of both. Use home wiring and Diwali lights as examples, then give me 5 questions with answers." },
  { id: "learning-320", title: "Electric power and household electricity bill", category: "learning", text: "Show me how to calculate a household electricity bill in India for Class 10, using units, the rate per unit, and appliances like a fan, bulb and fridge. Work out one month's bill step by step, then give me a practice bill to calculate." },
  { id: "learning-321", title: "Electromagnets and electric motor", category: "learning", text: "Explain electromagnets and the electric motor for Class 10 in simple words, with a diagram of each. Say where we use them at home, like in a fan or mixer, then give me 5 questions with answers at the end." },
  { id: "learning-322", title: "Atomic structure protons neutrons electrons", category: "learning", text: "Explain atomic structure for Class 9, with protons, neutrons and electrons, shells, atomic number and mass number. Use [element] as the example, draw the shell diagram in words, then give me 5 questions with answers." },
  { id: "learning-323", title: "Isotopes and their uses simply", category: "learning", text: "Teach me isotopes for Class 9 in simple words, using carbon-12, carbon-14 and hydrogen isotopes as examples. Explain what stays the same and what changes, list 3 uses, then give me 5 quiz questions with answers." },
  { id: "learning-324", title: "Chemical bonding ionic and covalent", category: "learning", text: "Explain ionic and covalent bonding for Class 10 with examples like sodium chloride and water. Show how electrons are transferred or shared in simple diagrams, then give me 6 compounds to classify with answers." },
  { id: "learning-325", title: "Balancing chemical equations step by step", category: "learning", text: "Show me how to balance chemical equations for Class 10 step by step, using [equation] as the worked example. Explain how to count atoms on both sides, then give me 8 equations to balance with answers at the end." },
  { id: "learning-326", title: "Mole concept for Class 11 beginners", category: "learning", text: "Explain the mole concept for Class 11 beginners in India in simple words, with Avogadro's number and molar mass. Work out the number of moles in [grams of a substance], then give me 5 numerical problems with answers." },
  { id: "learning-327", title: "Reactivity series of metals", category: "learning", text: "Teach me the reactivity series of metals for Class 10, in order from potassium to gold, with a simple memory trick. Explain how it predicts displacement reactions, then give me 6 reaction questions with answers." },
  { id: "learning-328", title: "Acids bases and salts with pH scale", category: "learning", text: "Explain acids, bases and salts for Class 10 with the pH scale, using kitchen examples like lemon, soap and baking soda. Show the pH of common things in a table, then give me 6 questions with answers at the end." },
  { id: "learning-329", title: "Carbon compounds and hydrocarbons", category: "learning", text: "Explain carbon compounds and hydrocarbons for Class 10, with alkanes, alkenes and alkynes, and their general formulas. Give one example and one use for each group, then give me 6 questions with answers." },
  { id: "learning-330", title: "Soaps detergents and cleaning action", category: "learning", text: "Explain how soaps and detergents clean for Class 10, with micelle formation in simple words and a diagram described step by step. Compare soap and detergent for hard water, then give me 5 questions with answers." },
  { id: "learning-331", title: "Reproduction in flowering plants", category: "learning", text: "Explain reproduction in flowering plants for Class 10, with a labelled diagram of a flower showing stamen and pistil. Describe pollination and fertilisation in order, then give me 5 questions with answers at the end." },
  { id: "learning-332", title: "Human reproduction system diagram notes", category: "learning", text: "Explain the human reproductive system for Class 10 in simple, exam-safe words, with the main parts and their jobs listed clearly. Focus on what the board exam asks, then give me 5 questions with answers." },
  { id: "learning-333", title: "Heredity and Mendel's experiments", category: "learning", text: "Explain heredity and Mendel's experiments for Class 10, using pea plants, dominant and recessive traits, and a Punnett square. Work out a cross step by step, then give me 4 genetics problems with answers." },
  { id: "learning-334", title: "DNA genes and traits explained", category: "learning", text: "Explain DNA, genes and traits for Class 10 in simple words, using examples like eye colour and attached earlobes in Indian families. Describe how traits pass from parents to children, then give me 5 questions with answers." },
  { id: "learning-335", title: "Evolution and fossils in India", category: "learning", text: "Explain evolution and fossils for Class 10 in simple words, with Indian examples like fossils found in [place] and how they show change over time. List 3 pieces of evidence for evolution, then give me 5 questions." },
  { id: "learning-336", title: "Coal petroleum and natural gas", category: "learning", text: "Explain coal, petroleum and natural gas for Class [8/10], how they formed, and why they are called exhaustible resources. List their main uses in India and 3 ways to save them, then give me 5 questions with answers." },
  { id: "learning-337", title: "Air pollution causes and control", category: "learning", text: "Explain air pollution for Class [8/9], its main causes in Indian cities, health effects, and 5 ways to control it at home and in school. Give one example for each pollutant, then make 5 quiz questions with answers." },
  { id: "learning-338", title: "Water pollution and purification at home", category: "learning", text: "Explain water pollution and purification at home for Class [8/9], including boiling, filtering and chlorination in simple steps. List 4 sources of pollution in Indian rivers, then give me 5 questions with answers." },
  { id: "learning-339", title: "Microorganisms and common diseases", category: "learning", text: "Explain microorganisms and common diseases for Class 8, with bacteria, virus and fungi, and how they spread. List 4 diseases, their cause and one way to prevent each, then give me 5 questions with answers." },
  { id: "learning-340", title: "Vaccination and immunity simply", category: "learning", text: "Explain vaccination and immunity for Class [8/9] in simple words, using examples like polio, BCG and tetanus in India. Describe how a vaccine trains the body, then give me 5 questions with answers at the end." },
  { id: "learning-341", title: "Food preservation methods at home", category: "learning", text: "Explain food preservation methods at home for Class 8, like drying, pickling, freezing and adding salt or sugar, with one Indian example for each. Say why each method stops germs, then give me 5 questions with answers." },
  { id: "learning-342", title: "Sound pollution and noise control", category: "learning", text: "Explain sound pollution for Class [8/9], its sources in Indian towns, like traffic, loudspeakers and construction, and its effects on health and study. List 5 ways to reduce noise, then give me 5 questions with answers." },
  { id: "learning-343", title: "Friction and its uses in daily life", category: "learning", text: "Explain friction for Class 8 with daily examples in India, like walking on a road, writing with a pencil, and a cycle brake. List 3 ways to increase and 3 ways to reduce friction, then give me 5 questions with answers." },
  { id: "learning-344", title: "Pressure in liquids and hydraulic machines", category: "learning", text: "Explain pressure in liquids for Class [8/9], including why dams are thicker at the bottom and how a hydraulic lift works. Give the formula, solve 3 problems, then give me 5 practice questions with answers." },
  { id: "learning-345", title: "Science lab record write-up for an experiment", category: "learning", text: "Help me write a science lab record for [experiment name] for Class [9/10], with aim, materials, procedure, observations, result and precautions. Keep the language simple and neat, ready to copy into my practical notebook." },
  { id: "learning-346", title: "Homophones and confusing word pairs", category: "learning", text: "Teach me 15 homophones for Class [7/8], like there/their, hear/here and buy/by, with one sentence for each pair showing the difference. Then give me 10 fill-in-the-blank sentences to practise, with answers at the end." },
  { id: "learning-347", title: "Synonyms and antonyms word bank", category: "learning", text: "Make a word bank of 20 synonyms and antonyms for Class [7/8], using common exam words like happy, brave, begin and difficult. Give one example sentence for each pair, then give me a 10-question quiz with answers." },
  { id: "learning-348", title: "One-word substitution practice", category: "learning", text: "Teach me one-word substitution for Class [8/9] with 20 common exam words, like a person who loves books, with the meaning and one example sentence each. Then give me 10 questions to practise, with answers at the end." },
  { id: "learning-349", title: "Jumbled sentences rearrangement", category: "learning", text: "Give me 15 jumbled sentences for Class [7/8] to rearrange into correct English, starting easy and getting harder. Cover statements, questions and negatives, and give the correct order with a short reason for each answer." },
  { id: "learning-350", title: "Cloze passage practice for exams", category: "learning", text: "Make a cloze passage practice for Class [9/10] on [topic], with 10 blanks and 3 options for each blank. The passage should be about 120 words, on an Indian topic, with answers and a one-line reason for each." },
  { id: "learning-351", title: "Notice writing for school board", category: "learning", text: "Help me write a notice for the school notice board about [event, like a science exhibition or sports day], for Class [8/9]. Include the heading, date, time, venue and contact, in the correct format, under 50 words, ready to copy." },
  { id: "learning-352", title: "Diary entry writing for school", category: "learning", text: "Help me write a diary entry for Class [8/9] about [a school trip or a special day], in first person and simple English. Include the date, feelings, what happened in order, and a closing line, in about 100 words." },
  { id: "learning-353", title: "Article writing for school magazine", category: "learning", text: "Help me write an article for the school magazine on [topic, like saving water or reading habits], for Class [9/10]. Give a title, introduction, 3 points with examples, and a conclusion, in about 150 words in simple English." },
  { id: "learning-354", title: "Report writing for a school event", category: "learning", text: "Help me write a report for Class [9/10] about a school event like [annual day or a clean-up drive], in the correct format with heading, byline, date and place. Cover what, when, where and who, in about 120 words." },
  { id: "learning-355", title: "Dialogue writing between two friends", category: "learning", text: "Write a dialogue between two friends for Class [8/9] about [topic, like preparing for exams or planning a trip], with 10 exchanges in simple, natural English. Give each speaker a name, and keep the lines short and realistic." },
  { id: "learning-356", title: "Story completion with a given beginning", category: "learning", text: "Complete this story for Class [8/9] in about 150 words, starting with: [paste the beginning]. Keep the same characters and setting, add one problem and a happy ending, and use simple English a student can copy and learn from." },
  { id: "learning-357", title: "Picture description practice", category: "learning", text: "Help me describe this picture for Class [7/8]: [describe the picture]. Write a short paragraph in simple English covering what I can see, the people, the place and the mood, in about 80 words, ready for my exam." },
  { id: "learning-358", title: "Unseen passage comprehension practice", category: "learning", text: "Make an unseen passage comprehension practice for Class [9/10] on [an Indian topic], about 200 words, with 5 questions: 3 short answers, 1 vocabulary question and 1 title question, plus answers at the end." },
  { id: "learning-359", title: "Word roots prefixes and suffixes", category: "learning", text: "Teach me word roots, prefixes and suffixes for Class [8/9] with 15 examples, like un-, re-, -ful and -less, showing how each changes the meaning. Give one example word and sentence for each, then a 10-question quiz with answers." },
  { id: "learning-360", title: "Punctuation and capital letters practice", category: "learning", text: "Teach me punctuation and capital letters for Class [6/7] with rules for full stops, commas, question marks and capitals. Give 5 examples for each rule, then give me 10 unpunctuated sentences to correct, with answers at the end." },
  { id: "learning-361", title: "Subject-verb agreement rules", category: "learning", text: "Explain subject-verb agreement for Class [8/9] in simple words, with rules for he/she, they, each, and either-or. Give 5 examples for each rule, then give me 15 sentences to correct, with answers at the end." },
  { id: "learning-362", title: "Modals can may must should practice", category: "learning", text: "Teach me modals can, may, must and should for Class [8/9], with one clear use and 3 examples for each modal. Explain the difference between must and should, then give me 15 fill-in-the-blank sentences with answers." },
  { id: "learning-363", title: "Conditionals if clauses explained", category: "learning", text: "Explain conditionals and if clauses for Class [9/10] in simple words, covering type 1, type 2 and type 3 with one Indian example each. Give 5 examples per type, then give me 12 sentences to complete, with answers." },
  { id: "learning-364", title: "Question tags practice", category: "learning", text: "Teach me question tags for Class [8/9], like is it not and do you not, with rules for positive and negative statements. Give 10 examples, explain the tricky cases, then give me 15 sentences to add tags to, with answers." },
  { id: "learning-365", title: "Editing a paragraph for errors", category: "learning", text: "Check and edit this paragraph for Class [8/9]: [paste the paragraph]. Find and correct spelling, grammar and punctuation mistakes, show each correction with a short reason, and give me the clean final paragraph to copy." },
  { id: "learning-366", title: "Prose lesson summary for Class 10 English", category: "learning", text: "Summarise this Class 10 English prose lesson for me: [paste the lesson name or text]. Give the story in order, the main characters, 3 important lines, and the moral, in simple English under 200 words." },
  { id: "learning-367", title: "Poetry analysis stanza by stanza", category: "learning", text: "Analyse this poem stanza by stanza for Class [9/10]: [paste the poem or its name]. Explain each stanza in simple words, name one figure of speech per stanza, and give the theme and the poet's message at the end." },
  { id: "learning-368", title: "Character sketch from a lesson", category: "learning", text: "Write a character sketch of [character name] from our Class [9/10] English lesson, in about 120 words. Cover their nature, 3 qualities with one example each from the story, and why the character matters to the lesson." },
  { id: "learning-369", title: "Theme and moral of a story", category: "learning", text: "Explain the theme and moral of this story for Class [8/9]: [paste the story name]. Give the central idea in one line, 3 points that support it, and a real-life example from India that shows the same moral." },
  { id: "learning-370", title: "Formal invitation writing for school", category: "learning", text: "Help me write a formal invitation for a school function like [annual day or farewell], for Class [9/10]. Include the occasion, date, time, venue and chief guest in the correct format, in simple English, under 60 words." },
  { id: "learning-371", title: "Email to the principal practice", category: "learning", text: "Help me write an email to the principal of my school asking for [leave / a certificate / permission], for Class [9/10]. Keep it polite, short and in the correct format, with subject, greeting and closing, ready to copy." },
  { id: "learning-372", title: "Leave application to the class teacher", category: "learning", text: "Help me write a leave application to my class teacher for [reason and dates], for Class [6/8]. Keep it in the correct school format, polite and short, with date, subject and signature line, ready to copy into my notebook." },
  { id: "learning-373", title: "Speech writing for morning assembly", category: "learning", text: "Help me write a 2-minute speech for the morning assembly on [topic, like discipline or saving water], for Class [8/9]. Start with a greeting, give 3 points with one example each, and end with a line the class can remember." },
  { id: "learning-374", title: "Reading a poem aloud with expression", category: "learning", text: "Help me read this poem aloud with expression for Class [7/8]: [paste the poem]. Mark where to pause, which words to stress, and where to speak softly or loudly, line by line, so I can practise and perform it well." },
  { id: "learning-375", title: "Vocabulary from the newspaper daily", category: "learning", text: "Help me build English vocabulary from the newspaper daily for Class [9/10]. Pick 10 words from [today's newspaper or a topic], give the meaning, pronunciation in simple letters, and one sentence each using Indian examples." },
  { id: "learning-376", title: "Revolt of 1857 causes and results", category: "learning", text: "Explain the Revolt of 1857 for Class 8, its causes, main leaders, important centres like Delhi, Kanpur and Lucknow, and its results. Present it as a timeline, then give me 5 questions with answers at the end." },
  { id: "learning-377", title: "Non-cooperation movement explained", category: "learning", text: "Explain the Non-cooperation Movement for Class 10, why Gandhi started it, what people did, and why it was withdrawn. Give the dates, 3 key events, and its impact, then give me 5 questions with answers." },
  { id: "learning-378", title: "Civil Disobedience and Salt March", category: "learning", text: "Explain the Civil Disobedience Movement and the Salt March for Class 10, step by step from Dandi to the Round Table Conference. Give the dates and 3 key leaders, then give me 5 questions with answers at the end." },
  { id: "learning-379", title: "Quit India Movement 1942", category: "learning", text: "Explain the Quit India Movement of 1942 for Class 10 in simple words, why it started, what happened, and how the British reacted. List 4 important leaders, then give me 5 questions with answers at the end." },
  { id: "learning-380", title: "Partition of India 1947 explained", category: "learning", text: "Explain the Partition of India in 1947 for Class 10 in simple, sensitive words, why it happened, what changed, and its human impact. Give the key dates, then give me 5 questions with answers at the end." },
  { id: "learning-381", title: "Making of the Indian Constitution", category: "learning", text: "Explain how the Indian Constitution was made for Class [8/9], who wrote it, how long it took, and its main features. Name 3 members of the Constituent Assembly, then give me 5 questions with answers." },
  { id: "learning-382", title: "Fundamental Rights with examples", category: "learning", text: "Explain the Fundamental Rights in the Indian Constitution for Class [8/9], with one everyday example for each right. Use examples a student can relate to, like freedom of speech and equality, then give me 5 questions with answers." },
  { id: "learning-383", title: "Fundamental Duties for students", category: "learning", text: "Explain the Fundamental Duties for a Class [8/9] student in India, listing each duty in simple words with one example of how a student can follow it. Then give me 5 questions with answers at the end." },
  { id: "learning-384", title: "Directive Principles of State Policy", category: "learning", text: "Explain the Directive Principles of State Policy for Class [9/10] in simple words, what they guide the government to do, and how they differ from Fundamental Rights. Give 4 examples, then give me 5 questions with answers." },
  { id: "learning-385", title: "Panchayati Raj and village government", category: "learning", text: "Explain Panchayati Raj and village government for Class [8/9], with gram sabha, gram panchayat, sarpanch and their jobs. Use an example of a village in India, then give me 5 questions with answers at the end." },
  { id: "learning-386", title: "Municipality and city government", category: "learning", text: "Explain how a municipality and city government work for Class [8/9], with the mayor, councillors and their jobs like water, roads and waste. Use [my town] as the example, then give me 5 questions with answers." },
  { id: "learning-387", title: "How the Indian judiciary works", category: "learning", text: "Explain how the Indian judiciary works for Class [8/9], with the Supreme Court, High Courts and district courts, and what each one does. Use one simple case example, then give me 5 questions with answers." },
  { id: "learning-388", title: "Latitude longitude and time zones", category: "learning", text: "Teach me latitude, longitude and time zones for Class [7/8], with a diagram described in words and the Indian Standard Time example. Explain why India has one time zone, then give me 5 questions with answers." },
  { id: "learning-389", title: "Monsoon in India explained simply", category: "learning", text: "Explain the monsoon in India for Class [9/10], the southwest and northeast monsoons, when they arrive, and how they affect farming. Give the months and 3 states, then give me 5 questions with answers at the end." },
  { id: "learning-390", title: "Major crops rice wheat and millets", category: "learning", text: "Explain the major crops of India for Class [10], rice, wheat and millets, with where they grow, the season, and the climate they need. Make a table comparing the three, then give me 5 questions with answers." },
  { id: "learning-391", title: "Industries in India location and types", category: "learning", text: "Explain industries in India for Class 10, their location and types, like cotton textiles, iron and steel, and IT, with one example city for each. Give 3 factors that decide location, then give me 5 questions with answers." },
  { id: "learning-392", title: "Transport and communication in India", category: "learning", text: "Explain transport and communication in India for Class 10, covering roads, railways, waterways, airways and mobile networks. Give one fact and one use for each, then give me 5 questions with answers at the end." },
  { id: "learning-393", title: "Population of India facts and trends", category: "learning", text: "Explain the population of India for Class [9/10], its size, growth, density and age structure, with simple numbers a student can remember. List 3 causes of growth and 3 effects, then give me 5 questions with answers." },
  { id: "learning-394", title: "Sectors of the Indian economy", category: "learning", text: "Explain the primary, secondary and tertiary sectors of the Indian economy for Class 10, with 3 examples for each sector. Use jobs like farming, factory work and teaching, then give me 5 questions with answers." },
  { id: "learning-395", title: "Money and banking in India", category: "learning", text: "Explain money and banking in India for Class 10, what banks do, savings accounts, loans and the role of the RBI. Use a student's savings account as the example, then give me 5 questions with answers." },
  { id: "learning-396", title: "Demand and supply with market examples", category: "learning", text: "Explain demand and supply for Class [10/11] with market examples from India, like onion prices rising when supply falls. Draw the idea in words, give 3 examples, then give me 5 questions with answers at the end." },
  { id: "learning-397", title: "Poverty in India causes and schemes", category: "learning", text: "Explain poverty in India for Class [9/10], its causes, how it is measured, and government schemes that help, like [scheme]. Give 3 causes and 3 schemes, then give me 5 questions with answers at the end." },
  { id: "learning-398", title: "Unemployment types in India", category: "learning", text: "Explain types of unemployment in India for Class [9/10], like seasonal, educated and disguised unemployment, with one example for each. List 3 causes and 3 solutions, then give me 5 questions with answers." },
  { id: "learning-399", title: "Consumer rights in India simply", category: "learning", text: "Explain consumer rights in India for Class 10 in simple words, with the right to safety, information, choice and redressal. Give one shop example for each right, then give me 5 questions with answers at the end." },
  { id: "learning-400", title: "Sustainable development goals for students", category: "learning", text: "Explain the Sustainable Development Goals for a Class [9/10] student in simple words, with 5 goals that matter most for India. Give one action a student can take for each goal, then give me 5 questions with answers." },
  { id: "learning-401", title: "Disaster management in school", category: "learning", text: "Explain disaster management in school for Class [8/9], what to do during an earthquake, fire and flood, with a step-by-step plan for each. Include a mock drill checklist, then give me 5 questions with answers." },
  { id: "learning-402", title: "Soil erosion and conservation", category: "learning", text: "Explain soil erosion and conservation for Class [10], its causes in India, like deforestation and overgrazing, and ways to stop it. List 4 conservation methods, then give me 5 questions with answers at the end." },
  { id: "learning-403", title: "Wildlife conservation in India", category: "learning", text: "Explain wildlife conservation in India for Class [8/9], why it matters, and projects like Project Tiger and Project Elephant. Name 3 national parks and one animal each, then give me 5 questions with answers." },
  { id: "learning-404", title: "Mineral resources of India", category: "learning", text: "Explain mineral resources of India for Class 10, where iron, coal, bauxite and mica are found, and what they are used for. Make a table with state and use, then give me 5 questions with answers." },
  { id: "learning-405", title: "Social science map work practice", category: "learning", text: "Give me map work practice for Class [9/10] social science, with 10 places to mark on an outline map of India, like rivers, states and ports. List the places, say what to label, and give the answers in a separate list." },
  { id: "learning-406", title: "Binary number system for Class 9", category: "learning", text: "Teach me the binary number system for Class 9 computers, how 0 and 1 work, and how to convert decimal numbers to binary. Work out 5 conversions step by step, then give me 8 numbers to convert with answers." },
  { id: "learning-407", title: "Computer memory units explained", category: "learning", text: "Explain computer memory units for Class [8/9], from bits and bytes to KB, MB, GB and TB, with a simple table and real examples like a photo or a movie. Then give me 8 conversion questions with answers." },
  { id: "learning-408", title: "Input and output devices chart", category: "learning", text: "Make a chart of input and output devices for Class [6/7], with 8 devices in each group, what each one does, and one example of using it at home or school. Then give me 10 devices to classify, with answers." },
  { id: "learning-409", title: "File and folder organisation on a computer", category: "learning", text: "Teach me how to organise files and folders on a computer for school work, with a folder plan for subjects, homework and projects. Explain naming files clearly, then give me a checklist to set up my folders today." },
  { id: "learning-410", title: "Google Docs formatting for school work", category: "learning", text: "Teach me Google Docs formatting for school work, including headings, bold, lists, tables and page numbers. Give each step in order for [a school assignment], then give me a 10-point checklist to finish and check my document." },
  { id: "learning-411", title: "Make a table in HTML for a webpage", category: "learning", text: "Teach me how to make a table in HTML for a webpage for Class [9/10], using [a school timetable] as the example. Give the code for rows and columns, explain each tag, and show how to add a heading row." },
  { id: "learning-412", title: "Python if else conditions practice", category: "learning", text: "Teach me if-else conditions in Python for Class [9/10] beginners, with 5 simple programs like checking pass marks, odd or even, and the greater of two numbers. Explain each line, then give me 3 programs to write myself." },
  { id: "learning-413", title: "Python loops for beginners", category: "learning", text: "Teach me loops in Python for Class [9/10], for loops and while loops, with 5 examples like printing tables, counting, and adding numbers. Explain each line simply, then give me 3 loop programs to write and test." },
  { id: "learning-414", title: "Python lists and functions basics", category: "learning", text: "Explain Python lists and functions for Class [10/11] beginners, with examples like a list of student names and a function to find the average marks. Show the code and the output, then give me 3 tasks to try." },
  { id: "learning-415", title: "Scratch sprite movement project", category: "learning", text: "Teach me Scratch sprite movement for Class [6/7], how to make a sprite move, turn, and bounce off the edge. Give a step-by-step project using [a cat or a car], then give me 3 small changes to try on my own." },
  { id: "learning-416", title: "Stay safe from phishing messages", category: "learning", text: "Teach me how to stay safe from phishing messages for Class [8/9], with Indian examples like fake bank, courier and job messages on WhatsApp and SMS. List 5 warning signs, then give me 6 messages to judge as safe or fake." },
  { id: "learning-417", title: "AI tools for school homework safely", category: "learning", text: "Show me how to use AI tools for school homework safely for Class [9/10], what to ask, how to check the answer in my textbook, and what never to copy blindly. Give 5 good prompts and 3 rules to follow every time." },
  { id: "learning-418", title: "Cornell notes for a science chapter", category: "learning", text: "Teach me Cornell notes for a science chapter for Class [9/10], with the cue column, notes column and summary box explained clearly. Use [chapter name] as the example, then give me a blank Cornell layout I can copy for my next chapter." },
  { id: "learning-419", title: "Science working model project plan", category: "learning", text: "Plan a science working model project for Class [8/9] on [topic, like a water pump or a windmill], using materials from home or a local shop. List the materials, steps, working, and 5 lines to explain it to the judges." },
  { id: "learning-420", title: "Maths project report for school", category: "learning", text: "Help me write a maths project report for school on [topic, like symmetry or mensuration], for Class [8/9]. Give the format with aim, introduction, examples, diagrams to draw, and conclusion, in simple English, ready to present." },
  { id: "learning-421", title: "Speak English at a vegetable market", category: "learning", text: "Teach me English sentences to use at a vegetable market in India, like asking the price of [vegetable], asking for half a kilo, and bargaining politely. Give me 12 useful sentences with simple meanings, plus a short practice dialogue with a vendor." },
  { id: "learning-422", title: "Speak English on a phone call", category: "learning", text: "Help me practise English for a phone call to [a shop / a school / an office]. Give me opening lines, polite ways to ask someone to repeat slowly, and closing lines. Add a short sample call I can read aloud twice a day." },
  { id: "learning-423", title: "Speak English in a job interview", category: "learning", text: "Prepare me for a job interview in English for the post of [job role]. Give me simple answers for tell me about yourself, your strengths, and why you want this job, plus five questions I can ask the interviewer at the end." },
  { id: "learning-424", title: "Speak English at a doctor visit", category: "learning", text: "Teach me English sentences for a doctor visit in India, like describing a fever, headache, or stomach pain, and asking about medicine timing. Give me 15 useful sentences, the meaning of each, and a short sample conversation at a clinic." },
  { id: "learning-425", title: "Speak English while travelling by train", category: "learning", text: "Give me English sentences for a train journey in India, like asking for my berth, asking about the next station, and requesting help with luggage. Include 12 sentences, simple meanings, and a short dialogue with a fellow passenger." },
  { id: "learning-426", title: "Speak English at a bank counter", category: "learning", text: "Teach me English for visiting a bank in India, like opening an account, asking about a passbook, and reporting a lost ATM card. Give me 12 polite sentences, explain any hard words simply, and add a short sample talk with a bank clerk." },
  { id: "learning-427", title: "Speak English with a new neighbour", category: "learning", text: "Help me start a friendly English conversation with a new neighbour in India. Give me greetings, questions about their family and hometown, and polite closing lines. Add a short dialogue I can practise aloud for [number] minutes a day." },
  { id: "learning-428", title: "Speak English at a school parents meeting", category: "learning", text: "Teach me English sentences for a parents meeting at my child’s school, like asking about marks, homework, and behaviour. Give me 12 polite questions and answers, explain hard words simply, and add a short sample talk with a teacher." },
  { id: "learning-429", title: "Speak English when ordering food", category: "learning", text: "Give me English sentences for ordering food at a restaurant in India, including asking for a Jain meal without onion and garlic, asking for less spicy food, and asking for the bill. Add 12 sentences and a short dialogue with a waiter." },
  { id: "learning-430", title: "Speak English at a hotel check-in", category: "learning", text: "Teach me English for checking into a hotel in India, like confirming my booking, asking for a quiet room, and asking about breakfast timing. Give me 12 useful sentences with meanings and a short sample conversation at the reception desk." },
  { id: "learning-431", title: "Speak English in a team meeting", category: "learning", text: "Help me speak English in a team meeting at work in India. Give me polite ways to share an idea, agree with a colleague, disagree softly, and ask for more time. Add 12 sentences and a short sample meeting talk about [topic]." },
  { id: "learning-432", title: "Speak English for a presentation", category: "learning", text: "Help me prepare a short English presentation of [number] minutes on [topic] for my class or office. Give me a simple opening, three clear points with one example each, useful linking words, and a confident closing line I can practise aloud." },
  { id: "learning-433", title: "Speak English at a shop return", category: "learning", text: "Teach me English sentences for returning a faulty item to a shop in India, like explaining the problem politely, asking for a replacement, and asking about the refund. Give me 12 sentences with meanings and a short sample talk with a shopkeeper." },
  { id: "learning-434", title: "Speak English while asking directions", category: "learning", text: "Give me English sentences for asking directions in an Indian city, like asking how to reach [place], how far it is, and whether to take a bus or auto. Include 12 sentences, simple meanings, and a short dialogue with a stranger on the road." },
  { id: "learning-435", title: "Speak English in small talk at work", category: "learning", text: "Teach me English small talk for the office in India, like talking about the weather, the weekend, lunch, and traffic. Give me 12 easy questions and replies, explain when to use each one, and add a short sample chat with a colleague." },
  { id: "learning-436", title: "English conditionals for everyday plans", category: "learning", text: "Explain English conditionals in simple words using everyday Indian examples, like if it rains, we will stay home. Cover if, unless, and would, give five examples for each type, and finish with ten sentences about [plan] for me to complete." },
  { id: "learning-437", title: "English modal verbs can could should", category: "learning", text: "Teach me English modal verbs can, could, should, must, and may with simple rules and everyday examples from India. Give five examples for each verb, explain the polite difference between can and could, and add ten practice sentences about [situation]." },
  { id: "learning-438", title: "English question tags in conversation", category: "learning", text: "Explain English question tags like isn’t it and don’t you in simple words, with everyday Indian examples. Show how to form them from positive and negative sentences, give ten examples, and add ten sentences about [topic] for me to add the correct tag." },
  { id: "learning-439", title: "English comparatives for shopping choices", category: "learning", text: "Teach me English comparatives like cheaper, bigger, and better using shopping examples in India, such as comparing two shirts or two phones. Explain the rules for short and long words, give ten examples, and add ten sentences comparing [item 1] and [item 2]." },
  { id: "learning-440", title: "English conjunctions to join sentences", category: "learning", text: "Teach me English conjunctions and, but, because, so, and although in simple words, with everyday examples from Indian life. Give five examples for each word, explain how each one joins two ideas, and add ten short sentence pairs about [topic] for me to join." },
  { id: "learning-441", title: "English words for office work", category: "learning", text: "Teach me 20 useful English words for office work in India, like meeting, deadline, report, and leave application. For each word, give a simple meaning, one example sentence from office life, and a quick way to remember it." },
  { id: "learning-442", title: "English words for train travel", category: "learning", text: "Teach me 20 useful English words for train travel in India, like platform, berth, ticket, and delay. For each word, give a simple meaning and one example sentence about a journey to [city], plus a short dialogue using five of the words." },
  { id: "learning-443", title: "English words for cooking and food", category: "learning", text: "Teach me 20 useful English words for cooking and food in an Indian kitchen, like boil, fry, steam, and taste. For each word, give a simple meaning and one example sentence using [dish], and add a short recipe description using five of the words." },
  { id: "learning-444", title: "English words for weather and seasons", category: "learning", text: "Teach me 20 useful English words for weather and seasons in India, like humid, drizzle, heatwave, and monsoon. For each word, give a simple meaning and one example sentence about [season] in [city], plus a short weather talk I can practise aloud." },
  { id: "learning-445", title: "English words for money and shopping", category: "learning", text: "Teach me 20 useful English words for money and shopping in India, like discount, receipt, change, and budget. For each word, give a simple meaning and one example sentence about buying [item], and add a short shop dialogue using five of the words." },
  { id: "learning-446", title: "Hindi numbers for shopping and bills", category: "learning", text: "Teach me Hindi numbers from 1 to 100 for shopping and paying bills in India. Write each number in Roman letters with its meaning, show how to say prices like ₹[amount], and give me ten practice sentences for asking prices at a shop." },
  { id: "learning-447", title: "Hindi polite requests at home", category: "learning", text: "Teach me polite Hindi requests to use at home in India, like asking for water, asking someone to close the door, and asking for help with homework. Give me 15 sentences in Roman letters with meanings, and explain when to use please politely." },
  { id: "learning-448", title: "Hindi conversation at a tea shop", category: "learning", text: "Give me a simple Hindi conversation for a tea shop in India, ordering chai, asking for less sugar, and paying the bill. Write each line in Roman letters with its meaning, and add ten useful words for tea, snacks, and payment." },
  { id: "learning-449", title: "Hindi words for family members", category: "learning", text: "Teach me Hindi words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Hindi." },
  { id: "learning-450", title: "Hindi sentences for asking directions", category: "learning", text: "Teach me Hindi sentences for asking directions in an Indian city, like asking how to reach [place], how far it is, and which road to take. Write each sentence in Roman letters with its meaning, and add a short dialogue with a passer-by." },
  { id: "learning-451", title: "Hindi verbs for daily routines", category: "learning", text: "Teach me 15 common Hindi verbs for daily routines, like wake up, brush teeth, eat, go, and sleep. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph about my day in Hindi." },
  { id: "learning-452", title: "Hindi greetings for festivals", category: "learning", text: "Teach me Hindi greetings for Indian festivals like Diwali, Holi, and Raksha Bandhan, including how to wish family and neighbours. Write each greeting in Roman letters with its meaning, and give me a short festival message I can send on WhatsApp." },
  { id: "learning-453", title: "Hindi words for vegetables and food", category: "learning", text: "Teach me Hindi words for 20 vegetables and foods used in an Indian kitchen, like potato, tomato, rice, and dal. Write each word in Roman letters with its meaning, and give me a short market list in Hindi I can practise reading aloud." },
  { id: "learning-454", title: "Hindi sentences for a train journey", category: "learning", text: "Give me Hindi sentences for a train journey in India, like asking for my seat, asking about food, and asking when the train reaches [station]. Write each sentence in Roman letters with its meaning, and add a short dialogue with a fellow traveller." },
  { id: "learning-455", title: "Hindi words for colours and clothes", category: "learning", text: "Teach me Hindi words for ten colours and ten clothes, like red, blue, kurta, and saree. Write each word in Roman letters with its meaning, give one example sentence for each colour, and add a short talk about what I am wearing today." },
  { id: "learning-456", title: "Hindi story retelling for practice", category: "learning", text: "Tell me a short simple story in Hindi of about 120 words, about [a clever rabbit / a kind farmer], written in Roman letters with an English meaning after each line. Then ask me five easy questions about the story so I can practise retelling it in my own words." },
  { id: "learning-457", title: "Hindi tongue twisters for clear speech", category: "learning", text: "Give me ten easy Hindi tongue twisters in Roman letters to improve my clear speech and pronunciation. Explain the hard sounds in each one simply, tell me how to practise slowly first, and add a five-minute daily routine for [number] days." },
  { id: "learning-458", title: "Hindi film dialogue for listening", category: "learning", text: "Pick a simple famous Hindi film dialogue about [friendship / family] and explain it line by line in easy English. Tell me the meaning of the hard words, how the tone changes the feeling, and give me three similar lines I can practise saying aloud." },
  { id: "learning-459", title: "Hindi writing practice in Devanagari", category: "learning", text: "Teach me to write ten simple Hindi words in Devanagari script, starting with easy letters and two-letter words. Show each word in Devanagari and Roman letters, explain how to form the letters, and give me a short copying exercise using my name and [city]." },
  { id: "learning-460", title: "Hindi translation of English signs", category: "learning", text: "Give me Hindi translations in Roman letters for 15 common English signs in India, like no parking, keep clean, and ticket counter. Explain any hard word simply, and add a short practice where I translate five new signs about [place] myself." },
  { id: "learning-461", title: "Tamil numbers for counting money", category: "learning", text: "Teach me Tamil numbers from 1 to 100 for counting money in Tamil Nadu. Write each number in Roman letters with its meaning, show how to say prices like ₹[amount], and give me ten practice sentences for paying at a shop or auto stand." },
  { id: "learning-462", title: "Tamil sentences at a bus stop", category: "learning", text: "Teach me Tamil sentences for a bus stop in Tamil Nadu, like asking which bus goes to [place], asking the fare, and asking for a ticket. Write each sentence in Roman letters with its meaning, and add a short dialogue with a conductor." },
  { id: "learning-463", title: "Tamil words for family and relatives", category: "learning", text: "Teach me Tamil words for family and relatives like mother, father, elder sister, younger brother, and uncle. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Tamil." },
  { id: "learning-464", title: "Tamil conversation at a flower market", category: "learning", text: "Give me a simple Tamil conversation for a flower market in Tamil Nadu, buying jasmine, asking the price, and bargaining politely. Write each line in Roman letters with its meaning, and add ten useful words for flowers and festivals." },
  { id: "learning-465", title: "Tamil polite words for elders", category: "learning", text: "Teach me polite Tamil words and respectful forms to use with elders in Tamil Nadu, like respectful greetings, thank you, and please. Write each one in Roman letters with its meaning, explain when to use the respectful form, and give five practice sentences." },
  { id: "learning-466", title: "Tamil words for food and meals", category: "learning", text: "Teach me Tamil words for 20 foods and meals in Tamil Nadu, like rice, sambar, dosa, and curd. Write each word in Roman letters with its meaning, and give me a short talk in Tamil about what I ate today for [breakfast / lunch / dinner]." },
  { id: "learning-467", title: "Tamil sentences for a doctor visit", category: "learning", text: "Teach me Tamil sentences for a doctor visit in Tamil Nadu, like describing a fever, cough, or stomach pain, and asking about medicine timing. Write each sentence in Roman letters with its meaning, and add a short sample talk at a clinic." },
  { id: "learning-468", title: "Tamil greetings for Pongal and festivals", category: "learning", text: "Teach me Tamil greetings for Pongal and other Tamil festivals, including how to wish family and neighbours. Write each greeting in Roman letters with its meaning, and give me a short festival message in Tamil I can send on WhatsApp." },
  { id: "learning-469", title: "Tamil reading practice with a short story", category: "learning", text: "Write a short simple Tamil story of about 120 words in Roman letters about [a clever crow / a kind farmer], with an English meaning after each line. Then ask me five easy questions about the story so I can practise reading and retelling it aloud." },
  { id: "learning-470", title: "Tamil verbs for daily chores", category: "learning", text: "Teach me 15 common Tamil verbs for daily chores, like sweep, wash, cook, and clean. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Tamil about my morning chores." },
  { id: "learning-471", title: "Tamil words for colours and clothes", category: "learning", text: "Teach me Tamil words for ten colours and ten clothes, like red, green, saree, and veshti. Write each word in Roman letters with its meaning, give one example sentence for each colour, and add a short talk about what I am wearing today." },
  { id: "learning-472", title: "Tamil song lyrics for listening practice", category: "learning", text: "Pick a simple Tamil song about [nature / family] and explain three easy lines in simple English. Tell me the meaning of the hard words, how to pronounce each line slowly, and give me a short listening practice routine for [number] minutes a day." },
  { id: "learning-473", title: "Telugu numbers for market shopping", category: "learning", text: "Teach me Telugu numbers from 1 to 100 for market shopping in Andhra Pradesh and Telangana. Write each number in Roman letters with its meaning, show how to say prices like ₹[amount], and give me ten practice sentences for asking prices at a stall." },
  { id: "learning-474", title: "Telugu greetings for guests at home", category: "learning", text: "Teach me Telugu greetings for welcoming guests at home, like come in, please sit, and have some water. Write each greeting in Roman letters with its meaning, explain the polite forms simply, and add a short welcome dialogue with a guest." },
  { id: "learning-475", title: "Telugu sentences at a railway station", category: "learning", text: "Teach me Telugu sentences for a railway station in Andhra Pradesh or Telangana, like asking the platform number, the train timing, and the ticket price. Write each sentence in Roman letters with its meaning, and add a short dialogue with station staff." },
  { id: "learning-476", title: "Telugu words for food and tiffin", category: "learning", text: "Teach me Telugu words for 20 foods and tiffin items, like idli, dosa, rice, and pickle. Write each word in Roman letters with its meaning, and give me a short talk in Telugu about what I ate today for [breakfast / lunch / dinner]." },
  { id: "learning-477", title: "Telugu polite requests to elders", category: "learning", text: "Teach me polite Telugu requests to use with elders, like asking for blessings, asking for advice, and offering help. Write each sentence in Roman letters with its meaning, explain the respectful forms simply, and give me five practice sentences." },
  { id: "learning-478", title: "Telugu conversation with an auto driver", category: "learning", text: "Give me a simple Telugu conversation with an auto driver in Hyderabad or Vijayawada, asking to go to [place], asking the fare, and asking to wait. Write each line in Roman letters with its meaning, and add ten useful travel words." },
  { id: "learning-479", title: "Telugu words for family members", category: "learning", text: "Teach me Telugu words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Telugu." },
  { id: "learning-480", title: "Telugu reading practice with a short tale", category: "learning", text: "Write a short simple Telugu tale of about 120 words in Roman letters about [a wise old man / a helpful bird], with an English meaning after each line. Then ask me five easy questions about the tale so I can practise reading and retelling it aloud." },
  { id: "learning-481", title: "Telugu verbs for morning routines", category: "learning", text: "Teach me 15 common Telugu verbs for morning routines, like wake up, brush teeth, bathe, and eat. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Telugu about my morning." },
  { id: "learning-482", title: "Telugu festival wishes and greetings", category: "learning", text: "Teach me Telugu festival wishes for Ugadi, Sankranti, and Dasara, including how to wish family and friends. Write each wish in Roman letters with its meaning, and give me a short festival message in Telugu I can send on WhatsApp." },
  { id: "learning-483", title: "Kannada numbers for paying bills", category: "learning", text: "Teach me Kannada numbers from 1 to 100 for paying bills in Karnataka. Write each number in Roman letters with its meaning, show how to say amounts like ₹[amount], and give me ten practice sentences for paying at a shop or restaurant." },
  { id: "learning-484", title: "Kannada sentences at a bus stand", category: "learning", text: "Teach me Kannada sentences for a bus stand in Karnataka, like asking which bus goes to [place], asking the fare, and asking for a ticket. Write each sentence in Roman letters with its meaning, and add a short dialogue with a conductor." },
  { id: "learning-485", title: "Kannada words for food and snacks", category: "learning", text: "Teach me Kannada words for 20 foods and snacks in Karnataka, like rice, sambar, dosa, and biscuits. Write each word in Roman letters with its meaning, and give me a short talk in Kannada about what I ate today for [breakfast / lunch / dinner]." },
  { id: "learning-486", title: "Kannada greetings for neighbours", category: "learning", text: "Teach me Kannada greetings for meeting neighbours in Karnataka, like good morning, how are you, and see you later. Write each greeting in Roman letters with its meaning, explain when to use each one, and add a short neighbour dialogue to practise aloud." },
  { id: "learning-487", title: "Kannada polite requests in a shop", category: "learning", text: "Teach me polite Kannada requests for a shop in Karnataka, like asking for an item, asking the price, and asking for a bill. Write each sentence in Roman letters with its meaning, and add a short shop dialogue I can practise with a family member." },
  { id: "learning-488", title: "Kannada conversation with a taxi driver", category: "learning", text: "Give me a simple Kannada conversation with a taxi driver in Bengaluru, asking to go to [place], asking the fare, and asking to stop on the way. Write each line in Roman letters with its meaning, and add ten useful travel words." },
  { id: "learning-489", title: "Kannada words for family and festivals", category: "learning", text: "Teach me Kannada words for family members and festivals like Ugadi and Dasara, including mother, father, and sister. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short festival talk in Kannada." },
  { id: "learning-490", title: "Kannada reading practice with a short story", category: "learning", text: "Write a short simple Kannada story of about 120 words in Roman letters about [a clever fox / a kind farmer], with an English meaning after each line. Then ask me five easy questions about the story so I can practise reading and retelling it aloud." },
  { id: "learning-491", title: "Kannada verbs for daily work", category: "learning", text: "Teach me 15 common Kannada verbs for daily work, like write, read, cook, and go. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Kannada about my day at work or school." },
  { id: "learning-492", title: "Malayalam numbers for shopping", category: "learning", text: "Teach me Malayalam numbers from 1 to 100 for shopping in Kerala. Write each number in Roman letters with its meaning, show how to say prices like ₹[amount], and give me ten practice sentences for asking prices at a shop or market." },
  { id: "learning-493", title: "Malayalam greetings for Onam", category: "learning", text: "Teach me Malayalam greetings for Onam, including how to wish family and neighbours a happy Onam. Write each greeting in Roman letters with its meaning, explain the festival words simply, and give me a short Onam message I can send on WhatsApp." },
  { id: "learning-494", title: "Malayalam sentences at a tea shop", category: "learning", text: "Give me a simple Malayalam conversation for a tea shop in Kerala, ordering tea, asking for a snack, and paying the bill. Write each line in Roman letters with its meaning, and add ten useful words for tea, snacks, and payment." },
  { id: "learning-495", title: "Malayalam words for food and fish", category: "learning", text: "Teach me Malayalam words for 20 foods in Kerala, including rice, fish curry, appam, and banana. Write each word in Roman letters with its meaning, and give me a short talk in Malayalam about my favourite meal at home." },
  { id: "learning-496", title: "Malayalam polite words for elders", category: "learning", text: "Teach me polite Malayalam words and respectful forms to use with elders in Kerala, like respectful greetings, thank you, and please. Write each one in Roman letters with its meaning, explain when to use the respectful form, and give five practice sentences." },
  { id: "learning-497", title: "Malayalam conversation at a hospital", category: "learning", text: "Teach me Malayalam sentences for a hospital visit in Kerala, like describing a fever or pain, asking for a doctor, and asking about medicine timing. Write each sentence in Roman letters with its meaning, and add a short sample talk with a nurse." },
  { id: "learning-498", title: "Malayalam words for family members", category: "learning", text: "Teach me Malayalam words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Malayalam." },
  { id: "learning-499", title: "Malayalam reading practice with a short story", category: "learning", text: "Write a short simple Malayalam story of about 120 words in Roman letters about [a clever elephant / a kind fisherman], with an English meaning after each line. Then ask me five easy questions about the story so I can practise reading and retelling it aloud." },
  { id: "learning-500", title: "Malayalam verbs for home routines", category: "learning", text: "Teach me 15 common Malayalam verbs for home routines, like wake up, cook, wash, and clean. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Malayalam about my day at home." },
  { id: "learning-501", title: "Marathi numbers for market bargaining", category: "learning", text: "Teach me Marathi numbers from 1 to 100 for market bargaining in Maharashtra. Write each number in Roman letters with its meaning, show how to ask for a lower price politely, and give me ten practice sentences for buying vegetables at a market." },
  { id: "learning-502", title: "Marathi greetings for Ganpati festival", category: "learning", text: "Teach me Marathi greetings for Ganesh Chaturthi, including how to wish family and neighbours. Write each greeting in Roman letters with its meaning, explain the festival words simply, and give me a short Ganpati message I can send on WhatsApp." },
  { id: "learning-503", title: "Marathi sentences on a local train", category: "learning", text: "Teach me Marathi sentences for a local train in Mumbai or Pune, like asking if this train goes to [station], asking for a seat, and asking about the next stop. Write each sentence in Roman letters with its meaning, and add a short dialogue with a passenger." },
  { id: "learning-504", title: "Marathi words for food and snacks", category: "learning", text: "Teach me Marathi words for 20 foods and snacks in Maharashtra, like poha, vada pav, bhakri, and modak. Write each word in Roman letters with its meaning, and give me a short talk in Marathi about my favourite snack at home." },
  { id: "learning-505", title: "Marathi polite requests at a shop", category: "learning", text: "Teach me polite Marathi requests for a shop in Maharashtra, like asking for an item, asking the price, and asking for a bill. Write each sentence in Roman letters with its meaning, and add a short shop dialogue I can practise with a family member." },
  { id: "learning-506", title: "Marathi conversation with a neighbour", category: "learning", text: "Give me a simple Marathi conversation with a neighbour in Maharashtra, talking about the weather, the festival, and family. Write each line in Roman letters with its meaning, and add ten useful words for friendly daily talk." },
  { id: "learning-507", title: "Marathi words for family members", category: "learning", text: "Teach me Marathi words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Marathi." },
  { id: "learning-508", title: "Marathi reading practice with a short story", category: "learning", text: "Write a short simple Marathi story of about 120 words in Roman letters about [a clever monkey / a kind farmer], with an English meaning after each line. Then ask me five easy questions about the story so I can practise reading and retelling it aloud." },
  { id: "learning-509", title: "Marathi verbs for daily chores", category: "learning", text: "Teach me 15 common Marathi verbs for daily chores, like sweep, wash, cook, and clean. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Marathi about my morning chores." },
  { id: "learning-510", title: "Bengali numbers for shopping", category: "learning", text: "Teach me Bengali numbers from 1 to 100 for shopping in West Bengal. Write each number in Roman letters with its meaning, show how to say prices like ₹[amount], and give me ten practice sentences for asking prices at a shop or market." },
  { id: "learning-511", title: "Bengali greetings for Durga Puja", category: "learning", text: "Teach me Bengali greetings for Durga Puja, including how to wish family and friends. Write each greeting in Roman letters with its meaning, explain the festival words simply, and give me a short Puja message I can send on WhatsApp." },
  { id: "learning-512", title: "Bengali sentences at a fish market", category: "learning", text: "Teach me Bengali sentences for a fish market in Kolkata, like asking the price of fish, asking for fresh fish, and bargaining politely. Write each sentence in Roman letters with its meaning, and add a short dialogue with a fish seller." },
  { id: "learning-513", title: "Bengali words for food and sweets", category: "learning", text: "Teach me Bengali words for 20 foods and sweets in West Bengal, like rice, fish curry, rasgulla, and sandesh. Write each word in Roman letters with its meaning, and give me a short talk in Bengali about my favourite meal." },
  { id: "learning-514", title: "Bengali polite requests to elders", category: "learning", text: "Teach me polite Bengali requests to use with elders, like asking for blessings, asking for advice, and offering help. Write each sentence in Roman letters with its meaning, explain the respectful forms simply, and give me five practice sentences." },
  { id: "learning-515", title: "Bengali conversation on a bus", category: "learning", text: "Give me a simple Bengali conversation on a bus in Kolkata, asking which bus goes to [place], asking the fare, and asking for a ticket. Write each line in Roman letters with its meaning, and add ten useful travel words." },
  { id: "learning-516", title: "Bengali words for family members", category: "learning", text: "Teach me Bengali words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Bengali." },
  { id: "learning-517", title: "Bengali reading practice with a short story", category: "learning", text: "Write a short simple Bengali story of about 120 words in Roman letters about [a clever jackal / a kind teacher], with an English meaning after each line. Then ask me five easy questions about the story so I can practise reading and retelling it aloud." },
  { id: "learning-518", title: "Bengali verbs for daily routines", category: "learning", text: "Teach me 15 common Bengali verbs for daily routines, like wake up, eat, go, and sleep. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Bengali about my day." },
  { id: "learning-519", title: "Gujarati numbers for buying vegetables", category: "learning", text: "Teach me Gujarati numbers from 1 to 100 for buying vegetables in Gujarat. Write each number in Roman letters with its meaning, show how to say prices like ₹[amount], and give me ten practice sentences for asking prices at a vegetable stall." },
  { id: "learning-520", title: "Gujarati greetings for Navratri", category: "learning", text: "Teach me Gujarati greetings for Navratri, including how to wish family and friends. Write each greeting in Roman letters with its meaning, explain the festival words simply, and give me a short Navratri message I can send on WhatsApp." },
  { id: "learning-521", title: "Gujarati sentences at a grocery shop", category: "learning", text: "Teach me Gujarati sentences for a grocery shop in Gujarat, like asking for rice, dal, and oil, asking the price, and asking for a bill. Write each sentence in Roman letters with its meaning, and add a short shop dialogue." },
  { id: "learning-522", title: "Gujarati words for food and snacks", category: "learning", text: "Teach me Gujarati words for 20 foods and snacks in Gujarat, like dhokla, thepla, khakhra, and dal. Write each word in Roman letters with its meaning, and give me a short talk in Gujarati about my favourite snack." },
  { id: "learning-523", title: "Gujarati polite requests in a shop", category: "learning", text: "Teach me polite Gujarati requests for a shop in Gujarat, like asking for an item, asking the price, and asking for change. Write each sentence in Roman letters with its meaning, and add a short shop dialogue I can practise with a family member." },
  { id: "learning-524", title: "Gujarati conversation with a neighbour", category: "learning", text: "Give me a simple Gujarati conversation with a neighbour in Gujarat, talking about the weather, the festival, and family. Write each line in Roman letters with its meaning, and add ten useful words for friendly daily talk." },
  { id: "learning-525", title: "Gujarati words for family members", category: "learning", text: "Teach me Gujarati words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Gujarati." },
  { id: "learning-526", title: "Gujarati reading practice with a short story", category: "learning", text: "Write a short simple Gujarati story of about 120 words in Roman letters about [a clever sparrow / a kind shopkeeper], with an English meaning after each line. Then ask me five easy questions about the story so I can practise reading and retelling it aloud." },
  { id: "learning-527", title: "Gujarati verbs for daily work", category: "learning", text: "Teach me 15 common Gujarati verbs for daily work, like write, read, cook, and go. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Gujarati about my day at work or school." },
  { id: "learning-528", title: "Punjabi numbers for shopping", category: "learning", text: "Teach me Punjabi numbers from 1 to 100 for shopping in Punjab. Write each number in Roman letters with its meaning, show how to say prices like ₹[amount], and give me ten practice sentences for asking prices at a shop or market." },
  { id: "learning-529", title: "Punjabi greetings for Vaisakhi", category: "learning", text: "Teach me Punjabi greetings for Vaisakhi, including how to wish family and friends. Write each greeting in Roman letters with its meaning, explain the festival words simply, and give me a short Vaisakhi message I can send on WhatsApp." },
  { id: "learning-530", title: "Punjabi sentences at a dhaba", category: "learning", text: "Give me a simple Punjabi conversation at a dhaba in Punjab, ordering roti and dal, asking for water, and paying the bill. Write each line in Roman letters with its meaning, and add ten useful words for food and payment." },
  { id: "learning-531", title: "Punjabi words for food and rotis", category: "learning", text: "Teach me Punjabi words for 20 foods in Punjab, like roti, dal, sarson da saag, and lassi. Write each word in Roman letters with its meaning, and give me a short talk in Punjabi about my favourite meal at home." },
  { id: "learning-532", title: "Punjabi polite words for elders", category: "learning", text: "Teach me polite Punjabi words and respectful forms to use with elders in Punjab, like respectful greetings, thank you, and please. Write each one in Roman letters with its meaning, explain when to use the respectful form, and give five practice sentences." },
  { id: "learning-533", title: "Punjabi conversation with a shopkeeper", category: "learning", text: "Give me a simple Punjabi conversation with a shopkeeper in Punjab, asking for an item, asking the price, and asking for a bill. Write each line in Roman letters with its meaning, and add ten useful words for shopping." },
  { id: "learning-534", title: "Punjabi words for family members", category: "learning", text: "Teach me Punjabi words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Punjabi." },
  { id: "learning-535", title: "Punjabi reading practice with a short story", category: "learning", text: "Write a short simple Punjabi story of about 120 words in Roman letters about [a clever farmer / a kind friend], with an English meaning after each line. Then ask me five easy questions about the story so I can practise reading and retelling it aloud." },
  { id: "learning-536", title: "Punjabi verbs for daily routines", category: "learning", text: "Teach me 15 common Punjabi verbs for daily routines, like wake up, eat, go, and sleep. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Punjabi about my day." },
  { id: "learning-537", title: "Urdu numbers for market shopping", category: "learning", text: "Teach me Urdu numbers from 1 to 100 for market shopping in India. Write each number in Roman letters with its meaning, show how to say prices like ₹[amount], and give me ten practice sentences for asking prices at a market stall." },
  { id: "learning-538", title: "Urdu greetings for Eid", category: "learning", text: "Teach me Urdu greetings for Eid, including how to wish family and friends. Write each greeting in Roman letters with its meaning, explain the festival words simply, and give me a short Eid message I can send on WhatsApp." },
  { id: "learning-539", title: "Urdu sentences at a tea stall", category: "learning", text: "Give me a simple Urdu conversation at a tea stall in India, ordering chai, asking for a snack, and paying the bill. Write each line in Roman letters with its meaning, and add ten useful words for tea, snacks, and payment." },
  { id: "learning-540", title: "Urdu words for food and hospitality", category: "learning", text: "Teach me Urdu words for 20 foods and hospitality words in India, like biryani, kebab, guest, and welcome. Write each word in Roman letters with its meaning, and give me a short talk in Urdu about welcoming a guest for dinner." },
  { id: "learning-541", title: "Urdu polite requests to guests", category: "learning", text: "Teach me polite Urdu requests to use with guests at home, like please sit, have some tea, and stay for dinner. Write each sentence in Roman letters with its meaning, explain the polite forms simply, and give me five practice sentences." },
  { id: "learning-542", title: "Urdu conversation with a neighbour", category: "learning", text: "Give me a simple Urdu conversation with a neighbour in India, talking about the weather, the festival, and family. Write each line in Roman letters with its meaning, and add ten useful words for friendly daily talk." },
  { id: "learning-543", title: "Urdu words for family members", category: "learning", text: "Teach me Urdu words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Urdu." },
  { id: "learning-544", title: "Urdu reading practice with a short story", category: "learning", text: "Write a short simple Urdu story of about 120 words in Roman letters about [a kind old man / a honest shopkeeper], with an English meaning after each line. Then ask me five easy questions about the story so I can practise reading and retelling it aloud." },
  { id: "learning-545", title: "Urdu verbs for daily routines", category: "learning", text: "Teach me 15 common Urdu verbs for daily routines, like wake up, eat, go, and sleep. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Urdu about my day." },
  { id: "learning-546", title: "Sanskrit numbers for counting", category: "learning", text: "Teach me Sanskrit numbers from 1 to 20 for counting, with each number in Roman letters and its meaning. Show how to count simple things like flowers and books, and give me ten practice sentences using the numbers with everyday objects at home." },
  { id: "learning-547", title: "Sanskrit greetings and blessings", category: "learning", text: "Teach me simple Sanskrit greetings and blessings used in India, like namaste and blessings for a new day. Write each one in Roman letters with its meaning, explain when to use each greeting, and give me five short sentences I can practise every morning." },
  { id: "learning-548", title: "Sanskrit words for nature and seasons", category: "learning", text: "Teach me Sanskrit words for 20 nature and season words, like sun, moon, rain, summer, and monsoon. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk about today’s weather in Sanskrit." },
  { id: "learning-549", title: "Sanskrit words for family members", category: "learning", text: "Teach me Sanskrit words for family members like mother, father, elder brother, younger sister, and grandmother. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short talk introducing my family in Sanskrit." },
  { id: "learning-550", title: "Sanskrit simple sentences for daily life", category: "learning", text: "Teach me 15 simple Sanskrit sentences for daily life in India, like I wake up early, I drink water, and I go to school. Write each sentence in Roman letters with its meaning, and make a short paragraph in Sanskrit about my day." },
  { id: "learning-551", title: "Sanskrit verbs for morning routines", category: "learning", text: "Teach me 15 common Sanskrit verbs for morning routines, like wake up, wash, pray, and eat. Write each verb in Roman letters with its meaning, give one example sentence for each, and make a short paragraph in Sanskrit about my morning." },
  { id: "learning-552", title: "Sanskrit names of fruits and vegetables", category: "learning", text: "Teach me Sanskrit names of 20 fruits and vegetables used in India, like mango, banana, potato, and tomato. Write each name in Roman letters with its meaning, and give me a short market list in Sanskrit I can practise reading aloud." },
  { id: "learning-553", title: "Sanskrit words for body parts", category: "learning", text: "Teach me Sanskrit words for 15 body parts, like eye, ear, hand, and foot. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short fun game where I point to a body part and say its Sanskrit name." },
  { id: "learning-554", title: "Sanskrit shloka for morning prayer", category: "learning", text: "Give me a short simple Sanskrit shloka for morning prayer, written in Roman letters with a word-by-word meaning in simple English. Explain its message in everyday language, show how to pronounce each line slowly, and give one example of how to apply it daily." },
  { id: "learning-555", title: "Sanskrit words for animals and birds", category: "learning", text: "Teach me Sanskrit words for 20 animals and birds in India, like dog, cat, elephant, peacock, and sparrow. Write each word in Roman letters with its meaning, give one example sentence for each, and add a short animal quiz with five questions." },
  { id: "learning-556", title: "Translate a shopping list into Hindi", category: "learning", text: "Translate my shopping list of [list items] from English into Hindi, writing each item in Roman letters with its meaning. Explain any hard word simply, and give me five practice sentences using the translated words at a shop in India." },
  { id: "learning-557", title: "Translate a school notice into Tamil", category: "learning", text: "Translate this school notice from English into simple Tamil: [paste the notice]. Write the translation in Roman letters with an English meaning after each line, explain any hard word simply, and keep the tone polite and clear for parents." },
  { id: "learning-558", title: "Translate a train announcement into Telugu", category: "learning", text: "Translate this train announcement from English into simple Telugu: [paste the announcement]. Write the translation in Roman letters with an English meaning after each line, and explain the words for platform, arrival, and delay in simple English." },
  { id: "learning-559", title: "Translate a recipe into Kannada", category: "learning", text: "Translate this simple recipe for [dish] from English into Kannada, writing each step in Roman letters with its meaning. Explain the cooking words simply, and give me a short list of the Kannada words for the ingredients used in the recipe." },
  { id: "learning-560", title: "Translate a birthday wish into Malayalam", category: "learning", text: "Translate this birthday wish from English into simple Malayalam: [paste the wish]. Write the translation in Roman letters with its meaning, explain any hard word simply, and give me two more short birthday wishes in Malayalam I can send on WhatsApp." },
  { id: "learning-561", title: "Translate a wedding invitation into Marathi", category: "learning", text: "Translate this short wedding invitation from English into simple Marathi: [paste the invitation]. Write the translation in Roman letters with an English meaning after each line, keep the tone warm and respectful, and explain the words for venue, date, and family." },
  { id: "learning-562", title: "Translate a shop board into Bengali", category: "learning", text: "Translate this shop board text from English into simple Bengali: [paste the board text]. Write the translation in Roman letters with its meaning, explain any hard word simply, and give me five more common shop board phrases in Bengali with meanings." },
  { id: "learning-563", title: "Translate a festival greeting into Gujarati", category: "learning", text: "Translate this festival greeting from English into simple Gujarati: [paste the greeting]. Write the translation in Roman letters with its meaning, explain the festival words simply, and give me two more short festival greetings in Gujarati for [festival]." },
  { id: "learning-564", title: "Compare greetings in five Indian languages", category: "learning", text: "Compare how to say hello, thank you, and goodbye in five Indian languages: [choose five from Hindi, Tamil, Telugu, Kannada, Malayalam, Marathi, Bengali, Gujarati, Punjabi, Urdu]. Write each greeting in Roman letters with its meaning, and note one polite difference between the languages." },
  { id: "learning-565", title: "Learn two languages together in 30 days", category: "learning", text: "Make a 30-day plan to learn two Indian languages together, [language 1] and [language 2], for [number] minutes a day. Give me a weekly word list, one shared sentence pattern per week, and a simple daily practice routine that keeps the two languages separate and clear." },
  { id: "learning-566", title: "Class 10 board maths 60-day plan", category: "learning", text: "I am in Class 10 and my board maths exam is 60 days away. Make a day-by-day plan that covers [list your weak chapters] first, with daily practice of [number] sums, a sample paper every Sunday, and two full revision rounds before the exam day." },
  { id: "learning-567", title: "Class 10 science diagrams practice", category: "learning", text: "Help me practise the important labelled diagrams for Class 10 science, like [a diagram, e.g. the human heart / a flower]. Give me a daily routine to draw each one from memory, label it correctly, and check my mistakes in under 20 minutes a day." },
  { id: "learning-568", title: "Class 10 social science map work practice", category: "learning", text: "Make a map practice plan for Class 10 social science board exams. List the [number] most important places to mark on India maps, give me a weekly drill to locate them from memory, and a quick self-test I can do in 10 minutes." },
  { id: "learning-569", title: "Class 10 board format questions practice", category: "learning", text: "Help me practise the short format questions in Class 10 board exams, like notices, letters and analytical paragraphs in English. Give me [number] practice questions, a simple format to follow for each type, and a checklist to score my own answers." },
  { id: "learning-570", title: "Class 10 Hindi paper writing practice", category: "learning", text: "Make a practice plan for the Class 10 Hindi board paper. Include daily writing of [number] short answers, one letter and one essay each week, common grammar mistakes to avoid, and a way to improve my speed without losing neatness." },
  { id: "learning-571", title: "Class 10 board sample paper review method", category: "learning", text: "Show me how to review a Class 10 board sample paper after I finish it. Tell me how to mark it honestly, sort my mistakes into silly errors, weak concepts and time problems, and turn each mistake into one revision task for the next day." },
  { id: "learning-572", title: "Class 10 last-week board revision checklist", category: "learning", text: "Make a last-week checklist for a Class 10 board exam student with [list your subjects]. For each day, say what to revise, what to skip, how many hours to study, and what to pack and check the night before each paper." },
  { id: "learning-573", title: "Class 10 practical file and internal assessment prep", category: "learning", text: "Help me finish my Class 10 practical files and internal assessment work before the board exams. Give me a week-by-week plan to complete [subject] experiments, write neat records, and prepare short answers for the viva questions teachers usually ask." },
  { id: "learning-574", title: "Class 10 board exam day checklist", category: "learning", text: "Make a simple exam-day checklist for a Class 10 board student. Cover what to carry, what time to leave home, what to do in the first 15 minutes in the hall, and what to avoid doing between two papers on the same day." },
  { id: "learning-575", title: "Class 10 supplementary exam comeback plan", category: "learning", text: "I could not clear [subject] in my Class 10 board exam and have to appear for the supplementary exam. Make a realistic [number]-week comeback plan that rebuilds only the weak chapters, with daily practice, weekly tests and a simple way to track my progress." },
  { id: "learning-576", title: "Class 12 physics numericals practice plan", category: "learning", text: "Make a 4-week practice plan for Class 12 physics numericals in [chapter, e.g. current electricity]. Give me [number] problems a day from easy to hard, the formulae to revise first, and a method to find and fix the step where I keep going wrong." },
  { id: "learning-577", title: "Class 12 chemistry named reactions revision", category: "learning", text: "Help me revise the important named reactions for Class 12 chemistry, like [reaction name]. Make a one-page style list with the reaction, the reagents, one example and one common exam question for each, plus a daily 15-minute recall drill." },
  { id: "learning-578", title: "Class 12 biology diagrams labelling drill", category: "learning", text: "Give me a labelling drill for Class 12 biology diagrams, like [diagram, e.g. the human brain / DNA structure]. Tell me how to draw it from memory in [number] minutes, label every part correctly, and test myself again after two days without looking." },
  { id: "learning-579", title: "Class 12 accountancy formats practice", category: "learning", text: "Help me master the formats for Class 12 accountancy, like [format, e.g. partnership deed / balance sheet]. Give me [number] practice questions, the step-by-step format for each, and the small calculation mistakes students make most often in board exams." },
  { id: "learning-580", title: "Class 12 business studies case study practice", category: "learning", text: "Make a practice set for Class 12 business studies case studies. Give me [number] short case passages based on [topic, e.g. planning / marketing], the questions to answer for each, and a simple structure for writing answers that score full marks." },
  { id: "learning-581", title: "Class 12 economics graphs and data questions", category: "learning", text: "Teach me to answer Class 12 economics graph and data questions confidently. Use [topic, e.g. demand and supply / national income] as the example, explain how to read the graph, what to write, and give me [number] practice questions with answers." },
  { id: "learning-582", title: "Class 12 maths calculus practice set", category: "learning", text: "Create a 3-week calculus practice set for Class 12 maths covering [differentiation / integration / application of derivatives]. Give me [number] questions a day, ordered easy to hard, with the key formulae listed first and a weekly test to check my speed." },
  { id: "learning-583", title: "Class 12 English unseen passage practice", category: "learning", text: "Give me a daily unseen passage practice plan for Class 12 English board exams. Include one passage a day, [number] questions of different types, a timer to finish in [number] minutes, and tips to find answers quickly without re-reading the whole passage." },
  { id: "learning-584", title: "Class 12 board last 15 days plan", category: "learning", text: "I have 15 days left before my Class 12 board exams and [list your subjects]. Make a day-by-day plan that revises every subject twice, keeps one mock paper per subject, and leaves the last day only for light revision and rest." },
  { id: "learning-585", title: "Class 12 improvement exam preparation plan", category: "learning", text: "I want to improve my marks in [subject] through the Class 12 improvement exam. Make a [number]-month plan that focuses only on the chapters where I lost marks, with weekly practice papers and a clear target score to aim for in each paper." },
  { id: "learning-586", title: "CUET domain subject choice plan", category: "learning", text: "Help me choose my CUET domain subjects after Class 12. I studied [stream, e.g. science / commerce / humanities] and want to apply for [course]. Compare my options, show which subjects match my strengths, and give me a simple decision checklist." },
  { id: "learning-587", title: "CUET general test practice routine", category: "learning", text: "Make a daily practice routine for the CUET general test covering quantitative aptitude, logical reasoning and general knowledge. Give me [number] questions a day, a weekly mock test, and a simple tracker to see which of the three areas needs the most work." },
  { id: "learning-588", title: "CUET English language section practice", category: "learning", text: "Help me prepare for the CUET English language section. Give me a weekly plan with reading comprehension passages, vocabulary from [source, e.g. my NCERT books], grammar drills, and [number] practice questions a day with answers explained simply." },
  { id: "learning-589", title: "CUET mock test score analysis method", category: "learning", text: "Show me how to analyse my CUET mock test scores properly. Tell me how to record marks per section, find the topics where I lose the most marks, and turn the analysis into a revision list for the next [number] days before the next mock." },
  { id: "learning-590", title: "CUET question pattern study from old papers", category: "learning", text: "Help me study the CUET question pattern using old question papers. Tell me how to collect [number] papers, count how many questions come from each topic, and use that count to decide how much time to give each topic in my revision." },
  { id: "learning-591", title: "CUET mock day simulation at home", category: "learning", text: "Plan a full CUET mock day at home for me. Set the timetable for [number] sections, breaks between them, and the exact exam-day rules to follow, so I practise sitting, timing and focus exactly like the real test day." },
  { id: "learning-592", title: "CUET revision plan using Class 12 syllabus", category: "learning", text: "Make a CUET revision plan that uses my Class 12 syllabus for [domain subject]. Show me which Class 12 chapters matter most, what extra topics to add, and a weekly schedule that revises one chapter a day with [number] practice questions." },
  { id: "learning-593", title: "CUET negative marking attempt strategy", category: "learning", text: "Teach me a smart attempt strategy for CUET papers with negative marking. Explain when to attempt, when to skip, and when to guess, using my last mock score of [score] as the example, and give me a rule I can follow in the exam hall." },
  { id: "learning-594", title: "CUET college and course shortlist after mocks", category: "learning", text: "Help me shortlist CUET colleges and courses after my mock tests. I scored about [score] in [subject] and want [course]. Suggest how to make a list of [number] safe, likely and dream options, and what to check about each college before applying." },
  { id: "learning-595", title: "CUET last-month study timetable", category: "learning", text: "Make a last-month CUET timetable for me with [number] hours a day. Cover [list your subjects], give Sundays to full mock tests, keep one hour daily for current affairs and English, and leave the final three days for revision only." },
  { id: "learning-596", title: "CLAT English comprehension passage practice", category: "learning", text: "Give me a CLAT English comprehension practice plan with one long passage a day from [source, e.g. editorials / magazines]. Include [number] questions per passage, a timer, and tips to find the main idea fast without reading every line twice." },
  { id: "learning-597", title: "CLAT current affairs notes system", category: "learning", text: "Help me build a CLAT current affairs notes system. Tell me what to note daily from [source, e.g. a newspaper], how to organise it by topic, and how to revise the last [number] months of notes in the final two weeks before the exam." },
  { id: "learning-598", title: "CLAT legal reasoning passage practice", category: "learning", text: "Make a legal reasoning practice set for CLAT with [number] passages based on [topic, e.g. contracts / torts]. For each passage, give a principle, facts and questions, and explain simply why the correct answer follows from the principle." },
  { id: "learning-599", title: "CLAT logical reasoning puzzle drills", category: "learning", text: "Give me a daily logical reasoning drill for CLAT with puzzles like [type, e.g. blood relations / seating / syllogisms]. Include [number] questions a day, the fastest method to solve each type, and a weekly test to measure my speed and accuracy." },
  { id: "learning-600", title: "CLAT quantitative techniques shortcuts", category: "learning", text: "Teach me quick quantitative techniques for CLAT, like percentages, ratios and averages, using simple examples. Give me [number] shortcut methods, [number] practice questions for each, and a way to practise them in under 20 minutes a day." },
  { id: "learning-601", title: "CLAT mock test review method", category: "learning", text: "Show me how to review a CLAT mock test the same day I take it. Tell me how to sort mistakes into reading errors, concept gaps and time pressure, and how to convert each mistake into one small task for my next study session." },
  { id: "learning-602", title: "CLAT reading speed for long passages", category: "learning", text: "Help me read faster for CLAT's long passages without losing understanding. Give me a 3-week plan with daily timed reading of [number] words, a method to note key points as I read, and a weekly test to check my speed and accuracy." },
  { id: "learning-603", title: "CLAT principle-fact question practice", category: "learning", text: "Create a practice set of CLAT principle-fact questions on [topic, e.g. law of torts]. Give me [number] questions where I apply one principle to new facts, explain each answer in simple words, and point out the trap most students fall into." },
  { id: "learning-604", title: "CLAT last-90-days study plan", category: "learning", text: "Make a 90-day CLAT study plan for me with [number] hours a day. Cover English, current affairs, legal reasoning, logical reasoning and maths week by week, with a mock test every Sunday and a full revision fortnight at the end." },
  { id: "learning-605", title: "CLAT answer elimination techniques", category: "learning", text: "Teach me how to eliminate wrong options in CLAT multiple-choice questions. Use [section, e.g. legal reasoning] as the example, show [number] elimination tricks, and give me [number] practice questions to try the tricks on." },
  { id: "learning-606", title: "CA Foundation accounts journal entries practice", category: "learning", text: "Help me practise journal entries for CA Foundation accounting. Give me [number] transactions a day based on [topic, e.g. partnership / company accounts], the correct entry for each, and the common debit-credit mistakes to watch out for." },
  { id: "learning-607", title: "CA Foundation business law case questions", category: "learning", text: "Make a business law case-question practice set for CA Foundation on [topic, e.g. the Indian Contract Act]. Give me [number] short cases, the legal rule for each, and a simple answer structure that covers facts, law and conclusion." },
  { id: "learning-608", title: "CA Foundation maths and statistics formula sheet", category: "learning", text: "Help me build a CA Foundation maths and statistics formula sheet for [topic, e.g. time value of money / probability]. List each formula in simple words, one example sum for each, and a daily 10-minute drill to recall them without looking." },
  { id: "learning-609", title: "CA Foundation economics diagrams revision", category: "learning", text: "Give me a revision plan for CA Foundation economics diagrams, like [diagram, e.g. demand and supply curves]. Tell me how to draw each one neatly, label it correctly, and explain it in two lines, with a weekly self-test." },
  { id: "learning-610", title: "CA Foundation MCQ practice method", category: "learning", text: "Show me a smart MCQ practice method for CA Foundation. Tell me how many questions to attempt daily from [subject], how to review wrong answers the same day, and how to use elimination when I am unsure between two options." },
  { id: "learning-611", title: "CA Foundation mock test under exam timing", category: "learning", text: "Plan a CA Foundation mock test under real exam timing for [subject]. Set the paper length, breaks, and rules to follow, and tell me how to score it, find my weak areas, and plan the next [number] days of study from the result." },
  { id: "learning-612", title: "CA Foundation four-subject revision in 45 days", category: "learning", text: "Make a 45-day revision plan for all four CA Foundation subjects: accounts, law, maths and economics. Give each subject a fixed daily slot, rotate weak topics first, and include [number] mock tests spread across the six weeks." },
  { id: "learning-613", title: "CA Foundation theory answer writing practice", category: "learning", text: "Teach me to write good theory answers for CA Foundation law and economics. Give me a structure for [number]-mark answers, [number] practice questions, and tips to add headings, examples and key terms that examiners look for." },
  { id: "learning-614", title: "CA Foundation mental maths shortcuts", category: "learning", text: "Teach me mental maths shortcuts for CA Foundation, like quick percentages, ratios and compound interest estimates. Give me [number] tricks with examples, a daily 10-minute drill, and [number] practice sums to test my speed each week." },
  { id: "learning-615", title: "CA Foundation first-attempt routine for Class 12 students", category: "learning", text: "Make a first-attempt CA Foundation study routine for a Class 12 student who also has board exams. Show me how to balance both for [number] months, which CA topics overlap with Class 12, and when to switch fully to CA Foundation after the boards." },
  { id: "learning-616", title: "NDA maths practice plan", category: "learning", text: "Make a 6-week NDA maths practice plan covering [topics, e.g. algebra, trigonometry and calculus basics]. Give me [number] questions a day from easy to hard, the formulae to revise first, and a weekly test to track my score." },
  { id: "learning-617", title: "NDA general ability test English and GK plan", category: "learning", text: "Help me prepare for the NDA general ability test in English and general knowledge. Give me a weekly plan with [number] English questions a day, daily GK notes from [source], and a Sunday revision test covering both parts." },
  { id: "learning-618", title: "NDA SSB interview preparation after written exam", category: "learning", text: "Help me prepare for the NDA SSB interview after clearing the written exam. Explain the five-day process simply, give me a daily practice plan for group tasks, picture perception and personal interview questions, and tips to stay confident and honest." },
  { id: "learning-619", title: "CDS English paper practice plan", category: "learning", text: "Make a CDS English paper practice plan with daily work on comprehension, synonyms, antonyms and spotting errors. Give me [number] questions a day, a weekly mock paper, and a method to learn [number] new words every week from my mistakes." },
  { id: "learning-620", title: "CDS general knowledge current affairs notes", category: "learning", text: "Help me build CDS general knowledge notes with a daily 20-minute current affairs habit. Tell me what to note from [source, e.g. a newspaper], how to organise it by defence, polity and economy, and how to revise it every Sunday." },
  { id: "learning-621", title: "CDS maths shortcuts practice", category: "learning", text: "Teach me fast maths shortcuts for the CDS exam, like quick squares, percentages and time-speed-distance tricks. Give me [number] methods with examples, a daily drill of [number] questions, and a weekly speed test to measure improvement." },
  { id: "learning-622", title: "NDA fitness routine alongside study", category: "learning", text: "Make a simple daily fitness routine for an NDA aspirant who studies [number] hours a day. Include running, push-ups and sit-ups I can do at home or in a park, a weekly target, and how to increase it slowly without getting injured or tired for study." },
  { id: "learning-623", title: "NDA topic weightage from old question papers", category: "learning", text: "Help me find which topics carry the most marks in the NDA exam using old question papers. Tell me how to count questions topic-wise from [number] papers, and how to use that list to plan the next [number] weeks of study." },
  { id: "learning-624", title: "CDS paper choice plan for IMA OTA and Navy", category: "learning", text: "Help me plan my CDS preparation based on whether I want IMA, OTA or the Navy. Compare the papers each option needs, show me which subjects to focus on, and give me a weekly timetable for [your choice] with [number] study hours a day." },
  { id: "learning-625", title: "NDA and CDS daily current affairs habit", category: "learning", text: "Build a 20-minute daily current affairs habit for NDA and CDS preparation. Tell me what to read, what to note in one line per news item, and how to turn the week's notes into a quick Sunday quiz of [number] questions." },
  { id: "learning-626", title: "SSC CGL tier-wise study plan", category: "learning", text: "Make a tier-wise SSC CGL study plan for me, starting with Tier 1 and moving to Tier 2. Show what to study for each tier, how many weeks to give each subject, and when to switch from learning new topics to mock tests only." },
  { id: "learning-627", title: "SSC CHSL typing and skill test preparation", category: "learning", text: "Help me prepare for the SSC CHSL typing and skill test along with the written exam. Give me a daily typing practice plan of [number] minutes, the speed target to aim for, and tips to reduce errors while typing fast." },
  { id: "learning-628", title: "SSC maths arithmetic shortcuts", category: "learning", text: "Teach me SSC arithmetic shortcuts for topics like percentages, profit and loss and averages. Give me [number] tricks with simple examples, [number] practice questions for each, and a daily 15-minute speed drill to build confidence." },
  { id: "learning-629", title: "SSC reasoning puzzle practice routine", category: "learning", text: "Give me a daily SSC reasoning practice routine with puzzles like series, coding, seating and blood relations. Include [number] questions a day, the fastest method for each type, and a weekly test to check speed and accuracy together." },
  { id: "learning-630", title: "SSC English error spotting practice", category: "learning", text: "Help me practise spotting errors in English for SSC exams. Give me [number] sentences a day with one error each, explain the grammar rule behind every answer simply, and list the [number] error types that appear most often." },
  { id: "learning-631", title: "SSC general knowledge static notes", category: "learning", text: "Help me make static GK notes for SSC exams covering history, polity, geography and science. Tell me what to note for each topic, how to keep each note under one page, and a weekly revision cycle so I remember them for months." },
  { id: "learning-632", title: "SSC mock test analysis sheet", category: "learning", text: "Make a simple SSC mock test analysis sheet for me. Tell me what to record after each mock — marks per section, time taken, silly mistakes and skipped questions — and how to use the sheet to pick the next [number] topics to revise." },
  { id: "learning-633", title: "SSC last-30-days revision plan", category: "learning", text: "Make a last-30-days SSC revision plan with [number] hours a day. Cover maths, reasoning, English and GK in rotation, give Sundays to full mock tests, and leave the last three days for formulae, notes and light practice only." },
  { id: "learning-634", title: "SSC MTS and GD exam preparation plan", category: "learning", text: "Make a preparation plan for the SSC MTS and GD exams with [number] hours a day. Cover maths, reasoning, English and GK at the basic level, add a daily current affairs habit, and include [number] mock tests in the final month." },
  { id: "learning-635", title: "SSC question attempt order strategy", category: "learning", text: "Teach me a smart question attempt order for SSC exams. Using my last mock score of [score], show me which section to start with, when to skip a hard question, and how to use the last [number] minutes for review instead of guessing." },
  { id: "learning-636", title: "Banking prelims speed maths plan", category: "learning", text: "Make a banking prelims speed maths plan for me. Give me daily drills in simplification, number series and arithmetic, a target time per question, and a weekly test to check how many questions I finish correctly in [number] minutes." },
  { id: "learning-637", title: "Banking mains data interpretation sets", category: "learning", text: "Give me a banking mains data interpretation practice plan with [number] sets a week on tables, bar graphs and caselets. For each set, explain the fastest way to read the data, which questions to attempt first, and the calculation shortcuts to use." },
  { id: "learning-638", title: "Banking reasoning puzzles seating arrangement", category: "learning", text: "Help me master seating arrangement puzzles for banking exams. Give me a step-by-step method, [number] puzzles a week from easy to hard, and tips to solve them in under [number] minutes without redrawing the diagram again and again." },
  { id: "learning-639", title: "Banking English reading comprehension practice", category: "learning", text: "Make a banking English reading comprehension plan with one passage a day from [source, e.g. editorials]. Include [number] questions per passage, a timer of [number] minutes, and tips to answer inference questions without re-reading everything." },
  { id: "learning-640", title: "Banking general awareness notes", category: "learning", text: "Help me build banking general awareness notes for [exam, e.g. IBPS PO / SBI Clerk]. Tell me what to note daily on banking, economy and current affairs, how to organise it, and how to revise the last [number] months before the exam." },
  { id: "learning-641", title: "Banking descriptive English letter and essay practice", category: "learning", text: "Give me a descriptive English practice plan for banking mains with one letter and one essay a week. Provide [number] topics based on [theme, e.g. banking and economy], a simple structure for each, and a checklist to score my own writing." },
  { id: "learning-642", title: "Banking interview preparation after mains", category: "learning", text: "Help me prepare for a banking interview after clearing the mains exam. Give me [number] common questions with simple answer outlines, a daily practice plan for speaking clearly, and tips on banking awareness and personal questions about my background." },
  { id: "learning-643", title: "Banking mock test sectional timing plan", category: "learning", text: "Make a sectional timing plan for banking mock tests. Tell me how many minutes to give each section in prelims and mains, when to move on from a tough section, and how to practise the plan with [number] mocks before the real exam." },
  { id: "learning-644", title: "IBPS Clerk versus PO preparation difference plan", category: "learning", text: "Help me plan my preparation based on whether I target IBPS Clerk or IBPS PO. Compare the exam pattern, difficulty and speed each needs, show me what to change in my daily routine for [your choice], and give me a weekly timetable." },
  { id: "learning-645", title: "Banking exam routine for working aspirants", category: "learning", text: "Make a banking exam routine for someone working [number] hours a day. Give me a morning and evening study plan, weekend mock tests, and a way to cover maths, reasoning, English and GK in just [number] hours on weekdays." },
  { id: "learning-646", title: "Railway NTPC maths and reasoning plan", category: "learning", text: "Make a Railway NTPC preparation plan with [number] hours a day. Cover maths, reasoning and general awareness in rotation, give me [number] practice questions a day, and a weekly mock test to track my progress." },
  { id: "learning-647", title: "Railway Group D science and GK plan", category: "learning", text: "Help me prepare for the Railway Group D exam with a daily plan for general science and GK. Give me [number] science questions a day from physics, chemistry and biology basics, plus a daily current affairs note habit of 15 minutes." },
  { id: "learning-648", title: "Railway ALP technical and aptitude preparation", category: "learning", text: "Make a Railway ALP preparation plan covering technical subjects, maths and reasoning. Show me how to split [number] hours a day between technical topics and aptitude, and include [number] mock tests in the final month." },
  { id: "learning-649", title: "Railway exam current affairs notes method", category: "learning", text: "Help me keep current affairs notes for railway exams. Tell me what to note daily from [source], how to organise it by month, and how to revise the last [number] months of notes in a single week before the exam." },
  { id: "learning-650", title: "Railway mock test review routine", category: "learning", text: "Show me how to review a railway exam mock test properly. Tell me how to record section-wise marks and time, find the topics where I lose marks, and turn the review into a revision list for the next [number] days." },
  { id: "learning-651", title: "Railway exam last-month plan", category: "learning", text: "Make a last-month plan for my railway exam with [number] hours a day. Cover all subjects in rotation, give Sundays to full mock tests, and keep the final week only for formulae, short notes and light practice." },
  { id: "learning-652", title: "Railway RPF constable written and physical balance", category: "learning", text: "Help me balance RPF constable written exam study with physical test preparation. Give me a daily plan with [number] hours of study and [number] minutes of running and exercise, plus weekly targets for both the written score and fitness." },
  { id: "learning-653", title: "Railway exam study plan using free mock tests", category: "learning", text: "Make a railway exam study plan that uses free mock tests wisely. Tell me how many mocks to take each week, how to pick good ones, how to review each mock the same day, and what to study between mocks so my score keeps rising." },
  { id: "learning-654", title: "CTET child development pedagogy notes", category: "learning", text: "Help me make CTET child development and pedagogy notes in simple words. Cover [topic, e.g. learning theories / child development stages], give one classroom example for each idea, and a daily 20-minute revision drill with [number] practice questions." },
  { id: "learning-655", title: "CTET maths pedagogy practice", category: "learning", text: "Give me a CTET maths pedagogy practice plan with [number] questions a day on teaching methods, common errors children make, and how to explain [topic, e.g. fractions] simply. Include answers with short explanations for each question." },
  { id: "learning-656", title: "CTET language paper practice", category: "learning", text: "Make a CTET language paper practice plan for [Hindi / English]. Include daily unseen passages, grammar questions and pedagogy questions, with [number] questions a day and a weekly test to check my score in each part." },
  { id: "learning-657", title: "CTET environmental studies notes", category: "learning", text: "Help me prepare CTET environmental studies notes covering [topic, e.g. family, food, water and travel]. Give me one-page notes per topic, [number] practice questions each, and a weekly revision plan that repeats every topic twice before the exam." },
  { id: "learning-658", title: "State TET versus CTET preparation plan", category: "learning", text: "Help me plan my preparation based on whether I target my state TET or CTET. Compare the syllabus, language papers and difficulty of each, show me what to study differently for [your choice], and give me a weekly timetable." },
  { id: "learning-659", title: "TET mock test analysis method", category: "learning", text: "Show me how to analyse a TET mock test after taking it. Tell me how to record marks for child development, languages, maths and EVS separately, find my weakest paper, and plan the next [number] days of study from the result." },
  { id: "learning-660", title: "TET teaching aptitude case questions", category: "learning", text: "Create a TET teaching aptitude practice set with [number] classroom case questions, like handling a slow learner or a naughty class. For each case, give the best response, explain why it works, and note the option most students wrongly choose." },
  { id: "learning-661", title: "TET last-45-days plan", category: "learning", text: "Make a last-45-days TET plan with [number] hours a day. Cover all five papers in rotation, give Sundays to full mock tests, and keep the final week only for short notes, pedagogy formulae and light practice." },
  { id: "learning-662", title: "NTSE mental ability test practice", category: "learning", text: "Give me an NTSE mental ability test practice plan with [number] questions a day on series, coding, analogy and puzzles. Include the fastest method for each type, a weekly timed test, and a way to track which type costs me the most marks." },
  { id: "learning-663", title: "NTSE scholastic aptitude science and social science", category: "learning", text: "Help me prepare for the NTSE scholastic aptitude test in science and social science. Give me a weekly plan that revises Class 9 and 10 chapters, with [number] practice questions per chapter and a Sunday test covering both subjects." },
  { id: "learning-664", title: "NTSE stage-wise preparation plan", category: "learning", text: "Make a stage-wise NTSE preparation plan, starting with the state-level stage and moving to the national stage. Show what to study for each stage, how many months to give each, and when to switch from school syllabus to extra practice." },
  { id: "learning-665", title: "Science Olympiad higher-order questions practice", category: "learning", text: "Help me practise higher-order thinking questions for the Science Olympiad. Give me [number] tricky questions a week from [subject, e.g. physics / biology], explain each answer simply, and show me how Olympiad questions differ from school exam questions." },
  { id: "learning-666", title: "Maths Olympiad problem-solving routine", category: "learning", text: "Make a Maths Olympiad problem-solving routine with [number] tough problems a week. Teach me how to attempt a problem for [number] minutes before checking hints, how to write a clean solution, and how to keep a notebook of methods I learn." },
  { id: "learning-667", title: "English Olympiad grammar and comprehension", category: "learning", text: "Give me an English Olympiad practice plan with daily grammar, vocabulary and comprehension work. Include [number] questions a day, a weekly reading passage with questions, and a method to learn [number] new words each week from my mistakes." },
  { id: "learning-668", title: "Olympiad mock test review method", category: "learning", text: "Show me how to review an Olympiad mock test properly. Tell me how to sort mistakes into silly errors, new concepts and tricky wording, and how to turn each new concept into a one-page note for revision before the next mock." },
  { id: "learning-669", title: "NTSE stage 2 revision plan", category: "learning", text: "Make an NTSE stage 2 revision plan for the final [number] weeks. Cover mental ability and scholastic aptitude in rotation, give Sundays to full mock tests, and keep the last week only for short notes, formulae and light practice." },
  { id: "learning-670", title: "Build your own mock test from textbook questions", category: "learning", text: "Show me how to build my own mock test from textbook and guidebook questions for [exam / subject]. Tell me how many questions to pick per chapter, how to set marks and time, and how to sit and attempt it like a real exam at home." },
  { id: "learning-671", title: "Mock test mistake notebook method", category: "learning", text: "Help me start a mock test mistake notebook for [exam]. Tell me what to write for each mistake — the question, my wrong answer, the right answer and why I went wrong — and how to revise the notebook every Sunday in 30 minutes." },
  { id: "learning-672", title: "Increase your mock score by 10 marks plan", category: "learning", text: "My mock score for [exam] is stuck at [score]. Make a [number]-week plan to raise it by 10 marks, focusing on the section where I lose the most marks, with daily drills, [number] mocks a week and a simple progress chart." },
  { id: "learning-673", title: "Mock test timing tracker per section", category: "learning", text: "Make a per-section timing tracker for my [exam] mock tests. Tell me what to record after each mock, how to spot the section where I spend too long, and how to set a time limit per section for the next mock." },
  { id: "learning-674", title: "Weekly mock test routine", category: "learning", text: "Build a weekly mock test routine for [exam] preparation. Tell me which day to take the mock, how long to rest before reviewing it, how to review it the same evening, and what to study on the other six days based on the result." },
  { id: "learning-675", title: "Analyse a mock test in 30 minutes", category: "learning", text: "Teach me to analyse a mock test in just 30 minutes. Give me a step-by-step checklist: check the score, list the top [number] mistakes, find the weakest topic, and write down exactly what to study tomorrow." },
  { id: "learning-676", title: "Mock test practice for your weakest subject only", category: "learning", text: "Make a mock test plan that focuses only on my weakest subject, [subject], for [exam]. Tell me how to take short subject-wise mocks, review them the same day, and decide when I am ready to return to full-length mocks." },
  { id: "learning-677", title: "Full-length mock exam day simulation at home", category: "learning", text: "Plan a full-length mock exam day at home for [exam]. Set the wake-up time, paper timing, breaks, and rules like no phone and no extra time, so I practise the real exam day from start to finish." },
  { id: "learning-678", title: "Write to-the-point 2-mark answers", category: "learning", text: "Teach me to write to-the-point 2-mark answers for [subject] board exams. Give me [number] questions, show a full-mark answer and a zero-mark answer for each, and a checklist to check length, keywords and neatness before moving on." },
  { id: "learning-679", title: "Write 5-mark answers with headings", category: "learning", text: "Help me write 5-mark answers with clear headings for [subject]. Give me a structure — introduction, [number] points with examples, and a conclusion — plus [number] practice questions and a way to score my own answers." },
  { id: "learning-680", title: "Answer writing for long theory questions", category: "learning", text: "Teach me to answer long theory questions in [subject] without running out of time. Show me how to plan the answer in one minute, use headings and bullet points, and give me [number] practice questions with model answer outlines." },
  { id: "learning-681", title: "Use diagrams and flowcharts in answers", category: "learning", text: "Show me how to use diagrams and flowcharts to score more in [subject] answers. Give me [number] topics where a diagram helps, a simple way to draw each one fast, and rules for labelling and referring to the diagram in my written answer." },
  { id: "learning-682", title: "Improve answer presentation and writing speed", category: "learning", text: "Help me improve my answer presentation and writing speed for board exams. Give me a daily 20-minute practice with [number] answers, tips for neat handwriting under time pressure, and a way to measure my words-per-minute each week." },
  { id: "learning-683", title: "Write answers when you only partly know", category: "learning", text: "Teach me what to write when I only partly know an answer in [exam]. Show me how to use the keywords I remember, structure a partial answer honestly, and avoid writing wrong facts, with [number] practice questions to try it on." },
  { id: "learning-684", title: "Answer writing practice with a timer", category: "learning", text: "Make a timed answer-writing practice plan for [subject] with [number] questions a day. Set a time limit per question based on its marks, tell me how to check my answers, and how to reduce my time per question each week." },
  { id: "learning-685", title: "Model answer comparison method", category: "learning", text: "Show me how to compare my answers with model answers for [subject]. Tell me what to check — keywords, structure, length and diagrams — and how to rewrite one weak answer a day using the model answer as a guide." },
  { id: "learning-686", title: "Three-hour paper time split plan", category: "learning", text: "Make a time split plan for a 3-hour [exam / subject] paper. Tell me how many minutes to give each section, when to start writing, when to leave tough questions, and how to save the last 15 minutes for checking." },
  { id: "learning-687", title: "Decide your question order in the exam hall", category: "learning", text: "Teach me how to decide my question order in the [exam] hall. Using my strengths in [subject / section], show me which questions to attempt first, which to leave for later, and how to stick to the plan under pressure." },
  { id: "learning-688", title: "Handle a tough question without losing time", category: "learning", text: "Teach me a method to handle a tough question in [exam] without losing time. Give me a 2-minute rule for deciding to skip or continue, a way to mark it for later, and [number] practice drills to build the habit." },
  { id: "learning-689", title: "Last 15 minutes exam checking routine", category: "learning", text: "Make a last-15-minutes checking routine for [exam] papers. Tell me what to check first — unattempted questions, calculation errors, or missed instructions — and how to practise the routine in every mock test." },
  { id: "learning-690", title: "Time plan for MCQ papers with negative marking", category: "learning", text: "Make a time plan for an MCQ paper with negative marking in [exam]. Tell me how many minutes per section, how many questions to attempt in the first pass, and when to return to marked questions in the second pass." },
  { id: "learning-691", title: "Speed versus accuracy balance tracker", category: "learning", text: "Help me balance speed and accuracy in [exam] mock tests. Give me a simple tracker to record attempts, correct answers and time after each mock, and a rule to decide whether to go faster or slower in the next mock." },
  { id: "learning-692", title: "Exam time plan for two papers in one day", category: "learning", text: "Make a time plan for an exam day with two papers, [paper 1] in the morning and [paper 2] in the afternoon. Cover revision between papers, rest, food and travel, and what to do if the first paper goes badly." },
  { id: "learning-693", title: "Practise finishing the paper 10 minutes early", category: "learning", text: "Help me practise finishing my [exam / subject] paper 10 minutes early. Give me a weekly drill with timed papers, a way to cut time per question gradually, and a checklist of what to do with the extra 10 minutes." },
  { id: "learning-694", title: "Spaced revision calendar for one chapter", category: "learning", text: "Make a spaced revision calendar for one chapter of [subject]. Tell me when to revise it after day 1, day 3, day 7 and day 14, what to do in each revision — recall, questions or notes — and how to fit it around new chapters." },
  { id: "learning-695", title: "Revise with self-testing not re-reading", category: "learning", text: "Teach me to revise [subject] with self-testing instead of re-reading my notes. Give me a method to turn each chapter into [number] questions, a daily test routine, and a way to re-test only the questions I got wrong." },
  { id: "learning-696", title: "One-page revision sheet per chapter", category: "learning", text: "Help me make a one-page revision sheet for each chapter of [subject]. Tell me what to include — key definitions, formulae, diagrams and one example — and give me a template I can copy for [number] chapters this week." },
  { id: "learning-697", title: "Formula sheet revision for maths and science", category: "learning", text: "Help me build a formula sheet for [subject, e.g. Class 10 maths / physics] with every important formula on [number] pages. Give me a daily 10-minute recall drill, and a weekly test where I write the formulae from memory before checking." },
  { id: "learning-698", title: "Active recall questions from your notes", category: "learning", text: "Show me how to turn my class notes on [topic] into active recall questions. Give me a method to write [number] questions per page of notes, a daily quiz routine using them, and a way to track which questions I still get wrong." },
  { id: "learning-699", title: "Revise a full subject in one day", category: "learning", text: "Make a one-day plan to revise a full subject, [subject], before an exam. Split the day into chapter blocks with breaks, tell me what to revise in each block, and include [number] quick tests to check what actually stayed in my memory." },
  { id: "learning-700", title: "Group revision session plan", category: "learning", text: "Plan a group revision session for [number] friends preparing for [exam]. Give me a 2-hour agenda with quiz rounds, doubt-clearing and a mock test review, plus simple rules so the group stays focused and everyone gets a turn." },
  { id: "learning-701", title: "Revise weak chapters first method", category: "learning", text: "Teach me the revise-weak-chapters-first method for [exam]. Show me how to rank my chapters by mock test scores, plan the next [number] days around the weakest three, and decide when a weak chapter is ready for a re-test." },
  { id: "learning-702", title: "Audio revision record and listen method", category: "learning", text: "Teach me an audio revision method for [subject]. Tell me how to record short summaries of each chapter in my own voice, when to listen to them — while walking or before sleep — and how to test myself after listening to each recording." },
  { id: "learning-703", title: "Night-before-exam revision do's and don'ts", category: "learning", text: "Give me a night-before-exam revision guide for [exam]. Tell me what to revise, what to stop doing, what time to sleep, and what to pack, so I walk into the hall calm and prepared instead of tired and panicky." },
  { id: "learning-704", title: "Exam result disappointment comeback plan", category: "learning", text: "I scored less than I expected in [exam] and feel disappointed. Help me make a calm comeback plan: analyse what went wrong, set a realistic new target, and build a [number]-week study routine that fixes the weak areas first." },
  { id: "learning-705", title: "Plan after a bad mock test", category: "learning", text: "I scored very low in my last mock test for [exam]. Help me recover without panicking: find the real reasons for the low score, fix the top [number] problems first, and plan the next mock so I can see clear improvement." },
  { id: "learning-706", title: "Study plan for a repeater or drop-year student", category: "learning", text: "Make a study plan for a repeater preparing for [exam] after a gap year. Cover how to use the extra time, which topics to relearn from scratch, how to stay motivated for [number] months, and when to start full mock tests." },
  { id: "learning-707", title: "Balance school and competitive exam preparation", category: "learning", text: "Help me balance school studies with [exam] preparation. Make a weekday and weekend timetable with [number] hours a day, show which topics overlap between school and the exam, and how to handle weeks when school tests and exam mocks clash." },
  { id: "learning-708", title: "Exam doubt-clearing routine with teachers", category: "learning", text: "Make a doubt-clearing routine for [exam] preparation. Tell me how to note doubts daily, which ones to ask teachers, which to solve myself, and how to keep a doubt diary that I revise every Sunday before the next week starts." },
  { id: "learning-709", title: "Exam admit card and documents checklist", category: "learning", text: "Make a checklist for [exam] day documents and items: admit card, ID proof, pens, and anything else the exam needs. Tell me when to download the admit card, what to verify on it, and what to do if I find a mistake in my name or photo." },
  { id: "learning-710", title: "Post-exam analysis between two papers", category: "learning", text: "Help me use the gap between two papers of [exam] well. Tell me how to review the first paper briefly without worrying, what to revise for the second paper, and how to rest and reset my mind in the [number] hours between them." },
  { id: "learning-711", title: "Python variables and input practice", category: "learning", text: "Teach me Python variables in simple words for a beginner in India. Show me how to store a name, an age and a price, ask the user for input, and print a friendly message using those values. Give me 5 small practice tasks with answers." },
  { id: "learning-712", title: "Python if-else decisions simply", category: "learning", text: "Teach me if and else in Python with simple everyday examples from India, like checking if marks are above 40 or if it is raining. Show me the code for 3 small decisions, explain each line, and give me 4 practice problems to try." },
  { id: "learning-713", title: "Loops in Python for absolute beginners", category: "learning", text: "Teach me loops in Python in simple words, using examples like printing numbers 1 to 10 and listing 5 friends. Show me a for loop and a while loop, explain when to use each one, and give me 4 small practice tasks." },
  { id: "learning-714", title: "Python lists with everyday examples", category: "learning", text: "Teach me Python lists in simple words for a beginner. Show me how to make a list of [5 favourite foods / 5 Indian cities], add an item, remove one, and print each item. Give me 4 practice tasks using a shopping list and a marks list." },
  { id: "learning-715", title: "Python functions in simple words", category: "learning", text: "Teach me Python functions in simple words, like a small machine that takes an input and gives an answer. Show me a function that adds two numbers and one that greets a person by name, then give me 3 functions to write on my own." },
  { id: "learning-716", title: "Build a simple calculator in Python", category: "learning", text: "Help me build a simple calculator in Python as a beginner project. It should add, subtract, multiply and divide two numbers typed by the user, and show the answer clearly. Explain the code line by line so I can change it myself." },
  { id: "learning-717", title: "Build a simple quiz game in Python", category: "learning", text: "Help me build a simple quiz game in Python about [Indian states / cricket / science]. It should ask 5 questions, keep the score, and show a message at the end. Explain the code simply and show me how to add 5 more questions." },
  { id: "learning-718", title: "Understand a Python error simply", category: "learning", text: "I have a small Python error and I do not understand it: [paste the error and your code]. Explain in simple words what the error means, show me the fixed code, and tell me 3 common mistakes beginners make so I can avoid them next time." },
  { id: "learning-719", title: "SQL basics with a small table", category: "learning", text: "Teach me SQL basics in simple words for a beginner. Show me how to make a small table for [students / shop items], add 5 rows, and find rows with a simple SELECT query. Explain each command and give me 4 practice questions." },
  { id: "learning-720", title: "Java first program in simple words", category: "learning", text: "Teach me Java basics in simple words and help me write my first program that prints Hello, [your name]. Explain what each line does, how to run it, and give me 3 tiny changes to try, like printing my age and city." },
  { id: "learning-721", title: "C programming first program simply", category: "learning", text: "Teach me C programming basics in simple words and help me write my first program that adds two numbers. Explain each line simply, show me how to run it, and give me 3 small practice tasks like printing my name and finding the bigger number." },
  { id: "learning-722", title: "JavaScript loops with simple examples", category: "learning", text: "Teach me loops in JavaScript in simple words for a beginner. Show me how to print numbers 1 to 10, list 5 Indian cities from an array, and stop a loop early. Explain each example line by line and give me 3 practice tasks." },
  { id: "learning-723", title: "Arrays in coding explained simply", category: "learning", text: "Teach me arrays in coding in simple words, using a list of 5 friends or 5 marks as the example. Show me how to make an array, read one item, change one item, and count how many items there are, in [Python / JavaScript]. Give me 4 practice tasks." },
  { id: "learning-724", title: "Sorting idea explained with marks", category: "learning", text: "Explain sorting in coding in simple words, like arranging 5 students by marks from highest to lowest. Show me the steps with a small example, explain why sorting is useful, and give me a tiny sorting task to try in [Python / JavaScript]." },
  { id: "learning-725", title: "Build a simple to-do list program", category: "learning", text: "Help me build a simple to-do list program in [Python / JavaScript] as a beginner. It should let me add a task, see all tasks, and tick one off as done. Explain the code in simple words and show me how to add a delete option." },
  { id: "learning-726", title: "Git basics to save coding work", category: "learning", text: "Teach me Git basics in simple words for a beginner who wants to save coding work safely. Explain what a repository, commit and push mean, show me the 5 basic commands to save a small project, and tell me what to do if I make a mistake." },
  { id: "learning-727", title: "How a website works in simple words", category: "learning", text: "Explain in simple words how a website works for a beginner in India: what a browser, server and domain mean, and what happens when I type an address and press enter. Use one everyday example and end with 3 quick questions to check I understood." },
  { id: "learning-728", title: "How a mobile app is made simply", category: "learning", text: "Explain in simple words how a mobile app is made, for a beginner in India. Cover the idea, the design, the coding, testing and publishing steps, with one example like a simple food-ordering app. End with 3 things a beginner can learn first." },
  { id: "learning-729", title: "Data types in coding simply", category: "learning", text: "Teach me data types in coding in simple words: numbers, text, true or false, and lists. Give me one Indian example for each, like age, name, is it raining, and a list of 5 cities, and 4 practice questions to test myself." },
  { id: "learning-730", title: "Pseudocode before coding simply", category: "learning", text: "Teach me pseudocode in simple words before I start coding. Show me how to write the steps for [making tea / finding the biggest of 3 numbers] in plain English first, then turn those steps into simple code. Give me 3 everyday tasks to write as pseudocode." },
  { id: "learning-731", title: "Mail merge letters in a word processor", category: "learning", text: "Teach me mail merge in a word processor in simple steps for a beginner in India. Show me how to make one letter and send it to 10 people from a list with their names and addresses changed automatically. Use a school or shop invitation as the example." },
  { id: "learning-732", title: "Table of contents for a school project", category: "learning", text: "Teach me how to add a table of contents in a word document for a school project on [topic]. Show me how to use heading styles, insert the contents page, and update it after I add pages. Give me a 5-point checklist to check before printing." },
  { id: "learning-733", title: "Track changes in a word document", category: "learning", text: "Teach me track changes in a word processor in simple words for a student in India. Show me how to turn it on, make edits that my teacher can see, accept or reject changes, and add a comment. Use a short essay as the practice example." },
  { id: "learning-734", title: "Page layout for a neat assignment", category: "learning", text: "Teach me page layout in a word processor in simple steps: margins, page size, line spacing and page breaks. Show me how to set up an A4 school assignment neatly, and give me a checklist for a tidy first page, headings and last page." },
  { id: "learning-735", title: "Headers footers and page numbers", category: "learning", text: "Teach me how to add headers, footers and page numbers in a word document for a school or college project. Show me how to put my name and topic at the top, page numbers at the bottom, and start numbering from page 2." },
  { id: "learning-736", title: "Find and replace tricks in Word", category: "learning", text: "Teach me find and replace in a word processor in simple words. Show me how to find a wrong spelling like [word], replace it everywhere in one step, and check the changes. Give me 3 practice tasks using a 2-page document." },
  { id: "learning-737", title: "IF formula in a spreadsheet simply", category: "learning", text: "Teach me the IF formula in a spreadsheet in simple words, using Indian school marks as the example. Show me how to mark a student Pass if marks are 40 or more and Fail if less, with 5 example rows. Give me 4 practice tasks with different conditions." },
  { id: "learning-738", title: "VLOOKUP in a spreadsheet simply", category: "learning", text: "Teach me VLOOKUP in a spreadsheet in simple words for a beginner. Use a small shop price list with 10 items to find the price of one item by its name. Explain each part of the formula and give me 4 practice questions to practise." },
  { id: "learning-739", title: "Conditional formatting for marks", category: "learning", text: "Teach me conditional formatting in a spreadsheet in simple words. Show me how to colour marks above 80 green and below 40 red in a class marks sheet, and how to highlight the highest value. Give me 3 practice tasks using monthly expenses." },
  { id: "learning-740", title: "Pivot tables in a spreadsheet simply", category: "learning", text: "Teach me pivot tables in a spreadsheet in simple words for a beginner. Use a small sales list from a shop in India to show total sales by item and by month. Explain each step and give me 2 practice tables to build on my own." },
  { id: "learning-741", title: "Dropdown lists with data validation", category: "learning", text: "Teach me data validation in a spreadsheet in simple words. Show me how to make a dropdown list for [Yes / No / Maybe] or for Indian states, so people cannot type wrong values. Give me a practice sheet for collecting 10 student details." },
  { id: "learning-742", title: "Freeze panes and print a spreadsheet", category: "learning", text: "Teach me how to freeze panes and set up printing in a spreadsheet in simple steps. Show me how to keep the top row visible while scrolling, fit a wide marks sheet on one A4 page, and add a title that repeats on every printed page." },
  { id: "learning-743", title: "Monthly household budget tracker", category: "learning", text: "Help me make a monthly household budget tracker in a spreadsheet for a family in India. Include income, rent, food, travel, school fees and savings, with totals that update automatically. Explain each formula and give me one tip to check it each week." },
  { id: "learning-744", title: "Class marks sheet with grades", category: "learning", text: "Help me make a class marks sheet in a spreadsheet for [subject] with 10 students. Add totals, averages and grades with a simple formula, and highlight the top 3 students. Explain each step so I can reuse the sheet for another subject." },
  { id: "learning-745", title: "Simple invoice template for a shop", category: "learning", text: "Help me make a simple invoice template in a spreadsheet for a small shop in India. Include shop name, customer name, date, item, quantity, price and total, with the total calculated automatically. Show me how to copy it for the next customer." },
  { id: "learning-746", title: "Monthly attendance sheet simply", category: "learning", text: "Help me make a monthly attendance sheet in a spreadsheet for a class or small office in India. Include names, dates, Present or Absent with a dropdown, and a total count for each person. Explain the counting formula in simple words." },
  { id: "learning-747", title: "Filter and sort data in a spreadsheet", category: "learning", text: "Teach me how to filter and sort data in a spreadsheet in simple steps. Use a list of 20 students with names, classes and marks to sort by marks and filter only one class. Give me 4 practice tasks to try on the same list." },
  { id: "learning-748", title: "Share a spreadsheet and work together", category: "learning", text: "Teach me how to share a spreadsheet safely and work on it with others in simple steps. Show me how to share a link, choose who can view or edit, add a comment, and check who changed what. Use a family budget or class project as the example." },
  { id: "learning-749", title: "Pie and line charts in a spreadsheet", category: "learning", text: "Teach me how to make pie and line charts in a spreadsheet in simple words. Use monthly spending in an Indian home for the pie chart and 6 months of electricity bills for the line chart. Show me how to add titles and read what each chart shows." },
  { id: "learning-750", title: "Seven simple slide design rules", category: "learning", text: "Teach me 7 simple slide design rules for a school presentation in India: one idea per slide, big text, few words, clear colours and one picture. Show me a bad slide and a good slide on [topic] so I can see the difference." },
  { id: "learning-751", title: "Simple animations and transitions", category: "learning", text: "Teach me simple animations and transitions in a presentation app in simple words. Show me how to add one gentle entrance to a heading, move between slides smoothly, and avoid too many effects. Use a 5-slide school presentation on [topic] as the example." },
  { id: "learning-752", title: "Presenter notes while presenting", category: "learning", text: "Teach me how to use presenter notes in a presentation app in simple steps. Show me how to write short speaking notes for each slide, see them while presenting, and keep the slides clean for the audience. Use a 5-minute talk on [topic] as the example." },
  { id: "learning-753", title: "Charts and tables on presentation slides", category: "learning", text: "Teach me how to add a chart and a table to a presentation in simple steps. Use a class survey of 30 students about [favourite sport / favourite food] to make a bar chart and a small table, and explain how to read them aloud to the class." },
  { id: "learning-754", title: "Ten-slide school project template", category: "learning", text: "Help me make a 10-slide template for a school project presentation on [topic] in India. Give me the title, one point per slide, where to put a picture, and what to say in one line for each slide. Keep the words simple for a Class [8/9/10] student." },
  { id: "learning-755", title: "Rehearse a presentation and time it", category: "learning", text: "Teach me how to rehearse a presentation and check its timing in simple steps. Show me how to practise a 5-minute talk on [topic], time each slide, cut extra words, and handle a slide that runs long. Give me a 3-day practice plan." },
  { id: "learning-756", title: "Make a certificate in a word processor", category: "learning", text: "Teach me how to make a simple certificate in a word processor for [a school competition / a workshop] in India. Show me how to add a border, the title, the person's name, the reason and the date, and save it so I can print 10 copies." },
  { id: "learning-757", title: "Weekly class timetable in a spreadsheet", category: "learning", text: "Help me make a weekly class timetable in a spreadsheet for a student in India. Include days, periods, subjects and break times, with colours for each subject. Explain how to print it on one page and stick it on my study wall." },
  { id: "learning-758", title: "Smart shopping list in a spreadsheet", category: "learning", text: "Help me make a smart shopping list in a spreadsheet for a family in India. Include item, quantity, shop price and total, with the total updating automatically. Show me how to sort it by shop section and tick items off on my phone." },
  { id: "learning-759", title: "Write a simple two-page report", category: "learning", text: "Teach me how to write a simple 2-page report in a word processor on [topic] for school or work in India. Show me the title, headings, short paragraphs, one table, and a conclusion. Give me a checklist to check spelling and layout before I send it." },
  { id: "learning-760", title: "Save a Word document as a PDF", category: "learning", text: "Teach me how to save a word document as a PDF and share it safely in simple steps. Show me how to check the layout, save it with a clear file name, and share it on WhatsApp or email without changing the format. Use a resume or school assignment as the example." },
  { id: "learning-761", title: "Touch typing starting with home row", category: "learning", text: "Teach me touch typing starting with the home row keys in simple steps for a beginner in India. Show me where to place my fingers, give me 10 minutes of daily practice words, and a way to check my speed each week without rushing." },
  { id: "learning-762", title: "Type numbers and symbols faster", category: "learning", text: "Teach me how to type numbers and symbols faster on a keyboard in simple steps. Give me daily practice with phone numbers, dates, rupee amounts and common symbols like @ and %. Include finger tips and a weekly speed check." },
  { id: "learning-763", title: "Typing accuracy before speed", category: "learning", text: "Help me improve my typing accuracy before speed with a simple daily plan. Give me 10 minutes of slow, correct typing practice, a way to count my mistakes, and 3 rules to follow when I make an error. Use easy English sentences about daily life in India." },
  { id: "learning-764", title: "Prepare for a typing test for a job", category: "learning", text: "Help me prepare for a typing test for a government or office job in India. Give me a 14-day practice plan with daily passages, a target speed and accuracy for each week, and tips for staying calm and steady on test day." },
  { id: "learning-765", title: "Five simple finger exercises for typing", category: "learning", text: "Give me 5 simple finger exercises for typing on a computer keyboard, for a beginner in India. Explain each exercise in one line, how long to do it, and how it helps my fingers find the right keys. Add a 10-minute daily routine to follow." },
  { id: "learning-766", title: "Type without looking at the keyboard", category: "learning", text: "Teach me how to type without looking at the keyboard in simple steps. Give me a 7-day plan with short daily drills, starting with the home row, and a simple test to check my progress. Tell me what to do when I keep pressing the wrong key." },
  { id: "learning-767", title: "Thirty-day plan to reach 30 wpm", category: "learning", text: "Make a 30-day plan to reach 30 words per minute in typing for a beginner in India. Give me a daily 15-minute practice, weekly speed targets, and simple passages to type. Start slow and correct, then build speed in the last 10 days." },
  { id: "learning-768", title: "Typing practice with common words", category: "learning", text: "Give me a typing practice set using the 100 most common English words, for a beginner in India. Arrange them into short sentences about home, school and work, give me a daily 10-minute routine, and a simple way to track my speed each week." },
  { id: "learning-769", title: "Type work emails faster and accurately", category: "learning", text: "Teach me how to type emails faster and more accurately for office work in India. Show me how to use short templates for common replies, type common phrases smoothly, and check spelling before sending. Give me 5 practice emails to type." },
  { id: "learning-770", title: "Typing for data entry work simply", category: "learning", text: "Teach me typing for data entry work in India in simple steps. Show me how to type names, numbers and dates neatly and quickly, check each row, and fix mistakes without slowing down. Give me a practice table with 20 rows to enter and check." },
  { id: "learning-771", title: "Spot a phishing email simply", category: "learning", text: "Teach me how to spot a phishing email in simple words, with examples common in India like fake bank, courier and job emails. Show me 5 warning signs, what to check before clicking a link, and what to do if I already clicked one." },
  { id: "learning-772", title: "Make a strong password you remember", category: "learning", text: "Teach me how to make a strong password in simple words for a beginner in India. Show me how to make one I can remember using 3 random words and numbers, why I should not reuse it, and how often to change important passwords." },
  { id: "learning-773", title: "Use a password manager simply", category: "learning", text: "Teach me how to use a password manager in simple words for a beginner in India. Explain what it does, how to save one password safely, and how to log in on my phone and computer without remembering every password. Give me 3 safety rules to follow." },
  { id: "learning-774", title: "Two-factor authentication in simple words", category: "learning", text: "Teach me two-factor authentication in simple words for a beginner in India. Show me how to turn it on for my email and bank app, what the extra code is for, and what to do if I lose my phone. Give me a checklist for my 3 most important accounts." },
  { id: "learning-775", title: "Spot fake news on WhatsApp", category: "learning", text: "Teach me how to spot fake news on WhatsApp in simple words, with examples common in India like fake health tips and false warnings. Show me 4 quick checks before forwarding a message, and what to say to family who share such messages." },
  { id: "learning-776", title: "Shop online safely checklist", category: "learning", text: "Teach me how to shop online safely in India in simple steps. Show me how to check a seller, read reviews carefully, pay safely, and keep a record of my order. Give me a checklist to use before I pay for anything online." },
  { id: "learning-777", title: "Spot a fake job offer online", category: "learning", text: "Teach me how to spot a fake job offer online in simple words, with examples common in India like asking for a fee or a work-from-home deposit. Show me 5 warning signs and what to check before sharing my documents or paying anything." },
  { id: "learning-778", title: "Spot a fake UPI payment screenshot", category: "learning", text: "Teach me how to spot a fake UPI payment screenshot in simple words for a shopkeeper or seller in India. Show me what to check in my own bank app instead of trusting a photo, and what to do if a customer pressures me to accept it quickly." },
  { id: "learning-779", title: "Update phone apps safely each week", category: "learning", text: "Teach me why updating my phone apps matters for safety in simple words. Show me how to check for updates, turn on automatic updates for important apps, and avoid fake update messages. Give me a weekly 5-minute phone safety check." },
  { id: "learning-780", title: "Use public Wi-Fi safely in India", category: "learning", text: "Teach me how to use public Wi-Fi safely in India in simple words, like at a railway station or cafe. Show me what not to do, like banking or entering passwords, and how to use mobile data instead for important work. Give me 5 safety rules." },
  { id: "learning-781", title: "Protect photos and privacy on my phone", category: "learning", text: "Teach me how to protect my photos and privacy on my phone in simple steps. Show me how to check which apps can see my photos, turn off location on photos, and keep family photos private. Use settings a beginner in India can follow." },
  { id: "learning-782", title: "Spot scam calls asking for an OTP", category: "learning", text: "Teach me how to spot scam calls asking for an OTP in simple words, with examples common in India like fake bank and KYC calls. Show me what to say, why I must never share an OTP, and what to do if I shared one by mistake." },
  { id: "learning-783", title: "Set privacy on social media simply", category: "learning", text: "Teach me how to set privacy on social media in simple steps for a beginner in India. Show me how to make my profile private, choose who can message me, and hide my phone number and location. Give me a checklist to review every month." },
  { id: "learning-784", title: "Check if a website is safe before paying", category: "learning", text: "Teach me how to check if a website is safe before paying in simple words. Show me what to look for in the address, the seller details and the payment page, using an Indian shopping site as the example. Give me 5 warning signs to stop and check." },
  { id: "learning-785", title: "Safe video calling rules for children", category: "learning", text: "Teach me safe video calling rules for children in India in simple words. Explain who they can call, what to do if a stranger joins, and why they should never share personal details on a call. Give me 5 family rules to agree together." },
  { id: "learning-786", title: "What to do after online fraud in India", category: "learning", text: "Teach me what to do if I face online fraud in India, in simple steps. Explain how to save proof, block the payment, call the helpline 1930, and report on the national cybercrime portal. Tell me what details to keep ready before I call." },
  { id: "learning-787", title: "Download apps and files safely", category: "learning", text: "Teach me how to download apps and files safely in simple words. Show me how to use the official app store, check the app name and reviews, and avoid free download links from unknown sites. Give me 5 rules for my phone and computer." },
  { id: "learning-788", title: "Spot clickbait and risky links", category: "learning", text: "Teach me how to spot clickbait and risky links in simple words, with examples common in India like free prize and lottery messages. Show me 4 signs a link is unsafe, and what to do instead of clicking it in a hurry." },
  { id: "learning-789", title: "Make YouTube safer for my child", category: "learning", text: "Teach me how to make YouTube safer for my child in India in simple steps. Show me how to turn on restricted mode, set a time limit, and check watch history together. Give me 5 simple family rules for watching videos." },
  { id: "learning-790", title: "Back up photos and files safely", category: "learning", text: "Teach me how to back up my important photos and files safely in simple steps. Show me how to save copies on my phone and in a cloud account, and how to check the backup worked. Use examples like school certificates, photos and important documents." },
  { id: "learning-791", title: "Use AI to explain a difficult chapter", category: "learning", text: "Show me how to use an AI tool to explain a difficult chapter from my textbook in simple words. Tell me what to type, how to ask for examples from daily life in India, and how to check the answer with my teacher or book before I trust it." },
  { id: "learning-792", title: "Use AI to make practice questions", category: "learning", text: "Show me how to use an AI tool to make practice questions from my lesson on [topic]. Tell me what to type to get easy, medium and hard questions, how to ask for answers separately, and how to use them for a 20-minute self-test." },
  { id: "learning-793", title: "Use AI to check my essay grammar", category: "learning", text: "Show me how to use an AI tool to check my school essay for grammar and spelling in simple words. Tell me what to paste, how to ask for corrections with reasons, and how to rewrite the essay in my own words instead of copying the answer." },
  { id: "learning-794", title: "Use AI to plan my study week", category: "learning", text: "Show me how to use an AI tool to plan my study week for [subjects] before an exam in India. Tell me what details to give it, how to ask for breaks and revision time, and how to change the plan if one subject takes longer than expected." },
  { id: "learning-795", title: "Use AI to summarise a long article", category: "learning", text: "Show me how to use an AI tool to summarise a long article or news story in simple words. Tell me what to paste, how to ask for 5 key points, and how to check the summary against the original before I use it for class." },
  { id: "learning-796", title: "Use AI to learn new words daily", category: "learning", text: "Show me how to use an AI tool to learn 5 new English words every day. Tell me what to ask for: the meaning, one simple sentence, and a quick quiz. Use words useful for school, work and daily life in India." },
  { id: "learning-797", title: "Use AI as a speaking practice partner", category: "learning", text: "Show me how to use an AI tool as a speaking practice partner for English in simple words. Tell me how to ask it to chat slowly, correct my mistakes gently, and give me 5 daily conversation topics like my family, my town and my favourite food." },
  { id: "learning-798", title: "Use AI to turn notes into flashcards", category: "learning", text: "Show me how to use an AI tool to turn my class notes on [topic] into flashcards for revision. Tell me what to paste, how to ask for short questions and one-line answers, and how to test myself with 10 cards a day." },
  { id: "learning-799", title: "Use AI to find a mistake in my code", category: "learning", text: "Show me how to use an AI tool to find a mistake in my beginner code. Tell me what to paste, how to ask it to explain the error in simple words, and how to fix it myself instead of copying the answer without understanding it." },
  { id: "learning-800", title: "Use AI to prepare interview answers", category: "learning", text: "Show me how to use an AI tool to prepare answers for a job interview for [job role] in India. Tell me what to type about my skills, how to ask for simple practice questions, and how to turn the answers into my own words before the interview." },
  { id: "learning-801", title: "Use AI to learn phrases for travel", category: "learning", text: "Show me how to use an AI tool to learn useful phrases in [language] for travel in India. Tell me how to ask for the phrase, its meaning, how to say it, and a short practice conversation. Give me 10 phrases for a market, a train and a hotel." },
  { id: "learning-802", title: "Use AI to make a quiz from my notes", category: "learning", text: "Show me how to use an AI tool to make a quiz from my own notes on [topic]. Tell me what to paste, how to ask for 10 multiple-choice questions with answers at the end, and how to use the quiz to find what I still need to revise." },
  { id: "learning-803", title: "Use AI to compare two topics simply", category: "learning", text: "Show me how to use an AI tool to compare two topics, like [topic A] and [topic B], in simple words. Tell me what to ask for: a small table of similarities and differences, one example each, and a one-line summary I can remember." },
  { id: "learning-804", title: "Use AI for a first draft then edit it", category: "learning", text: "Show me how to use an AI tool to write a first draft of [a letter / an essay / a speech] and then edit it myself. Tell me what to type, how to check the draft for mistakes, and how to rewrite it in my own voice before I submit it." },
  { id: "learning-805", title: "Use AI to learn spreadsheet formulas", category: "learning", text: "Show me how to use an AI tool to learn spreadsheet formulas in simple words. Tell me how to describe what I want, like adding marks or finding the highest value, and how to ask for the formula, one example, and a practice task." },
  { id: "learning-806", title: "Use AI to practise maths word problems", category: "learning", text: "Show me how to use an AI tool to practise maths word problems about daily life in India, like shopping discounts and train timings. Tell me how to ask for a problem, a step-by-step hint, and a similar problem to try on my own." },
  { id: "learning-807", title: "Use AI to turn notes into a mind map", category: "learning", text: "Show me how to use an AI tool to turn my notes on [chapter] into a mind map for revision. Tell me what to paste, how to ask for the main idea and 4 branches, and how to draw the map on paper in 10 minutes." },
  { id: "learning-808", title: "Check facts from an AI tool simply", category: "learning", text: "Teach me how to check facts from an AI tool before I trust them, in simple words. Show me how to ask for the source, compare the answer with my textbook or a trusted site, and spot when the answer looks wrong. Use one example from [topic]." },
  { id: "learning-809", title: "Use AI to learn a skill in 30 days", category: "learning", text: "Show me how to use an AI tool to learn a new skill in 30 days, like [typing / basic coding / spoken English]. Tell me what to ask for: a daily plan, one small task a day, and a weekly check to see what I have learned." },
  { id: "learning-810", title: "What not to share with an AI tool", category: "learning", text: "Teach me what not to share with an AI tool in simple words. Explain why I should never paste passwords, OTPs, bank details or private photos, and what to do instead. Give me 5 safety rules for using AI tools in India." },
  { id: "learning-811", title: "Five voice exercises to speak clearly", category: "learning", text: "Teach me 5 simple voice exercises to speak clearly on stage in India, like slow breathing, tongue twisters and reading aloud. Explain each exercise in one line, how long to do it, and give me a 10-minute daily routine before a talk." },
  { id: "learning-812", title: "Handle stage fear in simple steps", category: "learning", text: "Teach me how to handle stage fear in simple steps for a student in India. Show me what to do the night before, 10 minutes before, and in the first 30 seconds on stage. Give me a small practice plan to speak in front of family first." },
  { id: "learning-813", title: "Two-minute self-introduction simply", category: "learning", text: "Help me write a 2-minute self-introduction for [school / college / a job interview] in India. Give me a simple structure: my name, where I am from, what I study or do, and one thing I like. Add a short example I can change to fit me." },
  { id: "learning-814", title: "Short warm toast at a family function", category: "learning", text: "Help me give a short, warm toast at a family function in India, like a birthday or housewarming. Give me a simple opening, 2 lines about the person, and a closing wish. Keep it under one minute and easy to say in simple English." },
  { id: "learning-815", title: "Present a class project confidently", category: "learning", text: "Teach me how to present a class project confidently in simple steps for a student in India. Show me how to start, explain each part in short lines, show my chart or model, and end with what I learned. Give me a 5-minute practice plan." },
  { id: "learning-816", title: "Answer questions after a talk", category: "learning", text: "Teach me how to answer questions after a talk in simple words. Show me polite lines to use when I know the answer, when I need time to think, and when I do not know. Give me 5 practice questions on [my topic] to prepare." },
  { id: "learning-817", title: "Use hand gestures while speaking", category: "learning", text: "Teach me how to use hand gestures while speaking in simple words for a beginner in India. Show me 5 natural gestures, when to use them, and what to avoid. Give me a 5-minute practice talk on [topic] to try them with." },
  { id: "learning-818", title: "Speak slowly and clearly practice", category: "learning", text: "Teach me how to speak slowly and clearly in simple steps for a student in India. Give me a daily 10-minute practice: reading aloud, pausing after each idea, and recording myself. Show me how to check if my friends can follow me easily." },
  { id: "learning-819", title: "Tell a personal story on stage", category: "learning", text: "Teach me how to tell a short personal story on stage in simple words, like a lesson I learned at school or at home in India. Show me how to start, build up to the main moment, and end with the lesson. Keep it under 3 minutes." },
  { id: "learning-820", title: "Debate rebuttal basics for beginners", category: "learning", text: "Teach me debate rebuttal basics in simple words for a school student in India. Show me how to listen to the other side, pick one weak point, and answer it politely with one example. Give me a practice debate on [topic] with 3 points each side." },
  { id: "learning-821", title: "Speak English in a work meeting", category: "learning", text: "Teach me how to speak in English in a work meeting in India in simple words. Give me polite lines to share an idea, agree, disagree gently, and ask a question. Add 5 practice sentences I can use in my next meeting." },
  { id: "learning-822", title: "Host a small online meeting simply", category: "learning", text: "Teach me how to host a small online meeting in simple steps for a beginner in India. Show me how to start on time, welcome everyone, share my screen, ask for views one by one, and close with clear next steps. Give me a 30-minute plan." },
  { id: "learning-823", title: "Short farewell speech for school", category: "learning", text: "Help me write a short farewell speech for school in India in simple English. Give me a warm opening, 2 memories from school life, thanks for teachers and friends, and a hopeful closing. Keep it under 3 minutes and easy to practise." },
  { id: "learning-824", title: "Short speech for morning assembly", category: "learning", text: "Help me prepare a short speech for a school morning assembly in India on [topic]. Give me a simple opening, 3 short points, and a closing line. Keep it under 2 minutes and easy to say clearly in front of the whole school." },
  { id: "learning-825", title: "Improve speaking by recording myself", category: "learning", text: "Teach me how to improve my speaking by recording myself in simple steps. Show me how to record a 2-minute talk on [topic] on my phone, listen back, and note 3 things to improve. Give me a weekly practice plan for one month." },
  { id: "learning-826", title: "Memory palace method for lists", category: "learning", text: "Teach me the memory palace method in simple words to remember a list of [10 items / 10 points]. Show me how to link each item to a room in my home in India, walk through it in my mind, and recall the list in order. Give me a practice list to try." },
  { id: "learning-827", title: "Chunking to remember long numbers", category: "learning", text: "Teach me chunking to remember long numbers in simple words, like phone numbers and dates in India. Show me how to break a number into small groups of 2 or 3, say each group aloud, and recall it after 5 minutes. Give me 5 numbers to practise with." },
  { id: "learning-828", title: "Acronyms to remember a list simply", category: "learning", text: "Teach me how to use acronyms to remember a list in simple words for a student in India. Show me how to take the first letter of each point in [topic] and make a fun word or sentence. Give me 3 examples and one list to try on my own." },
  { id: "learning-829", title: "Spaced repetition plan for exams", category: "learning", text: "Teach me spaced repetition in simple words to remember lessons for exams in India. Show me when to revise: same day, next day, after 3 days and after a week. Make a 7-day plan for [chapter] with 10 minutes of revision each time." },
  { id: "learning-830", title: "Remember names of new people", category: "learning", text: "Teach me how to remember names of new people in simple words. Show me what to do when I first hear a name, how to repeat it in a sentence, and how to link it to something familiar. Give me a 7-day practice plan for school or work in India." },
  { id: "learning-831", title: "Visual association to remember words", category: "learning", text: "Teach me visual association to remember new words in simple words for a student in India. Show me how to link each word in [list] to a funny picture in my mind, draw it quickly, and recall the words from the pictures. Give me 10 words to practise with." },
  { id: "learning-832", title: "Active recall after reading a page", category: "learning", text: "Teach me active recall in simple words to remember what I read. Show me how to read one page, close the book, and write down what I remember, then check what I missed. Give me a 20-minute daily routine for [subject] in India." },
  { id: "learning-833", title: "Remember history dates with a timeline", category: "learning", text: "Teach me how to remember history dates in India using a simple timeline. Show me how to place 10 important events in order, link each date to a story, and revise the timeline in 10 minutes. Use [freedom movement / a period] as the example." },
  { id: "learning-834", title: "Remember a speech without notes", category: "learning", text: "Teach me how to remember a short speech without reading from paper, in simple steps for a student in India. Show me how to break the speech into 4 parts, link each part to a key word, and practise it in small chunks. Give me a 3-day plan for a 2-minute speech." },
  { id: "learning-835", title: "Ten-minute daily memory workout", category: "learning", text: "Give me a 10-minute daily memory workout for a student in India. Include recalling yesterday's lesson, remembering a 10-item list, and naming 5 things I saw today. Explain each exercise in one line and how to track my progress each week." },
  { id: "learning-836", title: "Skim a textbook chapter in 10 minutes", category: "learning", text: "Teach me how to skim a textbook chapter in 10 minutes in simple steps. Show me how to read the headings, first lines and summary first, note 5 key points, and decide what to read fully later. Use a chapter from [subject] as the example." },
  { id: "learning-837", title: "Read a newspaper fast for key points", category: "learning", text: "Teach me how to read a newspaper fast and catch the key points in simple steps, for a student in India. Show me how to scan headlines, read the first paragraph, and note 5 important news items in 15 minutes. Give me a daily practice plan." },
  { id: "learning-838", title: "Read a long PDF faster simply", category: "learning", text: "Teach me how to read a long PDF faster in simple steps for a student in India. Show me how to check the contents, search for key words, read the summary first, and take 5 short notes. Use a [notes / guide] PDF as the practice example." },
  { id: "learning-839", title: "Pointer method for reading faster", category: "learning", text: "Teach me the pointer method for reading faster in simple words. Show me how to move my finger or a pen under each line, keep a steady pace, and avoid going back. Give me a 10-minute daily practice with a passage from [topic]." },
  { id: "learning-840", title: "Stop saying every word while reading", category: "learning", text: "Teach me how to stop saying every word in my head while reading, in simple steps for a student in India. Give me 3 gentle exercises, like humming softly and reading in phrases, and a 10-minute daily practice to read faster without losing meaning." },
  { id: "learning-841", title: "Cornell note-taking method simply", category: "learning", text: "Teach me the Cornell note-taking method in simple words for a student in India. Show me how to divide a page into notes, cues and summary, take notes on [lesson], and use the cue column to test myself. Give me a blank format I can copy." },
  { id: "learning-842", title: "Take notes from a learning video", category: "learning", text: "Teach me how to take good notes from a learning video on YouTube in simple steps. Show me how to pause, write 5 key points, note one doubt, and summarise the video in 3 lines. Use a video on [topic] as the practice example." },
  { id: "learning-843", title: "Take notes during an online class", category: "learning", text: "Teach me how to take notes during an online class in simple steps for a student in India. Show me how to prepare before class, write only main points, mark doubts, and review the notes the same evening. Give me a one-page format to follow." },
  { id: "learning-844", title: "Organise digital notes in folders", category: "learning", text: "Teach me how to organise my digital notes in folders in simple steps for a student in India. Show me how to name folders by subject, save notes with clear dates, and find any note in one minute. Give me a simple folder plan for 5 subjects." },
  { id: "learning-845", title: "Summarise notes in my own words", category: "learning", text: "Teach me how to summarise my class notes in my own words in simple steps. Show me how to read one page, close it, and write 5 lines without copying. Use notes from [subject] as the example and give me 3 practice pages to try." },
  { id: "learning-846", title: "Research a topic online step by step", category: "learning", text: "Teach me how to research a topic online step by step for a school project in India on [topic]. Show me how to plan questions, search with clear words, pick 3 good sources, and note facts with their source. Give me a simple research sheet to fill." },
  { id: "learning-847", title: "Check if a website is trustworthy", category: "learning", text: "Teach me how to check if a website is trustworthy for school research in simple words. Show me what to look for: who wrote it, when it was updated, and whether other good sites agree. Give me a 5-point checklist using [topic] as the example." },
  { id: "learning-848", title: "Find free learning videos online", category: "learning", text: "Teach me how to find free learning videos online in simple steps for a student in India. Show me how to search for [topic], check if the video suits my class, and make a playlist of 5 videos. Tell me how to avoid videos that waste my time." },
  { id: "learning-849", title: "Plan one week of a free online course", category: "learning", text: "Help me plan one week of a free online course on [topic] for a beginner in India. Give me daily 30-minute lessons, one practice task a day, and a weekend review. Show me how to stay on track if I miss a day." },
  { id: "learning-850", title: "Stay focused in online classes", category: "learning", text: "Teach me how to stay focused in online classes in simple steps for a student in India. Show me how to set up a quiet corner, keep my phone away, take short notes, and ask one question in each class. Give me a daily checklist to follow." },
  { id: "learning-851", title: "Choose a free online course wisely", category: "learning", text: "Teach me how to choose a free online course in simple steps for a beginner in India. Show me how to check the topics, the teacher, the time it needs, and what I will learn by the end. Give me 5 questions to ask before I join any course on [topic]." },
  { id: "learning-852", title: "Study plan for learning online at home", category: "learning", text: "Help me make a study plan for learning online at home in India for [subject or skill]. Give me fixed study hours, breaks, one practice task a day, and a weekly review. Show me how to balance online lessons with homework and rest." },
  { id: "learning-853", title: "Short forms and symbols in notes", category: "learning", text: "Teach me how to use short forms and symbols in my notes in simple words for a student in India. Give me 20 useful short forms for common words, show me how to use them in a lesson on [subject], and how to expand them when I revise." },
  { id: "learning-854", title: "Revise notes the same day simply", category: "learning", text: "Teach me how to revise my notes the same day in simple steps for a student in India. Show me a 15-minute routine: read the notes, cover them, recall 5 key points, and write one doubt to ask tomorrow. Give me a plan for [subject]." },
  { id: "learning-855", title: "Build a personal knowledge notebook", category: "learning", text: "Help me build a personal knowledge notebook in simple steps for a student in India. Show me how to keep one page per topic, add new facts, link related topics, and review it every Sunday. Give me a starter format for 5 topics from [subjects]." },
  { id: "learning-856", title: "Phonics sounds at home for a 4-year-old", category: "learning", text: "Teach my 4-year-old the sounds of English letters at home in 10 minutes a day. Give me a 2-week plan with one sound per day, a simple game for each sound, and everyday words like [cat, sun, ball] to practise with." },
  { id: "learning-857", title: "Teaching numbers to a toddler with toys", category: "learning", text: "Help me teach numbers 1 to 20 to my 3-year-old using toys we already have at home. Give me 5 short games, one for each day, that use [blocks, spoons, toy cars] and end with a fun counting song." },
  { id: "learning-858", title: "Colours and shapes games for a 3-year-old", category: "learning", text: "Give me 7 simple games to teach colours and shapes to my 3-year-old at home. Use things like cups, cushions and chapati shapes, keep each game under 10 minutes, and tell me what to praise when my child gets it right." },
  { id: "learning-859", title: "First English words for a preschooler", category: "learning", text: "Help my 5-year-old learn their first 50 English words before school starts. Make a 4-week plan with 3 words a day, a picture or action for each word, and a weekend revision game using [objects at home]." },
  { id: "learning-860", title: "Rhymes that teach new words to a 2-year-old", category: "learning", text: "Suggest 10 short rhymes that teach new words to a 2-year-old, including [a rhyme about animals, a rhyme about food, a rhyme about the body]. For each rhyme, give one action to do while singing and one new word it teaches." },
  { id: "learning-861", title: "Teaching a child to hold a pencil right", category: "learning", text: "Teach my 4-year-old to hold a pencil the right way before they start writing. Give me 3 simple grip exercises, the correct finger position explained in plain words, and a 5-minute daily practice using [crayons or thick pencils]." },
  { id: "learning-862", title: "Simple sorting games for a preschooler", category: "learning", text: "Give me 6 sorting games for my preschooler using things at home, like sorting dal by colour, socks by size, and spoons by shape. Explain what each game teaches and how to make it a little harder each week." },
  { id: "learning-863", title: "Teaching days of the week to a 5-year-old", category: "learning", text: "Help me teach the days of the week to my 5-year-old in a fun way. Make a simple song, a chart we can stick on the wall, and a daily question like [what day is today], so my child learns the order in one week." },
  { id: "learning-864", title: "Months and seasons for a young child", category: "learning", text: "Teach my 4-year-old the months of the year and the three main Indian seasons — summer, monsoon and winter. Use festivals like [Diwali, Holi] as markers, give one outdoor activity per season, and a simple way to remember the order." },
  { id: "learning-865", title: "Teaching a child family members names", category: "learning", text: "Help my 5-year-old learn the names of all family members and what each person is called, like grandmother, uncle and cousin. Give me a simple family tree drawing activity and a fun quiz game we can play together." },
  { id: "learning-866", title: "Bedtime counting games for a 3-year-old", category: "learning", text: "Give me 5 bedtime counting games for my 3-year-old that we can play in bed without toys, such as counting fingers, toes and stars on the blanket. Keep each game calm and under 5 minutes so my child falls asleep happily." },
  { id: "learning-867", title: "Teaching a preschooler letters on signboards", category: "learning", text: "Help my 4-year-old recognise letters by pointing them out on shop boards, bus signs and packets at home. Give me a 7-day plan with one letter a day, a game for the walk to the shop, and a way to celebrate each letter learned." },
  { id: "learning-868", title: "Animal names and sounds for a toddler", category: "learning", text: "Teach my 2-year-old the names and sounds of 10 common animals, like cow, dog, cat and elephant. Give me a sound game, a picture-matching game, and a simple animal song we can sing together every morning." },
  { id: "learning-869", title: "Teaching a child to dress by themselves", category: "learning", text: "Teach my 4-year-old to button a shirt, zip a bag and put on shoes by themselves. Break each task into 3 tiny steps, suggest a patient way to practise for 5 minutes a day, and tell me how to praise effort, not just success." },
  { id: "learning-870", title: "Mother-tongue alphabet fun for a 4-year-old", category: "learning", text: "Help my 4-year-old learn the first letters of our mother tongue, [Tamil / Hindi / Telugu], through play. Give me a 2-week plan with one letter a day, a song or rhyme for each letter, and a drawing activity that matches its sound." },
  { id: "learning-871", title: "Teaching a child to share toys at playgroup", category: "learning", text: "Help my 3-year-old learn to share toys at playgroup without tears. Give me 3 simple turn-taking games we can practise at home, the exact words I can teach my child to say, and what to do when sharing still feels hard." },
  { id: "learning-872", title: "Helping a shy preschooler greet people", category: "learning", text: "Help my shy 4-year-old learn to greet guests, say thank you and answer simple questions politely. Give me a gentle 2-week practice plan with role play at home, short scripts to practise, and ways to build confidence without forcing my child." },
  { id: "learning-873", title: "Nature walk lessons for a 4-year-old", category: "learning", text: "Plan a 20-minute nature walk lesson for my 4-year-old in our street or park. List 5 things to look for, like [a leaf, a bird, a flower], one simple question to ask about each, and a drawing activity to do when we get home." },
  { id: "learning-874", title: "Teaching a toddler to tidy up toys", category: "learning", text: "Teach my 3-year-old to put toys away after playing, using a fun clean-up song and labelled boxes. Give me a simple routine for after playtime, a reward chart that uses stars, and tips for days when my child refuses to tidy up." },
  { id: "learning-875", title: "First drawing lessons for a 3-year-old", category: "learning", text: "Give me a first drawing plan for my 3-year-old using crayons and big sheets of paper. Include 7 daily scribble activities, like drawing circles, lines and rain, and tell me what to say to encourage my child instead of correcting their drawing." },
  { id: "learning-876", title: "Storytelling with puppets for a 5-year-old", category: "learning", text: "Help me tell a bedtime story to my 5-year-old using two hand puppets or soft toys. Give me a simple 5-minute story about [a kind lion / a brave little girl], with voices for each puppet, one moral, and a question to ask at the end." },
  { id: "learning-877", title: "Turning a fairy tale into a moral lesson", category: "learning", text: "Turn the story of [a fairy tale or Panchatantra tale] into a lesson about honesty for my 6-year-old. Retell it in simple words, pause at 3 points to ask my child what the character should do, and end with one line my child can remember." },
  { id: "learning-878", title: "Block tower games that teach balance", category: "learning", text: "Help my 4-year-old learn about balance and size by building towers with blocks. Give me 5 block challenges, from easy to hard, explain what each one teaches, and tell me the questions to ask while my child builds." },
  { id: "learning-879", title: "Kitchen play that teaches measuring", category: "learning", text: "Teach my 5-year-old simple measuring through kitchen play, using cups of rice, spoons of dal and water in bowls. Give me 4 safe activities, explain words like full, half and empty, and a fun way to test what my child learned." },
  { id: "learning-880", title: "Treasure hunt that teaches directions at home", category: "learning", text: "Plan a treasure hunt at home that teaches my 6-year-old directions like left, right, up and down. Give me 8 simple clues, a small prize at the end, and a map my child can draw after finding the treasure." },
  { id: "learning-881", title: "Board games that teach a child to count", category: "learning", text: "Suggest 5 board games that teach my 6-year-old to count, add and take turns, using games we can buy in India or make at home. For each game, say what maths skill it teaches and how long one round takes." },
  { id: "learning-882", title: "Pretend shop game for learning money", category: "learning", text: "Help me set up a pretend shop at home where my 5-year-old is the shopkeeper and I am the customer. Use toy money or paper notes, give me a price list for [fruits or toys], and 5 questions that teach counting and simple money." },
  { id: "learning-883", title: "Making a family storybook with a child", category: "learning", text: "Help me make a small storybook with my 6-year-old about our family, using drawings and one sentence per page. Give me a 6-page plan, the sentence starter for each page, and tips to let my child lead the story." },
  { id: "learning-884", title: "Retelling a Panchatantra story simply", category: "learning", text: "Retell a Panchatantra story about [a clever rabbit / a foolish lion / a loyal friend] in very simple words for my 5-year-old. Keep it under 3 minutes, use animal sounds, and end with the moral explained in one short sentence my child can repeat." },
  { id: "learning-885", title: "Story dice game for a child's imagination", category: "learning", text: "Make a story dice game for my 7-year-old using 6 pictures like [a king, a river, a mango, a train]. Explain how to make the dice from paper, how to play, and how to help my child build a short story from 3 rolls." },
  { id: "learning-886", title: "Garden learning game for kids", category: "learning", text: "Plan a garden learning game for my 5-year-old using a small pot, soil and seeds. Teach my child how plants grow, give a daily watering job, and a simple diary where my child draws the plant each week." },
  { id: "learning-887", title: "Puppet show script about kindness", category: "learning", text: "Write a short 5-minute puppet show script for my child about being kind to a new friend at school. Give me 2 puppet characters, simple lines each, one song in the middle, and a happy ending my child can act out." },
  { id: "learning-888", title: "Memory card game for a 6-year-old", category: "learning", text: "Make a memory card game for my 6-year-old using pictures of [fruits, animals or vehicles] drawn on paper. Explain how to make 12 cards, how to play in pairs, and how to make the game harder as my child gets better." },
  { id: "learning-889", title: "Hide and seek that teaches counting to 20", category: "learning", text: "Teach my 4-year-old to count to 20 through a hide-and-seek game at home. Give me the counting rhyme to use, safe hiding spots, and a way to practise counting backwards from 10 when it is my child's turn to seek." },
  { id: "learning-890", title: "Learning about rain with an outdoor game", category: "learning", text: "Help my 6-year-old learn about rain with a simple outdoor game on a rainy day. List 4 things to watch, like puddles, clouds and dripping leaves, one question for each, and a drawing to make after we come inside and dry off." },
  { id: "learning-891", title: "Dress-up play that teaches community jobs", category: "learning", text: "Use dress-up play to teach my 5-year-old about jobs like doctor, teacher, farmer and postman. Give me a simple costume idea for each job using clothes at home, one tool for each role, and a question my child can answer in character." },
  { id: "learning-892", title: "Building a cardboard house to learn shapes", category: "learning", text: "Help my 6-year-old learn shapes by building a cardboard house together. List the shapes to cut, like squares for walls and a triangle for the roof, and give me 3 questions to ask while we build and decorate it." },
  { id: "learning-893", title: "Story circle game for a family evening", category: "learning", text: "Plan a story circle game for our family evening where each person adds one line to a story. Give me 3 story starters, like [a magic bus / a talking mango], simple rules for young children, and a way to end the story happily in 10 minutes." },
  { id: "learning-894", title: "Making up new endings for old stories", category: "learning", text: "Help my 7-year-old make up new endings for a familiar story like [Cinderella or a Panchatantra tale]. Give me 3 ways to change the ending, questions to spark ideas, and a way to write or draw the new ending together." },
  { id: "learning-895", title: "Playdough lessons for shapes and letters", category: "learning", text: "Teach my 4-year-old shapes and letters using playdough at home. Give me 7 daily activities, like rolling balls, making snakes and stamping letters, and tell me how to keep the playdough soft and the table clean." },
  { id: "learning-896", title: "Teaching honesty to a 6-year-old", category: "learning", text: "Teach my 6-year-old what honesty means using 3 everyday examples from home and school. Give me a short story, a role-play game where my child chooses the honest answer, and the exact words to praise honesty when I see it." },
  { id: "learning-897", title: "Teaching a child to say sorry and mean it", category: "learning", text: "Help my 5-year-old learn to say sorry and mean it after hurting a friend or sibling. Give me a simple 3-step apology, a short story about saying sorry, and what to do when my child says sorry but still feels angry." },
  { id: "learning-898", title: "Daily thank-you habit for a young child", category: "learning", text: "Start a daily thank-you habit with my 5-year-old using one sentence at dinner or bedtime. Give me 7 simple prompts for the week, like thanking [the cook, a teacher, a friend], and a way to make gratitude fun without turning it into a lecture." },
  { id: "learning-899", title: "Teaching kindness to animals at home", category: "learning", text: "Teach my 6-year-old to be kind to animals at home and on the street. Give me 3 simple rules, like giving water to birds and not teasing dogs, a story about kindness to animals, and a daily job my child can do to help." },
  { id: "learning-900", title: "Teaching a child patience while waiting", category: "learning", text: "Help my 5-year-old learn patience while waiting in a queue or for food to be served. Give me 3 waiting games that need no toys, a simple way to explain waiting, and what to say when my child gets restless." },
  { id: "learning-901", title: "Teaching respect for elders in Indian families", category: "learning", text: "Teach my 6-year-old to show respect to elders in our Indian family, like touching feet, greeting politely and listening when elders speak. Give me 3 daily habits, a short story, and gentle words to use when my child forgets." },
  { id: "learning-902", title: "Teaching a child to share food with neighbours", category: "learning", text: "Help my 6-year-old learn to share food with neighbours and friends, like sharing a tiffin or festival sweets. Give me a simple sharing activity, a story about generosity, and words to praise my child when they share happily." },
  { id: "learning-903", title: "Teaching a child to return lost things", category: "learning", text: "Teach my 7-year-old what to do when they find a lost pencil, book or toy that is not theirs. Give me a simple rule to follow, a role-play game, and a story that shows why returning lost things is the right thing to do." },
  { id: "learning-904", title: "Helping a child understand why lying hurts trust", category: "learning", text: "Help my 7-year-old understand why lying breaks trust, using a simple story and everyday examples. Give me a calm way to respond when my child lies, questions that help them tell the truth, and words that praise truth-telling." },
  { id: "learning-905", title: "Teaching courage to a child afraid of the dark", category: "learning", text: "Help my 5-year-old learn courage when they are afraid of the dark. Give me a gentle 5-night plan with a night lamp, a brave-hero story, and a small brave badge my child earns each night they sleep without fear." },
  { id: "learning-906", title: "Teaching a child to care for younger siblings", category: "learning", text: "Teach my 7-year-old to care for a younger brother or sister, like helping with shoes, sharing a book or playing gently. Give me 3 small jobs, a story about big brothers and sisters, and words to praise caring behaviour." },
  { id: "learning-907", title: "Teaching a child to keep promises", category: "learning", text: "Help my 6-year-old learn to keep promises, starting with small ones like returning a borrowed toy. Give me a simple promise chart, a story about keeping your word, and what to say kindly when a promise is broken." },
  { id: "learning-908", title: "Teaching a child to accept losing a game", category: "learning", text: "Help my 6-year-old learn to accept losing a board game without tears or anger. Give me 3 calm phrases to teach, a short game we can play together, and a simple after-game talk that makes losing feel normal and okay." },
  { id: "learning-909", title: "Teaching cleanliness as a daily habit for kids", category: "learning", text: "Teach my 5-year-old cleanliness as a daily habit, like washing hands before eating, brushing teeth and keeping shoes in one place. Give me a morning and night checklist with pictures, and a star chart to track the week." },
  { id: "learning-910", title: "Teaching a child to thank everyday helpers", category: "learning", text: "Help my 6-year-old learn to thank helpers like the milkman, the postman and the school bus driver. Give me 3 simple thank-you actions, a short story about people who help us, and a handmade card idea my child can give." },
  { id: "learning-911", title: "First guitar lessons for a 10-year-old", category: "learning", text: "Give my 10-year-old a first guitar lesson plan for 4 weeks, with 15 minutes of practice a day. Include how to hold the guitar, the first 3 chords, one simple song, and how to keep practice fun without pressure." },
  { id: "learning-912", title: "Learning the keyboard at home for a child", category: "learning", text: "Help my 8-year-old learn the keyboard at home with 15 minutes of practice a day. Give me a 4-week plan with finger positions, the first 5 notes, one simple tune like [a nursery rhyme], and a weekly mini-test that feels like a game." },
  { id: "learning-913", title: "First Carnatic music lessons for a child", category: "learning", text: "Plan first Carnatic music lessons for my 7-year-old, with 2 short sessions a week. Include the first sarali varisai, how to practise voice, one simple song, and tips for parents who do not know Carnatic music themselves." },
  { id: "learning-914", title: "Learning to sing simple bhajans correctly", category: "learning", text: "Help my 8-year-old learn to sing simple bhajans correctly, with clear words and tune. Give me 3 easy bhajans to start with, the meaning of each in one line, and a 10-minute daily practice that keeps my child interested." },
  { id: "learning-915", title: "First drawing class plan for a 7-year-old", category: "learning", text: "Give my 7-year-old a first drawing class plan for one month, with 2 sessions a week at home. Include lines, circles and simple animals, the materials needed, and one finished picture per week to stick on the wall." },
  { id: "learning-916", title: "Learning watercolour painting as a home hobby", category: "learning", text: "Help me learn watercolour painting as a hobby at home, starting from zero. Give me a 4-week plan with one small painting a week, the basic colours and brushes to buy under [₹500], and 3 beginner mistakes to avoid." },
  { id: "learning-917", title: "First sketching plan for a teenager", category: "learning", text: "Give my 13-year-old a first sketching plan for one month, with 20 minutes a day. Include drawing everyday objects, shading basics, one outdoor sketch a week, and a simple way to track improvement without comparing with others." },
  { id: "learning-918", title: "Simple dance steps at home for a child", category: "learning", text: "Teach my 6-year-old 5 simple dance steps at home for a family function. Give me the steps in order, a song to practise with, how to practise 10 minutes a day, and tips to help a shy child perform happily." },
  { id: "learning-919", title: "First Bharatanatyam lessons for a beginner child", category: "learning", text: "Plan first Bharatanatyam lessons for my 6-year-old, with 2 classes a week. Include the basic adavus, how to practise at home for 10 minutes, what to wear, and how to keep a young child interested in a classical dance form." },
  { id: "learning-920", title: "Teaching a teenager to cook rice and dal", category: "learning", text: "Teach my 14-year-old to cook rice and dal from scratch as a first cooking lesson. Give me a safe step-by-step recipe, the utensils needed, how to check if the dal is done, and 3 safety rules for using the stove." },
  { id: "learning-921", title: "First baking lessons for a 12-year-old", category: "learning", text: "Give my 12-year-old a first baking lesson plan for 4 weekends, starting with biscuits and a simple cake. List the ingredients and tools, the steps in order, oven safety rules, and how to decorate the finished cake simply." },
  { id: "learning-922", title: "Teaching a child to stitch a button", category: "learning", text: "Teach my 10-year-old to stitch a button, sew a torn pocket and hem a cloth as useful life skills. Give me the tools needed, step-by-step instructions for each task, and a small practice cloth to learn on first." },
  { id: "learning-923", title: "First knitting plan for a beginner", category: "learning", text: "Give me a first knitting plan for a beginner, with 20 minutes a day for 2 weeks. Include the wool and needles to buy, the first stitch, a simple scarf project, and how to fix a dropped stitch without starting again." },
  { id: "learning-924", title: "Learning chess together as a family hobby", category: "learning", text: "Teach my family to play chess together as a weekend hobby, starting from zero. Give me a 4-week plan, how each piece moves explained simply, one easy opening, and a fun family tournament at the end of the month." },
  { id: "learning-925", title: "First harmonium lessons for a child", category: "learning", text: "Help my 9-year-old learn the harmonium at home, with 15 minutes of practice a day. Give me a 4-week plan with the first notes, how to use the bellows, one simple song, and tips to practise without disturbing the neighbours." },
  { id: "learning-926", title: "Learning simple rangoli as a hobby for kids", category: "learning", text: "Help my 8-year-old learn to make simple rangoli as a hobby for festivals. Give me 5 easy designs, the colours and materials needed, how to practise on paper first, and tips to draw a neat rangoli at the door." },
  { id: "learning-927", title: "First photography hobby plan for a teenager", category: "learning", text: "Give my 14-year-old a first photography hobby plan using a phone camera for one month. Include one theme a week like [flowers, streets, family], 3 rules of good framing, and a way to choose the best 10 photos at the end." },
  { id: "learning-928", title: "First tabla lessons for a beginner child", category: "learning", text: "Help my 10-year-old learn the tabla as a beginner, with 15 minutes of practice a day. Give me a 4-week plan with the basic bols, how to sit and place the hands, one simple rhythm, and how to practise quietly at home." },
  { id: "learning-929", title: "First gardening hobby plan for a child", category: "learning", text: "Give my 6-year-old a first gardening hobby plan using one pot and easy seeds like methi or coriander. Include sowing, watering and watching growth, a weekly drawing of the plant, and what to do when the first leaves appear." },
  { id: "learning-930", title: "Learning calligraphy as a relaxing hobby", category: "learning", text: "Help me learn calligraphy as a relaxing hobby, starting from zero. Give me a 4-week plan with the pen and paper to buy, the basic strokes, one alphabet a week, and a simple name card project to finish at the end." },
  { id: "learning-931", title: "Helping a child with homework without doing it", category: "learning", text: "Help me support my child's homework without doing it for them. Give me 5 guiding questions to ask, a routine for homework time, and what to do when my child is stuck for more than 10 minutes on one question." },
  { id: "learning-932", title: "Setting up a small study corner at home", category: "learning", text: "Help me set up a small study corner at home for my 8-year-old using a table, a lamp and a few boxes. List what to keep in it, what to remove, and a simple rule for study time that my child helps to make." },
  { id: "learning-933", title: "Teaching a child to read a clock", category: "learning", text: "Teach my 6-year-old to read a clock with hours and half-hours using a toy clock or a wall clock. Give me a 1-week plan, 3 games like [what time do we eat lunch], and a way to test without making it feel like an exam." },
  { id: "learning-934", title: "Helping a child who hates maths homework", category: "learning", text: "Help my 9-year-old who hates maths homework to feel less scared of numbers. Give me 3 ways to start homework calmly, one game that uses maths in daily life, and words to say when my child says [I cannot do maths]." },
  { id: "learning-935", title: "Read-aloud habit for 15 minutes a day", category: "learning", text: "Start a 15-minute read-aloud habit with my 7-year-old every evening. Suggest 7 books or stories for the week, how to take turns reading, 2 questions to ask after each story, and how to keep it fun on busy days." },
  { id: "learning-936", title: "Helping a child prepare for a school oral test", category: "learning", text: "Help my 10-year-old prepare for a school oral test in one week. Give me a daily plan with reading aloud, answering questions, and a mock test at home, plus tips to speak slowly and clearly in front of the class." },
  { id: "learning-937", title: "Teaching a child to pack their school bag alone", category: "learning", text: "Teach my 6-year-old to pack their school bag alone the night before school. Give me a picture checklist, the order to pack books, tiffin and water bottle, and a morning check game that makes it fun." },
  { id: "learning-938", title: "Teaching tables through daily routines", category: "learning", text: "Help my 8-year-old learn multiplication tables through daily routines like setting the table and counting pairs of shoes. Give me a 2-week plan with one table a week, a chant to repeat, and a quick quiz during dinner." },
  { id: "learning-939", title: "Guiding a child's first school project", category: "learning", text: "Help me guide my 9-year-old through their first school project on [a topic] without doing the work myself. Give me a 5-day plan, what materials to collect, how to help with research, and how to let my child present it in their own words." },
  { id: "learning-940", title: "Helping a slow reader read better", category: "learning", text: "Help my 8-year-old who reads slowly to read better, with 10 minutes of practice a day. Give me a 4-week plan with easy books, finger-tracking, reading aloud together, and a way to celebrate small progress each week." },
  { id: "learning-941", title: "Teaching a child to ask for help in class", category: "learning", text: "Teach my 7-year-old to ask for help in class when they do not understand a lesson. Give me the exact words to practise, a role-play game at home, and a way to praise my child the first time they raise their hand." },
  { id: "learning-942", title: "Learning from a museum visit with a child", category: "learning", text: "Help my 9-year-old learn from a museum visit in our city, like [a science museum or a local museum]. Give me 5 things to look for, 3 questions to ask, and a drawing or note my child can make after the visit." },
  { id: "learning-943", title: "Teaching a child to use a library card", category: "learning", text: "Teach my 8-year-old to use a library card and borrow books on their own. Explain how to choose a book, how to return it on time, and give me a simple reading log my child can fill after finishing each book." },
  { id: "learning-944", title: "Revising for a class test in one evening", category: "learning", text: "Help my 10-year-old revise for a class test in one evening without panic. Give me a 2-hour plan with reading notes, writing key points, one quick self-test, and a calm bedtime so my child sleeps well before the test." },
  { id: "learning-945", title: "Teaching a child to write a daily diary entry", category: "learning", text: "Teach my 8-year-old to write one diary entry a day in 5 lines. Give me 7 simple prompts for the week, like [the best part of my day], and a way to check spelling gently without correcting every word my child writes." },
  { id: "learning-946", title: "Building good handwriting habits in a child", category: "learning", text: "Help my 7-year-old build good handwriting habits with 10 minutes of practice a day. Give me a 2-week plan with letter formation, spacing and sitting posture, and a simple way to check progress without making it a punishment." },
  { id: "learning-947", title: "Teaching a child to plan tomorrows tasks", category: "learning", text: "Teach my 9-year-old to plan tomorrows tasks using a simple list with 3 things to do. Give me a nightly routine, how to tick off finished tasks, and what to do when my child forgets or leaves a task undone." },
  { id: "learning-948", title: "Helping two children study together at home", category: "learning", text: "Help my two children study together at home without fighting over the table or the pencil. Give me a shared timetable, clear turns for asking questions, and a teamwork reward they earn together at the end of the week." },
  { id: "learning-949", title: "Teaching a child to check their own homework", category: "learning", text: "Teach my 9-year-old to check their own homework before showing it to me. Give me a simple checklist for spelling, sums and handwriting, and a routine where my child finds and fixes one mistake by themselves." },
  { id: "learning-950", title: "Helping a child learn from test mistakes", category: "learning", text: "Help my 10-year-old learn from mistakes in a test instead of feeling sad about marks. Give me 3 calm questions to ask, a way to sort mistakes into silly errors and real doubts, and a plan to fix the doubts before the next test." },
  { id: "learning-951", title: "Returning to study after a 10-year gap", category: "learning", text: "Help me return to studies after a 10-year gap, starting with 30 minutes a day. Give me a 4-week gentle plan to rebuild reading, writing and focus, a way to choose what to study first, and tips to stay motivated on tired days." },
  { id: "learning-952", title: "Improving English for a job interview as an adult", category: "learning", text: "Help me improve my English for a job interview as an adult who studied in [Tamil / Hindi] medium. Give me a 3-week plan with daily speaking practice, 10 common interview answers to prepare, and a mock interview I can practise at home." },
  { id: "learning-953", title: "Night study plan for a working mother", category: "learning", text: "Make a night study plan for a working mother who has only 9 to 10 pm free after housework. Give me a realistic weekly plan, how to revise in short bursts, and a way to track progress without staying up late every night." },
  { id: "learning-954", title: "Learning to read and write as an adult beginner", category: "learning", text: "Help an adult beginner in my family learn to read and write in [Tamil / Hindi / English] from zero. Give me a 4-week plan with one letter a day, tracing practice, and simple words like names of family members and common food items." },
  { id: "learning-955", title: "Planning an open university degree at 35", category: "learning", text: "Help me plan an open university degree at 35 while working full time. Give me a realistic 3-year view, how many hours to study each week, how to choose subjects, and what to check before paying any fees." },
  { id: "learning-956", title: "Basic accounting for a small shop owner", category: "learning", text: "Teach me basic accounting for my small shop, like recording daily sales, expenses and profit in a notebook. Give me a simple daily format, a weekly check, and 3 common mistakes small shop owners make with money records." },
  { id: "learning-957", title: "Upskilling plan for a homemaker returning to work", category: "learning", text: "Make an upskilling plan for a homemaker returning to work after 5 years at home. Help me pick one skill to learn in 3 months, give a daily 1-hour plan, and suggest how to show the new skill in a simple resume." },
  { id: "learning-958", title: "Learning to use a computer at 40 for office work", category: "learning", text: "Help me learn to use a computer at 40 for office work, starting from switching it on. Give me a 4-week plan with typing, email, and making a simple document, plus one practice task per week that matches real office work." },
  { id: "learning-959", title: "Preparing for a government exam while working full time", category: "learning", text: "Help me prepare for a government job exam while working a full-time job, with only 2 hours a day. Give me a 6-month plan, which subjects to study first, how to use weekends for mock tests, and a way to revise without burning out." },
  { id: "learning-960", title: "Learning a new skill in 30 minutes a day as an adult", category: "learning", text: "Help me learn a new skill in 30 minutes a day as a busy adult, choosing from [typing, spoken English, basic Excel]. Give me a 30-day plan, a way to measure progress each week, and tips to keep going on days when work runs late." },
  { id: "learning-961", title: "Managing a distance-learning course while working", category: "learning", text: "Help me manage a distance-learning course while working, with classes only on weekends. Give me a weekly plan, how to keep notes, when to submit assignments, and a way to stay in touch with teachers and classmates." },
  { id: "learning-962", title: "Speaking confidently in office meetings", category: "learning", text: "Help me speak confidently in office meetings as an adult who feels nervous in English. Give me a 3-week plan with daily 10-minute speaking practice, 5 useful phrases for meetings, and a way to prepare one point before each meeting." },
  { id: "learning-963", title: "Finishing Class 12 privately as an adult learner", category: "learning", text: "Help me plan to finish Class 12 privately as an adult learner in India. Give me the steps to register, a 6-month study plan for [subjects], how to arrange exam preparation, and what documents to keep ready before applying." },
  { id: "learning-964", title: "Learning digital payments safely as an adult", category: "learning", text: "Help an adult beginner learn digital payments safely, starting with checking balance and sending small amounts. Give me a step-by-step guide, 5 safety rules, and what to do if a payment fails or goes to the wrong person." },
  { id: "learning-965", title: "Choosing a short course after a career break", category: "learning", text: "Help me choose a short course after a career break of 3 years, comparing [a computer course, a spoken English course, a tailoring course]. Give me 5 questions to ask before joining, how to check if the course is genuine, and a way to compare fees." },
  { id: "learning-966", title: "Learning WhatsApp video calls at 65", category: "learning", text: "Help my 65-year-old father learn to make WhatsApp video calls to family on his own. Give me a step-by-step guide with big clear steps, one practice call a day, and a printed cheat sheet he can keep near his phone." },
  { id: "learning-967", title: "Brain games to keep memory sharp after 60", category: "learning", text: "Give me 7 simple brain games to keep memory sharp after 60, using a newspaper, cards and everyday objects. For each game, explain how to play in 10 minutes, what it helps with, and how to play it with a friend or grandchild." },
  { id: "learning-968", title: "Reading the newspaper in English at 70", category: "learning", text: "Help my 70-year-old mother learn to read the newspaper in English, starting with headlines and short news. Give me a 4-week plan with 15 minutes a day, a small notebook for new words, and a way to discuss one news story a day." },
  { id: "learning-969", title: "Starting painting after retirement at 62", category: "learning", text: "Help my retired father start learning painting at 62, with no experience at all. Give me a 4-week beginner plan, the basic materials to buy, one small painting a week, and tips to enjoy the process without worrying about perfection." },
  { id: "learning-970", title: "Ordering groceries online safely at 60", category: "learning", text: "Help my 60-year-old mother learn to order groceries online safely, step by step. Give me a guide for choosing items, checking the bill, paying on delivery, and what to do if the wrong item arrives or the order is late." },
  { id: "learning-971", title: "Teaching grandparents to use UPI safely", category: "learning", text: "Teach my grandparents to use UPI safely for paying the milkman and the vegetable seller. Give me 5 simple safety rules, how to check the name before paying, and what to do if they receive a strange call asking for money." },
  { id: "learning-972", title: "Learning a new language after retirement for fun", category: "learning", text: "Help my retired uncle learn a new language, [French / Spanish / Sanskrit], for fun at 65. Give me a 3-month plan with 15 minutes a day, 5 useful sentences a week, and a fun way to practise with family members." },
  { id: "learning-973", title: "Learning simple yoga from videos at 65", category: "learning", text: "Help my 65-year-old mother learn simple yoga from videos at home, safely and slowly. Give me a 4-week plan with 10-minute sessions, which poses to start with, safety rules for knees and back, and when to stop and rest." },
  { id: "learning-974", title: "Writing life memories as a family book at 65", category: "learning", text: "Help my 65-year-old grandfather write his life memories as a family book. Give me a plan with one story a week, questions to ask him, how to record his voice, and a simple way to print the stories for the family." },
  { id: "learning-975", title: "Learning smartphone photography at 70", category: "learning", text: "Help my 70-year-old father learn to use his smartphone camera to take clear photos of family functions. Give me a simple guide with big steps, how to hold the phone steady, and how to find and share the photos afterwards." },
  { id: "learning-976", title: "Helping a Class 9 child discover their interests", category: "learning", text: "Help my Class 9 child discover their interests before choosing subjects. Give me 10 simple activities to try over a month, like [drawing, coding, gardening, cooking], and a way to note what my child enjoys and does well." },
  { id: "learning-977", title: "Career paths for a child who loves drawing", category: "learning", text: "Help my child who loves drawing explore careers in art and design after school. List 5 career paths, what each one does daily, which subjects to choose in Class 11, and one small step to try this year." },
  { id: "learning-978", title: "Career options for a child good at maths", category: "learning", text: "Help my child who is good at maths but unsure about a career explore 5 options beyond engineering. For each option, say what the work is like, which subjects help, and one person my child can talk to for real advice." },
  { id: "learning-979", title: "What to do after Class 10 for a computer lover", category: "learning", text: "Help my Class 10 child who loves computers decide what to do next. Compare 3 paths — science with computers, a diploma, and a vocational course — with what each leads to, and 5 questions to ask before choosing." },
  { id: "learning-980", title: "Choosing between science and commerce in Class 11", category: "learning", text: "Help my Class 10 child choose between science and commerce for Class 11. Give me a simple comparison of both streams, the careers each opens, and 5 questions my child can answer to see which stream fits better." },
  { id: "learning-981", title: "Sports careers for a school student in India", category: "learning", text: "Help my school-going child who loves sports explore careers in sports in India. List 5 paths like coaching, sports medicine and sports management, what each needs, and how to balance sports practice with studies." },
  { id: "learning-982", title: "Food careers for a child who loves cooking", category: "learning", text: "Help my child who loves cooking explore food careers after school. List 5 paths like chef, baker, food writer and caterer, what each one does, which course helps, and one dish my child can master this year." },
  { id: "learning-983", title: "Planning a creative career while in Class 11", category: "learning", text: "Help my Class 11 child plan for a creative career in [writing / music / design] while finishing school. Give me a weekly plan that balances board exam study with creative practice, and one portfolio piece to make each month." },
  { id: "learning-984", title: "Careers for a child who loves animals", category: "learning", text: "Help my child who loves animals explore careers like veterinary doctor, wildlife worker and pet care. For each path, say what the work is like, which subjects to choose, and one way to gain experience while still in school." },
  { id: "learning-985", title: "Career talk for a child interested in teaching", category: "learning", text: "Help my child who is interested in teaching explore a career in education. Explain the paths to become a school teacher, what subjects and degrees are needed, and how my child can start by tutoring younger children at home." },
  { id: "learning-986", title: "Planning to join the armed forces after Class 10", category: "learning", text: "Help my child who wants to join the armed forces plan the path after Class 10. Explain the NDA route and other entries in simple words, the subjects and fitness needed, and a weekly preparation plan my child can follow." },
  { id: "learning-987", title: "Music and dance careers for school students", category: "learning", text: "Help my child explore careers in music and dance in India, beyond performing on stage. List 5 paths like teaching, composing and music therapy, what each needs, and how to build skills while finishing school." },
  { id: "learning-988", title: "Farming and food careers for school students", category: "learning", text: "Help my child who loves farming and food explore careers in agriculture and food business. List 5 paths like farming, food processing and agri-business, what each one does, and which subjects to choose in Class 11." },
  { id: "learning-989", title: "Helping careers for a child who loves helping people", category: "learning", text: "Help my child who loves helping people explore careers like nursing, social work and counselling. For each path, say what the daily work is like, which subjects help, and one volunteering idea my child can try this year." },
  { id: "learning-990", title: "Talking to a Class 12 child about careers calmly", category: "learning", text: "Help me talk to my Class 12 child about career choices without pressure or arguments. Give me 5 calm questions to ask, how to listen without judging, and a way to shortlist 3 options together by the end of the week." },
  { id: "learning-991", title: "First steps to study abroad after Class 12", category: "learning", text: "Help my child take the first steps to study abroad after Class 12. Give me a timeline starting 12 months before, the first 5 things to do, and a simple checklist to track applications, tests and documents." },
  { id: "learning-992", title: "Choosing a country for studying abroad on a budget", category: "learning", text: "Help my child choose a country for studying abroad on a tight budget. Compare [Canada, Germany, the UK] on fees, living costs and part-time work rules in simple words, and give 5 questions to decide which country fits best." },
  { id: "learning-993", title: "Preparing for IELTS as an Indian student", category: "learning", text: "Help my child prepare for IELTS as an Indian student aiming for a score of [6.5 / 7]. Give me an 8-week plan with daily practice for listening, reading, writing and speaking, plus one mock test each weekend." },
  { id: "learning-994", title: "Writing a statement of purpose for a foreign university", category: "learning", text: "Help my child write a statement of purpose for a foreign university application. Give me a simple structure with 4 paragraphs, what to write in each, and 5 common mistakes Indian students should avoid." },
  { id: "learning-995", title: "Budget plan for a child studying abroad", category: "learning", text: "Make a budget plan for my child studying abroad from India, covering fees, living costs, travel and emergencies. Give me a monthly estimate format, ways to save before leaving, and 3 costs families often forget to plan for." },
  { id: "learning-996", title: "Scholarship search for Indian students going abroad", category: "learning", text: "Help my child search for scholarships for Indian students going abroad. List where to look, the documents usually needed, how to check if a scholarship is genuine, and a timeline for applying to 5 scholarships." },
  { id: "learning-997", title: "Preparing a student for life in a foreign hostel", category: "learning", text: "Help my child prepare for life in a foreign hostel, from cooking simple food to managing laundry and money. Give me a 4-week preparation plan, a packing list of essentials, and 5 daily habits for living independently." },
  { id: "learning-998", title: "Documents checklist for a study-abroad application", category: "learning", text: "Make a documents checklist for my child's study-abroad application, including passport, marksheets, test scores and financial papers. Explain each document in one line, when to arrange it, and how to keep safe copies." },
  { id: "learning-999", title: "Preparing a student for a university interview abroad", category: "learning", text: "Help my child prepare for a university interview for studying abroad. Give me 10 likely questions, sample answers in simple English, and a mock interview plan we can practise at home for 3 days." },
  { id: "learning-1000", title: "Comparing study-abroad consultants before paying", category: "learning", text: "Help me compare study-abroad consultants before paying any fees. Give me 10 questions to ask each consultant, warning signs of a fake promise, and a simple table to compare fees, services and success stories of 3 consultants." },
  { id: "learning-1001", title: "Learn Indian sign language greetings for beginners", category: "learning", text: "Teach me five simple greetings in Indian Sign Language, such as hello, thank you, please, sorry, and good morning. Show the hand shape for each one in simple words, give a short practice sentence, and suggest a daily five-minute routine to remember them. Use [name of the person I am greeting] in one example." },
  { id: "learning-1002", title: "Read a bus timetable to plan a trip", category: "learning", text: "Explain how to read a bus timetable for [my town] in simple steps. Show me how to find the route number, the starting point, the stop nearest my home, and the arrival time. Then help me plan a trip to [destination] that leaves after [time] and arrives before [time]." },
  { id: "learning-1003", title: "Fold a paper boat and a paper plane", category: "learning", text: "Teach me to fold a paper boat and a paper plane using one sheet of paper each. Give clear steps for every fold, tips to keep the edges straight, and a simple test to see which plane flies farther. Use paper from [size] and try the boat in a tub of water." },
  { id: "learning-1004", title: "Learn Kathak dance basics at home", category: "learning", text: "Teach me Kathak dance basics at home in simple steps. Start with the basic footwork, hand positions, and a slow spin, then add a short sequence I can practise to music. Give a ten-minute daily routine, safety tips for bare feet, and a way to check my rhythm using [song name]." },
  { id: "learning-1005", title: "Write a limerick poem that makes children laugh", category: "learning", text: "Teach me to write a funny limerick poem in five lines with a clear rhythm. Use [a funny animal] and [a place in India] as the subject, give two example limericks, then help me write my own. Keep the words simple, the joke kind, and the last line surprising." },
  { id: "learning-1006", title: "Learn abacus mental maths for children", category: "learning", text: "Teach a child aged [age] to use an abacus for simple addition and subtraction. Explain the beads, the value of each column, and how to move beads slowly at first. Give five practice sums, a daily five-minute game, and tips to move from the abacus to mental maths." },
  { id: "learning-1007", title: "Understand how a refrigerator keeps food cold", category: "learning", text: "Explain in simple words how a refrigerator keeps food cold, using [my fridge at home] as the example. Describe the gas, the cooling coils, and why the back feels warm. Add three tips to store food safely, and explain why we should not keep the door open long." },
  { id: "learning-1008", title: "Learn to use a microscope for home science", category: "learning", text: "Teach me to use a simple microscope at home to look at [an onion peel or a leaf]. Explain how to place the slide, focus slowly, and draw what I see. Give safety rules, three easy things to observe first, and questions to note in my science diary." },
  { id: "learning-1009", title: "Learn chess openings for a beginner", category: "learning", text: "Teach me two simple chess openings for a beginner, one for White and one for Black. Explain the first five moves of each, what each move tries to do, and the common mistake to avoid. Then give a short practice game using [opening name] so I can try it." },
  { id: "learning-1010", title: "Grow a herb garden on a windowsill", category: "learning", text: "Help me grow a small herb garden on a windowsill in [my city]. Suggest three easy herbs, such as tulsi, mint, and coriander, and explain the pot size, soil, sunlight, and watering for each. Give a weekly care chart and ideas to use the herbs in cooking." },
  { id: "learning-1011", title: "Learn Indian folk tales from five states", category: "learning", text: "Tell me one short folk tale each from [five Indian states], in simple words a child aged [age] can enjoy. For each tale, give the hero, the lesson, and one question to discuss after reading. Keep every tale under two minutes to tell aloud." },
  { id: "learning-1012", title: "Learn to tie useful knots for daily life", category: "learning", text: "Teach me five useful knots for daily life, such as tying a parcel, a shoelace bow that stays, a clothesline knot, and a knot for a tent rope. Give slow steps for each knot, say when to use it, and suggest a practice rope of [length] to learn with." },
  { id: "learning-1013", title: "Learn the basics of Braille reading and writing", category: "learning", text: "Teach me the basics of Braille in simple words. Explain the six-dot cell, how letters are formed, and how to read three short words by touch. Suggest a way to practise with raised dots at home, and give a kind introduction to how blind readers use Braille daily." },
  { id: "learning-1014", title: "Learn to read a weather map for school", category: "learning", text: "Teach me to read a simple weather map for [my state] for a school project. Explain the symbols for sun, rain, clouds, and wind, and how to find the temperature for my town. Then help me write three lines predicting tomorrow's weather from today's map." },
  { id: "learning-1015", title: "Make natural colours from flowers and leaves", category: "learning", text: "Teach me to make safe natural colours from flowers and leaves at home, using marigold, beetroot, and spinach. Explain how to crush, soak, and strain each one, what cloth or paper to test it on, and how to store the colours. Use adult help for [boiling step]." },
  { id: "learning-1016", title: "Learn about the life of a honeybee", category: "learning", text: "Teach me about the life of a honeybee in simple words. Explain the queen, the worker bees, and the drones, how bees find flowers, and how honey is made in the hive. Add three facts about why bees help farmers in [my state], and a drawing activity." },
  { id: "learning-1017", title: "Learn to play carrom with family rules", category: "learning", text: "Teach my family to play carrom with simple rules we can all agree on. Explain the board, the striker, the coins, and how to score, then settle common arguments about fouls and the queen. Give a fair turn order for [number] players and a first-game practice plan." },
  { id: "learning-1018", title: "Write a letter to your future self", category: "learning", text: "Help me write a letter to my future self to open in [one year]. Guide me to write about my hopes, my current favourite things, and one goal I want to reach. Keep it warm and honest, add three questions for my future self, and suggest a safe place to keep it." },
  { id: "learning-1019", title: "Learn about Indian handloom weaving traditions", category: "learning", text: "Teach me about Indian handloom weaving in simple words, using [a weave from my state] as the main example. Explain the loom, the yarn, and how a pattern is made, then name two other famous weaves and where they come from. End with a visit plan for a local weaver." },
  { id: "learning-1020", title: "Identify common birds in your neighbourhood", category: "learning", text: "Help me identify five common birds in my neighbourhood in [my city]. For each bird, give its colour, size, call, and where it is usually seen. Suggest a morning birdwatch routine, a simple notebook format, and rules to watch birds quietly without disturbing them." },
  { id: "learning-1021", title: "Make a sundial and tell time by the sun", category: "learning", text: "Teach me to make a simple sundial using a stick, a paper plate, and a sunny spot in [my home]. Explain how to mark the hours, why the shadow moves, and how to test it at [three times of day]. Add a note on why it works only on sunny days." },
  { id: "learning-1022", title: "Test soil for a kitchen garden simply", category: "learning", text: "Teach me to test soil for a kitchen garden at home in simple steps. Show a squeeze test for clay and sand, a jar test for soil layers, and how to tell if the soil holds water well. Then suggest which vegetables grow best in [my soil type] this season." },
  { id: "learning-1023", title: "Create a family tree with stories", category: "learning", text: "Help me create a family tree that includes a short story for each person, not just names and dates. Suggest five questions to ask [an elder in my family], how to record their answers, and how to draw the tree on one large sheet with photos and memories." },
  { id: "learning-1024", title: "Use a compass and map on a trek", category: "learning", text: "Teach me to use a compass and a printed map on a short trek near [place]. Explain how to hold the compass flat, find north, match the map to the land, and follow a simple route. Add safety rules, what to carry, and what to do if I lose the path." },
  { id: "learning-1025", title: "Bake bread at home for beginners", category: "learning", text: "Teach me to bake a simple loaf of bread at home with [flour type], yeast, water, and salt. Give clear steps for mixing, kneading, resting, and baking, plus signs that the dough is ready. Add tips to keep the bread soft and a safe way to use the oven." },
];
